{"content": "//! proto schema 解析(声明级, 仅提取 registry 所需的自定义 option 语义).
//!
//! 不需要 protoc/prost: registry 只需要每文件独立的声明级信息, 无跨文件
//! import 解析需求。语法全集已核实(见 docs/21-rust.md):
//! proto3、`package`、`import [public]`、`option (ext).field = value;`、
//! message/enum(无 oneof/extend, 少量 `reserved`)、字段、map/repeated、
//! `//` 与 `/* */` 注释、CRLF。

pub mod parse;

pub use parse::{
    DataLoaderOpt, FileType, ParsedEnum, ParsedField, ParsedFile, ParsedMessage, parse_file,
};

/// 扫描目录下全部待解析的 proto 文件(DataDefine 全量 + 根目录共享文件).
pub fn collect_proto_files(proto_root: &std::path::Path) -> Vec<std::path::PathBuf> {
    let mut files: Vec<std::path::PathBuf> = Vec::new();
    let data_define = proto_root.join("DataDefine");
    if data_define.is_dir() {
        let mut inner: Vec<std::path::PathBuf> = walk_protos(&data_define);
        inner.sort();
        files.extend(inner);
    }
    for extra in ["enum.proto", "options_extension.proto"] {
        let p = proto_root.join(extra);
        if p.is_file() {
            files.push(p);
        }
    }
    files
}

fn walk_protos(dir: &std::path::Path) -> Vec<std::path::PathBuf> {
    let mut out = Vec::new();
    if let Ok(rd) = std::fs::read_dir(dir) {
        for entry in rd.flatten() {
            let path = entry.path();
            if path.is_dir() {
                out.extend(walk_protos(&path));
            } else if path.extension().is_some_and(|e| e == "proto") {
                out.push(path);
            }
        }
    }
    out
}
