{"content": "//! 手写 proto 词法/语法解析器(容错, 只收集 registry 需要的语义).
//!
//! 解析策略:
//! - 词法: 标识符 / 字符串(双引号+转义) / 整数 / 符号(含 `.`)
//! - 语法: 顶层 `syntax/package/import/option/message/enum` 语句;
//!   message 内字段/嵌套 message/enum/reserved/option;
//!   不认识或不需要的语句按 `;` 或配对 `{}` 粒度跳过(容错)。
//! - 收集: `(file_type) = STREAMING`、`(data_loader).load_path/is_single_file`、
//!   `(super_field_name)`、`(cli_index_field_name)/(svr_index_field_name)`、
//!   字段 `(cli_field_attributes)` 与 `(map_key_enum_type)`、枚举值。

use std::fmt;

/// 文件级 `option (file_type)` 取值(只关心是否 STREAMING).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FileType {
    DataDefine,
    Streaming,
}

/// message 级 `option (data_loader)`(点式聚合选项).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct DataLoaderOpt {
    pub load_path: String,
    pub is_single_file: bool,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct MessageOpts {
    pub data_loader: Option<DataLoaderOpt>,
    pub super_field_name: Option<String>,
    pub cli_index_field_name: Option<String>,
    pub svr_index_field_name: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedField {
    pub name: String,
    pub is_repeated: bool,
    pub is_map: bool,
    pub cli_field_attributes: Option<String>,
    pub map_key_enum_type: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedMessage {
    pub full_name: String,
    pub opts: MessageOpts,
    pub fields: Vec<ParsedField>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedEnum {
    pub full_name: String,
    /// (值名, 数值) 列表, 按声明序.
    pub values: Vec<(String, i64)>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParsedFile {
    pub package: String,
    pub file_type: Option<FileType>,
    /// 顶层 message(与 Python 端一致: 嵌套 message 不进入 registry 索引).
    pub messages: Vec<ParsedMessage>,
    /// 顶层 enum.
    pub enums: Vec<ParsedEnum>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseError {
    pub message: String,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl std::error::Error for ParseError {}

// =====================================================================
// 词法
// =====================================================================

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Ident(String),
    Str(String),
    Num(i64),
    Sym(char),
}

struct Lexer {
    chars: Vec<char>,
    pos: usize,
}

impl Lexer {
    fn new(text: &str) -> Self {
        // 去 BOM(数据中未见, 防御性处理)
        let text = text.strip_prefix('\u{feff}').unwrap_or(text);
        Lexer { chars: text.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_trivia(&mut self) {
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.pos += 1;
                }
                Some('/') => {
                    if self.chars.get(self.pos + 1) == Some(&'/') {
                        while let Some(c) = self.peek() {
                            if c == '\n' {
                                break;
                            }
                            self.pos += 1;
                        }
                    } else if self.chars.get(self.pos + 1) == Some(&'*') {
                        self.pos += 2;
                        loop {
                            match self.peek() {
                                None => break,
                                Some('*') if self.chars.get(self.pos + 1) == Some(&'/') => {
                                    self.pos += 2;
                                    break;
                                }
                                Some(_) => self.pos += 1,
                            }
                        }
                    } else {
                        return;
                    }
                }
                _ => return,
            }
        }
    }

    fn next_token(&mut self) -> Result<Option<Tok>, ParseError> {
        self.skip_trivia();
        let c = match self.peek() {
            None => return Ok(None),
            Some(c) => c,
        };
        if c.is_ascii_alphabetic() || c == '_' {
            let mut s = String::new();
            while let Some(c) = self.peek() {
                if c.is_ascii_alphanumeric() || c == '_' {
                    s.push(c);
                    self.pos += 1;
                } else {
                    break;
                }
            }
            return Ok(Some(Tok::Ident(s)));
        }
        if c.is_ascii_digit()
            || (c == '-'
                && self.chars.get(self.pos + 1).is_some_and(|d| d.is_ascii_digit()))
        {
            let mut s = String::new();
            if c == '-' {
                s.push('-');
                self.pos += 1;
            }
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.pos += 1;
                } else {
                    break;
                }
            }
            let n: i64 = s.parse().map_err(|_| ParseError {
                message: format!("bad number literal: {s}"),
            })?;
            return Ok(Some(Tok::Num(n)));
        }
        if c == '"' {
            self.pos += 1;
            let mut s = String::new();
            loop {
                match self.bump() {
                    None => {
                        return Err(ParseError { message: "unterminated string".into() });
                    }
                    Some('"') => break,
                    Some('\\') => match self.bump() {
                        None => return Err(ParseError { message: "unterminated escape".into() }),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('\\') => s.push('\\'),
                        Some('"') => s.push('"'),
                        Some('\'') => s.push('\''),
                        Some('0') => s.push('\0'),
                        Some(other) => {
                            // 未知转义按字面保留(容错)
                            s.push('\\');
                            s.push(other);
                        }
                    },
                    Some(ch) => s.push(ch),
                }
            }
            return Ok(Some(Tok::Str(s)));
        }
        if "{}[]()=;,.<>".contains(c) {
            self.pos += 1;
            return Ok(Some(Tok::Sym(c)));
        }
        Err(ParseError { message: format!("unexpected char {c:?}") })
    }
}

// =====================================================================
// 语法
// =====================================================================

struct Parser {
    lex: Lexer,
    /// 预读一个 token(用于 peek).
    pending: Option<Option<Tok>>,
}

impl Parser {
    fn new(text: &str) -> Self {
        Parser { lex: Lexer::new(text), pending: None }
    }

    fn peek(&mut self) -> Result<Option<Tok>, ParseError> {
        if self.pending.is_none() {
            self.pending = Some(self.lex.next_token()?);
        }
        Ok(self.pending.clone().unwrap())
    }

    fn next(&mut self) -> Result<Option<Tok>, ParseError> {
        if let Some(t) = self.pending.take() {
            return Ok(t);
        }
        self.lex.next_token()
    }

    fn expect_sym(&mut self, s: char) -> Result<(), ParseError> {
        match self.next()? {
            Some(Tok::Sym(c)) if c == s => Ok(()),
            other => Err(ParseError { message: format!("expected '{s}', got {other:?}") }),
        }
    }

    fn expect_ident(&mut self) -> Result<String, ParseError> {
        match self.next()? {
            Some(Tok::Ident(s)) => Ok(s),
            other => Err(ParseError { message: format!("expected ident, got {other:?}") }),
        }
    }

    fn expect_str(&mut self) -> Result<String, ParseError> {
        match self.next()? {
            Some(Tok::Str(s)) => Ok(s),
            other => Err(ParseError { message: format!("expected string, got {other:?}") }),
        }
    }

    /// 读取一个带点标识符 `a.b.c`.
    fn dotted_ident(&mut self) -> Result<String, ParseError> {
        let mut name = self.expect_ident()?;
        while self.peek()? == Some(Tok::Sym('.')) {
            self.next()?;
            name.push('.');
            name.push_str(&self.expect_ident()?);
        }
        Ok(name)
    }

    /// 读取一个值 token: 字符串 / 数字 / 标识符 / 负数.
    fn value(&mut self) -> Result<Tok, ParseError> {
        match self.peek()? {
            Some(Tok::Sym('-')) => {
                self.next()?;
                match self.next()? {
                    Some(Tok::Num(n)) => Ok(Tok::Num(-n)),
                    other => {
                        Err(ParseError { message: format!("expected number after '-', got {other:?}") })
                    }
                }
            }
            _ => self.next().map(|t| t.unwrap_or(Tok::Sym(';'))),
        }
    }

    /// 跳过一条不认识的语句: 到 `;` 或配对 `{}` 结束.
    fn skip_statement(&mut self) -> Result<(), ParseError> {
        loop {
            match self.next()? {
                None => return Ok(()),
                Some(Tok::Sym(';')) => return Ok(()),
                Some(Tok::Sym('{')) => self.skip_balanced()?,
                Some(Tok::Sym('}')) => return Ok(()),
                Some(_) => {}
            }
        }
    }

    /// 跳过配对花括号块(前置 `{` 已消费).
    fn skip_balanced(&mut self) -> Result<(), ParseError> {
        let mut depth = 1usize;
        while depth > 0 {
            match self.next()? {
                None => return Ok(()),
                Some(Tok::Sym('{')) => depth += 1,
                Some(Tok::Sym('}')) => depth -= 1,
                Some(_) => {}
            }
        }
        Ok(())
    }

    /// 解析 `option NAME = VALUE;`(NAME 可为 `(ext)` / `(ext).field` / 普通名).
    /// 返回 (扩展名, 子字段, 值); 普通 option(无扩展)返回 None.
    fn option_statement(&mut self) -> Result<Option<(String, Option<String>, Tok)>, ParseError> {
        // 前置 'option' 已消费
        let name = match self.peek()? {
            Some(Tok::Sym('(')) => {
                self.next()?;
                let ext = self.dotted_ident()?;
                self.expect_sym(')')?;
                let mut sub = None;
                if self.peek()? == Some(Tok::Sym('.')) {
                    self.next()?;
                    sub = Some(self.expect_ident()?);
                }
                (ext, sub)
            }
            Some(Tok::Ident(_)) => {
                self.dotted_ident()?;
                (String::new(), None)
            }
            other => {
                return Err(ParseError { message: format!("bad option name: {other:?}") });
            }
        };
        self.expect_sym('=')?;
        let value = self.value()?;
        self.expect_sym(';')?;
        if name.0.is_empty() {
            Ok(None)
        } else {
            Ok(Some((name.0, name.1, value)))
        }
    }

    /// 解析字段(类型名已由调用方消费; `map<...>` 头部已消费).
    fn field(&mut self, is_repeated: bool, is_map: bool) -> Result<ParsedField, ParseError> {
        let name = self.expect_ident()?;
        self.expect_sym('=')?;
        self.value()?; // field number
        let mut cli_field_attributes = None;
        let mut map_key_enum_type = None;
        if self.peek()? == Some(Tok::Sym('[')) {
            self.next()?;
            loop {
                if self.peek()? == Some(Tok::Sym('(')) {
                    self.next()?;
                    let ext = self.dotted_ident()?;
                    self.expect_sym(')')?;
                    let mut sub = String::new();
                    if self.peek()? == Some(Tok::Sym('.')) {
                        self.next()?;
                        sub = self.expect_ident()?;
                    }
                    self.expect_sym('=')?;
                    let value = self.value()?;
                    if let Tok::Str(s) = value {
                        match (ext.as_str(), sub.as_str()) {
                            ("cli_field_attributes", "") => cli_field_attributes = Some(s),
                            ("map_key_enum_type", "") => map_key_enum_type = Some(s),
                            _ => {}
                        }
                    }
                } else {
                    // plain option (deprecated = true 等): 跳过
                    self.dotted_ident()?;
                    self.expect_sym('=')?;
                    self.value()?;
                }
                match self.next()? {
                    Some(Tok::Sym(',')) => continue,
                    Some(Tok::Sym(']')) => break,
                    other => {
                        return Err(ParseError { message: format!("bad field options: {other:?}") });
                    }
                }
            }
        }
        self.expect_sym(';')?;
        Ok(ParsedField {
            name,
            is_repeated,
            is_map,
            cli_field_attributes,
            map_key_enum_type,
        })
    }

    /// 解析 message 主体(前置 'message Name' 已消费), 只收集需要的语义.
    fn message_body(&mut self, full_name: String) -> Result<ParsedMessage, ParseError> {
        self.expect_sym('{')?;
        let mut opts = MessageOpts::default();
        let mut fields: Vec<ParsedField> = Vec::new();
        loop {
            match self.peek()? {
                None => return Err(ParseError { message: "unexpected EOF in message".into() }),
                Some(Tok::Sym('}')) => {
                    self.next()?;
                    return Ok(ParsedMessage { full_name, opts, fields });
                }
                Some(Tok::Sym(';')) => {
                    self.next()?;
                }
                Some(Tok::Ident(kw)) => match kw.as_str() {
                    "message" | "enum" | "extend" | "service" | "group" => {
                        // 嵌套声明: 跳过(registry 只索引顶层, 与 Python 一致)
                        self.skip_statement()?;
                    }
                    "reserved" | "extensions" => {
                        self.skip_statement()?;
                    }
                    "option" => {
                        self.next()?;
                        if let Some((ext, sub, value)) = self.option_statement()? {
                            match (ext.as_str(), sub.as_deref()) {
                                ("data_loader", Some("load_path")) => {
                                    if let Tok::Str(s) = value {
                                        let loader = opts.data_loader.get_or_insert_default();
                                        loader.load_path = s;
                                    }
                                }
                                ("data_loader", Some("is_single_file")) => {
                                    if let Tok::Ident(s) = value {
                                        let loader = opts.data_loader.get_or_insert_default();
                                        loader.is_single_file = s == "true";
                                    }
                                }
                                ("super_field_name", None) => {
                                    if let Tok::Str(s) = value {
                                        opts.super_field_name = Some(s);
                                    }
                                }
                                ("cli_index_field_name", None) => {
                                    if let Tok::Str(s) = value {
                                        opts.cli_index_field_name = Some(s);
                                    }
                                }
                                ("svr_index_field_name", None) => {
                                    if let Tok::Str(s) = value {
                                        opts.svr_index_field_name = Some(s);
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                    "repeated" => {
                        self.next()?;
                        self.dotted_ident()?;
                        fields.push(self.field(true, false)?);
                    }
                    "map" => {
                        self.next()?;
                        self.expect_sym('<')?;
                        self.dotted_ident()?; // K
                        self.expect_sym(',')?;
                        self.dotted_ident()?; // V
                        self.expect_sym('>')?;
                        fields.push(self.field(true, true)?);
                    }
                    "optional" | "required" => {
                        self.next()?;
                        self.dotted_ident()?;
                        fields.push(self.field(false, false)?);
                    }
                    _ => {
                        // 普通字段: kw 即类型首段
                        self.dotted_ident()?;
                        fields.push(self.field(false, false)?);
                    }
                },
                other => {
                    return Err(ParseError { message: format!("unexpected token in message: {other:?}") });
                }
            }
        }
    }

    /// 解析 enum 主体(前置 'enum Name' 已消费).
    fn enum_body(&mut self, full_name: String) -> Result<ParsedEnum, ParseError> {
        self.expect_sym('{')?;
        let mut values: Vec<(String, i64)> = Vec::new();
        loop {
            match self.peek()? {
                None => return Err(ParseError { message: "unexpected EOF in enum".into() }),
                Some(Tok::Sym('}')) => {
                    self.next()?;
                    return Ok(ParsedEnum { full_name, values });
                }
                Some(Tok::Sym(';')) => {
                    self.next()?;
                }
                Some(Tok::Ident(kw)) if kw == "option" || kw == "reserved" => {
                    self.skip_statement()?;
                }
                Some(Tok::Ident(name)) => {
                    self.next()?;
                    self.expect_sym('=')?;
                    let n = match self.value()? {
                        Tok::Num(n) => n,
                        other => {
                            return Err(ParseError { message: format!("bad enum value: {other:?}") });
                        }
                    };
                    if self.peek()? == Some(Tok::Sym('[')) {
                        self.next()?;
                        let mut depth = 1;
                        while depth > 0 {
                            match self.next()? {
                                None => break,
                                Some(Tok::Sym('[')) => depth += 1,
                                Some(Tok::Sym(']')) => depth -= 1,
                                Some(_) => {}
                            }
                        }
                    }
                    self.expect_sym(';')?;
                    values.push((name, n));
                }
                other => {
                    return Err(ParseError { message: format!("unexpected token in enum: {other:?}") });
                }
            }
        }
    }

    fn parse(mut self) -> Result<ParsedFile, ParseError> {
        let mut file = ParsedFile {
            package: String::new(),
            file_type: None,
            messages: Vec::new(),
            enums: Vec::new(),
        };
        loop {
            match self.peek()? {
                None => break,
                Some(Tok::Sym(';')) => {
                    self.next()?;
                }
                Some(Tok::Ident(kw)) => match kw.as_str() {
                    "syntax" => {
                        self.next()?;
                        self.expect_sym('=')?;
                        self.value()?;
                        self.expect_sym(';')?;
                    }
                    "package" => {
                        self.next()?;
                        file.package = self.dotted_ident()?;
                        self.expect_sym(';')?;
                    }
                    "import" => {
                        self.next()?;
                        // [public|weak] "path";
                        if let Some(Tok::Ident(_)) = self.peek()? {
                            self.next()?;
                        }
                        self.expect_str()?;
                        self.expect_sym(';')?;
                    }
                    "option" => {
                        self.next()?;
                        if let Some((ext, sub, value)) = self.option_statement()? {
                            if ext == "file_type" && sub.is_none() {
                                file.file_type = match value {
                                    Tok::Ident(s) if s == "STREAMING" => Some(FileType::Streaming),
                                    _ => Some(FileType::DataDefine),
                                };
                            }
                        }
                    }
                    "message" => {
                        self.next()?;
                        let name = self.expect_ident()?;
                        let full = qualify(&file.package, &name);
                        let msg = self.message_body(full)?;
                        file.messages.push(msg);
                    }
                    "enum" => {
                        self.next()?;
                        let name = self.expect_ident()?;
                        let full = qualify(&file.package, &name);
                        let e = self.enum_body(full)?;
                        file.enums.push(e);
                    }
                    _ => {
                        // service / extend / 未知顶层语句: 跳过
                        self.skip_statement()?;
                    }
                },
                other => {
                    return Err(ParseError { message: format!("unexpected top-level token: {other:?}") });
                }
            }
        }
        Ok(file)
    }
}

fn qualify(package: &str, name: &str) -> String {
    if package.is_empty() {
        name.to_string()
    } else {
        format!("{package}.{name}")
    }
}

/// 解析单个 proto 文件文本.
pub fn parse_file(text: &str) -> Result<ParsedFile, ParseError> {
    Parser::new(text).parse()
}

