{"content": "//! Runtime registry built from parsed proto schemas.
//!
//! 与 Python 版 `abc_db.registry` 一一对应: 从 proto 声明中提取项目的
//! 自定义 option 语义为可查询索引:
//!
//! - loaders: 带 `option (data_loader)` 的 message → load_path / is_single_file
//! - super_fields: `option (super_field_name)`(Base 字段组合继承)
//! - refs: `cli_field_attributes` 中的 `JsonConfigField(typeof(X))` 跨表引用
//! - enum_key_maps: `map_key_enum_type` 枚举键 map
//! - streaming_messages: `option (file_type) = STREAMING` 文件的顶层 message
//! - enums: 顶层枚举名 → 值表(如 Language → LANGUAGE_SC=1)
//!
//! 运行时默认读取内嵌快照(`registry_snapshot.json`, `abc-db gen-registry`
//! 重新生成, 零启动开销); 对拍/调试用 `build_registry_from_protos` 实时解析。

use std::collections::HashMap;
use std::fmt;
use std::path::Path;
use std::sync::Arc;

use serde::{Deserialize, Serialize};

use crate::schema::{FileType, ParsedFile};

/// 数据加载器 message(`option (data_loader)`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct LoaderDef {
    /// 全名, 如 `pd.TrainerChsTableConfig`.
    pub message_name: String,
    pub load_path: String,
    pub is_single_file: bool,
    /// cli/svr_index_field_name(逗号分隔取第一段).
    #[serde(default)]
    pub index_field: Option<String>,
    /// 单文件表顶层 repeated/map 字段名.
    #[serde(default)]
    pub entry_field: Option<String>,
}

impl LoaderDef {
    pub fn relative_dir(&self) -> &str {
        match self.load_path.rfind('/') {
            Some(i) => &self.load_path[..i],
            None => "",
        }
    }
}

/// 引用其他配置表的字段(`JsonConfigField(typeof(X))`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FieldRef {
    pub message_name: String,
    pub field_name: String,
    /// 目标类型裸名, 如 `AdvSmartObjectConfig`.
    pub target_type: String,
}

/// 枚举键 map 字段(`map_key_enum_type`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct EnumKeyMap {
    pub message_name: String,
    pub field_name: String,
    pub enum_type: String,
}

/// 不可变索引(构造后只读).
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Registry {
    /// key = message 全名.
    pub loaders: HashMap<String, LoaderDef>,
    pub super_fields: HashMap<String, String>,
    pub refs: Vec<FieldRef>,
    pub enum_key_maps: Vec<EnumKeyMap>,
    pub streaming_messages: std::collections::BTreeSet<String>,
    /// key = 顶层枚举裸名(如 `Language`), 值 = 值名 → 数值.
    #[serde(default)]
    pub enums: HashMap<String, HashMap<String, i64>>,
}

impl Registry {
    /// 按 load_path 查加载器(与 Python `find_loader` 一致: 线性扫描).
    pub fn loader_by_path(&self, load_path: &str) -> Option<&LoaderDef> {
        self.loaders.values().find(|l| l.load_path == load_path)
    }

    pub fn refs_for(&self, message_name: &str, field_name: &str) -> Vec<&FieldRef> {
        self.refs
            .iter()
            .filter(|r| r.message_name == message_name && r.field_name == field_name)
            .collect()
    }

    /// 枚举值名 → 数值(如 `LANGUAGE_SC` → 1).
    pub fn enum_value(&self, enum_name: &str, value_name: &str) -> Option<i64> {
        self.enums.get(enum_name).and_then(|v| v.get(value_name)).copied()
    }
}

#[derive(Debug, thiserror::Error)]
#[error("registry build failed: {0}")]
pub struct RegistryBuildError(pub String);

impl RegistryBuildError {
    fn file(path: &Path, err: crate::schema::ParseError) -> Self {
        RegistryBuildError(format!("{}: {}", path.display(), err))
    }
}

/// 正则与 Python `_JSON_CONFIG_FIELD_RE` 完全一致.
fn json_config_field_targets(attrs: &str) -> Vec<String> {
    let re = match regex::Regex::new(r"JsonConfigField\(\s*typeof\((\w+)\)") {
        Ok(re) => re,
        Err(_) => return Vec::new(),
    };
    re.captures_iter(attrs).filter_map(|c| c.get(1).map(|m| m[1].to_string())).collect()
}

/// 从解析结果构建 Registry(与 Python `build_registry` 语义逐条对应).
pub fn build_registry_from_files(files: &[ParsedFile]) -> Registry {
    let mut reg = Registry::default();
    for file in files {
        if file.file_type == Some(FileType::Streaming) {
            for m in &file.messages {
                reg.streaming_messages.insert(m.full_name.clone());
            }
        }
        for msg in &file.messages {
            index_message(msg, &mut reg);
        }
        for e in &file.enums {
            let values: HashMap<String, i64> = e.values.iter().cloned().collect();
            reg.enums.insert(e.full_name.clone(), values);
        }
    }
    reg
}

fn index_message(msg: &crate::schema::ParsedMessage, reg: &mut Registry) {
    if let Some(super_field) = &msg.opts.super_field_name {
        reg.super_fields.insert(msg.full_name.clone(), super_field.clone());
    }
    if let Some(loader_opt) = &msg.opts.data_loader {
        let index = msg
            .opts
            .cli_index_field_name
            .as_deref()
            .or(msg.opts.svr_index_field_name.as_deref())
            .and_then(|s| s.split(',').next().map(str::trim))
            .filter(|s| !s.is_empty())
            .map(str::to_string);
        let entry_field = if loader_opt.is_single_file {
            msg.fields
                .iter()
                .find(|f| f.is_repeated || f.is_map)
                .map(|f| f.name.clone())
        } else {
            None
        };
        reg.loaders.insert(
            msg.full_name.clone(),
            LoaderDef {
                message_name: msg.full_name.clone(),
                load_path: loader_opt.load_path.clone(),
                is_single_file: loader_opt.is_single_file,
                index_field: index,
                entry_field,
            },
        );
    }
    for field in &msg.fields {
        if let Some(attrs) = &field.cli_field_attributes {
            for target in json_config_field_targets(attrs) {
                reg.refs.push(FieldRef {
                    message_name: msg.full_name.clone(),
                    field_name: field.name.clone(),
                    target_type: target,
                });
            }
        }
        if field.is_map {
            if let Some(enum_type) = &field.map_key_enum_type {
                reg.enum_key_maps.push(EnumKeyMap {
                    message_name: msg.full_name.clone(),
                    field_name: field.name.clone(),
                    enum_type: enum_type.clone(),
                });
            }
        }
    }
}

// =====================================================================
// 快照(与 Python registry_to_json/from_json 格式一致)
// =====================================================================

/// 序列化为 Python `registry_to_json` 相同形状的 JSON.
pub fn registry_to_json(reg: &Registry) -> String {
    let obj = serde_json::json!({
        "loaders": reg.loaders.values().collect::<Vec<_>>(),
        "super_fields": reg.super_fields,
        "refs": reg.refs,
        "enum_key_maps": reg.enum_key_maps,
        "streaming_messages": reg.streaming_messages.iter().collect::<Vec<_>>(),
    });
    serde_json::to_string_pretty(&obj).expect("registry serialization cannot fail")
}

/// 从快照 JSON 重建 Registry.
pub fn registry_from_json(text: &str) -> Result<Registry, RegistryBuildError> {
    let data: serde_json::Value = serde_json::from_str(text)
        .map_err(|e| RegistryBuildError(format!("bad registry json: {e}")))?;
    let loaders: HashMap<String, LoaderDef> = data
        .get("loaders")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|item| {
                    let ld: LoaderDef = serde_json::from_value(item.clone()).ok()?;
                    Some((ld.message_name.clone(), ld))
                })
                .collect()
        })
        .unwrap_or_default();
    let super_fields: HashMap<String, String> = data
        .get("super_fields")
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .unwrap_or_default();
    let refs: Vec<FieldRef> = data
        .get("refs")
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .unwrap_or_default();
    let enum_key_maps: Vec<EnumKeyMap> = data
        .get("enum_key_maps")
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .unwrap_or_default();
    let streaming_messages = data
        .get("streaming_messages")
        .and_then(|v| v.as_array())
        .map(|arr| arr.iter().filter_map(|v| v.as_str().map(str::to_string)).collect())
        .unwrap_or_default();
    let enums: HashMap<String, HashMap<String, i64>> = data
        .get("enums")
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .unwrap_or_default();
    Ok(Registry {
        loaders,
        super_fields,
        refs,
        enum_key_maps,
        streaming_messages,
        enums,
    })
}

// =====================================================================
// 构建入口
// =====================================================================

/// 默认 proto 根(本机 P4 workspace; 可用 `ABC_PROTO_ROOT` 覆盖).
pub fn default_proto_root() -> std::path::PathBuf {
    std::env::var_os("ABC_PROTO_ROOT")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| {
            std::path::PathBuf::from(
                "~/Perforce/ABC_Project_<client>/Protobuf",
            )
        })
}

/// 解析目录下全部 proto 文件并构建 Registry(失败即报错, 与 Python
/// protoc 全量编译成功的语义一致).
pub fn build_registry_from_protos(
    proto_root: &Path,
) -> Result<Registry, RegistryBuildError> {
    let files = crate::schema::collect_proto_files(proto_root);
    let mut parsed: Vec<ParsedFile> = Vec::with_capacity(files.len());
    for path in &files {
        let text = std::fs::read_to_string(path)
            .map_err(|e| RegistryBuildError(format!("read {}: {e}", path.display())))?;
        let file = crate::schema::parse_file(&text).map_err(|e| RegistryBuildError::file(path, e))?;
        parsed.push(file);
    }
    Ok(build_registry_from_files(&parsed))
}

/// 内嵌快照的注册表(运行时默认入口).
pub fn build_registry() -> Arc<Registry> {
    static REG: std::sync::OnceLock<Arc<Registry>> = std::sync::OnceLock::new();
    REG.get_or_init(|| {
        let text = include_str!("registry_snapshot.json");
        Arc::new(
            registry_from_json(text)
                .unwrap_or_else(|e| panic!("embedded registry snapshot invalid: {e}")),
        )
    })
    .clone()
}

