use serde::{Deserialize, Serialize};
use serde_json::Value;

/// 编辑器 FText: 完整 dict 保留(Context/TextMapID/TextMapHashID).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FText {
    #[serde(rename = "TextMapHashID")]
    pub text_map_hash_id: u64,
    #[serde(rename = "Context", default)]
    pub context: Option<String>,
    #[serde(rename = "TextMapID", default)]
    pub text_map_id: Option<String>,
}

/// 编辑器 SoftObjectPath: 资源引用(路径可直接取用).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SoftPath {
    #[serde(rename = "AssetHash")]
    pub asset_hash: u64,
    #[serde(rename = "Name", default)]
    pub name: Option<String>,
    #[serde(rename = "Path", default)]
    pub path: Option<String>,
    #[serde(rename = "Type", default)]
    pub type_: Option<String>,
}

/// fixed/safe 定点数值: Raw 为定点整型, RealValue 为展示值(数字或字符串).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct InitAttribute {
    #[serde(rename = "RealValue", default)]
    pub real_value: Option<Value>,
    #[serde(rename = "Raw", default)]
    pub raw: Option<i64>,
}

/// ItemData: 物品 + 数量(奖励/消耗通用).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ItemRef {
    #[serde(rename = "ItemID", default)]
    pub item_id: Option<u64>,
    #[serde(rename = "Num", default)]
    pub num: Option<i64>,
}

/// 属性表(InitAttributes 等): 键为 `EntityAttribute_*`, 值为定点数值.
pub type AttrMap = std::collections::HashMap<String, InitAttribute>;
