{"content": "//! Component(多态)解析: JSON 数据里的多态条目带显式 `$type` 标记.
//!
//!     {"$type": "/pd.ChsTrainerAbilityEntityComponentConfig", "UltSkill": 22201, ...}
//!
//! JSON 路线不需要标记字节映射——类型名是显式的。

use serde_json::{Map, Value};

use crate::value_ext::JsonExt;

/// `$type` 值形如 `/pd.MessageName`, 剥掉前导斜杠.
pub const TYPE_PREFIX: &str = "/pd.";

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("no $type marker in component: {keys:?}")]
pub struct UnknownComponentError {
    keys: Vec<String>,
}

/// 解析多态条目的具体 message 类型名(裸名, 如 `ChsTrainerAbilityEntityComponentConfig`).
pub fn component_type_name(entry: &Map<String, Value>) -> Result<String, UnknownComponentError> {
    match entry.get("$type").and_then(Value::as_str) {
        Some(marker) if marker.starts_with(TYPE_PREFIX) => {
            Ok(marker[TYPE_PREFIX.len()..].to_string())
        }
        _ => Err(UnknownComponentError {
            keys: entry.keys().take(5).cloned().collect(),
        }),
    }
}

/// 校验一个 JSON 组件条目, 返回 (type_name, entry).
pub fn parse_json_component(entry: &Value) -> Result<(String, Value), UnknownComponentError> {
    let obj = entry.as_object().ok_or_else(|| UnknownComponentError { keys: Vec::new() })?;
    let type_name = component_type_name(obj)?;
    Ok((type_name, entry.clone()))
}

/// 容器列表里每个多态元素的 [(type_name, entry)].
///
/// 没有可用 `$type` 的条目跳过(需要严格模式请用 [`parse_json_component`]).
pub fn iter_components(container: &[Value]) -> Vec<(String, Value)> {
    container
        .iter()
        .filter_map(|entry| parse_json_component(entry).ok())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn parses_type_marker() {
        let entry = json!({"$type": "/pd.ChsTrainerAbilityEntityComponentConfig", "UltSkill": 22201});
        let (t, _) = parse_json_component(&entry).unwrap();
        assert_eq!(t, "ChsTrainerAbilityEntityComponentConfig");
    }

    #[test]
    fn rejects_bad_marker() {
        let entry = json!({"UltSkill": 22201});
        assert!(component_type_name(entry.as_object().unwrap()).is_err());
    }

    #[test]
    fn iter_skips_bad_entries() {
        let container = vec![
            json!({"$type": "/pd.A", "x": 1}),
            json!({"no": "marker"}),
            json!({"$type": "/pd.B", "y": 2}),
        ];
        let comps = iter_components(&container);
        assert_eq!(comps.len(), 2);
        assert_eq!(comps[0].0, "A");
        assert_eq!(comps[1].0, "B");
    }
}
", "file_path": "src/components.rs"}

