{"content": "//! FText 处理: 保留完整结构, 提供文案查询.
//!
//! 数据里 FText 永远是完整 dict: `{Context, TextMapID, TextMapHashID}`。
//! hash 是正式键(13 语/翻译管线); Context 只是内嵌的当前语言文本。
//! 文案查询走本模块, 绝不拍平。
//!
//! - [`ftext_text`]: 默认展示文本 — Context 优先, 否则 hash → TextMap 查询。
//! - [`ftext_langs`]: hash → {语言: 文本}(13 语)。

use std::collections::HashMap;

use serde_json::Value;

use crate::textmap::TextMapIndex;
use crate::value_ext::JsonExt;

/// 返回 FText dict 原样(结构处处保留).
pub fn ftext_dict(ftext: &Value) -> &Value {
    ftext
}

/// 最佳展示文本: Context 优先, 然后 TextMap(SC 优先, 回退任意语言), 最后空串.
pub fn ftext_text(ftext: Option<&Value>, textmap: Option<&TextMapIndex>) -> String {
    let Some(ftext) = ftext else { return String::new() };
    if let Some(ctx) = ftext.get("Context").and_then(Value::as_str) {
        if !ctx.is_empty() {
            return ctx.to_string();
        }
    }
    let hash = ftext.get("TextMapHashID").and_then(Value::as_u64).unwrap_or(0);
    if hash != 0 {
        if let Some(index) = textmap {
            let langs = index.lookup(hash);
            if let Some(sc) = langs.get(&1) {
                return sc.clone();
            }
            if let Some(first) = langs.values().next() {
                return first.clone();
            }
        }
    }
    String::new()
}

/// {Language 枚举值 → 文本} for TextMapHashID.
pub fn ftext_langs(ftext: Option<&Value>, textmap: &TextMapIndex) -> HashMap<i32, String> {
    let Some(ftext) = ftext else { return HashMap::new() };
    let hash = ftext.get("TextMapHashID").and_then(Value::as_u64).unwrap_or(0);
    textmap.lookup(hash)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn context_preferred() {
        let name = json!({"Context": "刃", "TextMapID": "x", "TextMapHashID": 640733071491943868u64});
        assert_eq!(ftext_text(Some(&name), None), "刃");
    }

    #[test]
    fn hash_without_index_empty() {
        let name = json!({"TextMapHashID": 640733071491943868u64});
        assert_eq!(ftext_text(Some(&name), None), "");
        assert_eq!(ftext_text(None, None), "");
    }

    #[test]
    fn langs_empty_without_index() {
        let name = json!({"TextMapHashID": 640733071491943868u64});
        let fake = TextMapIndex {
            root: std::path::PathBuf::new(),
            lang_by_prefix: Default::default(),
            hash_langs: Default::default(),
        };
        assert!(ftext_langs(Some(&name), &fake).is_empty());
    }
}
", "file_path": "src/ftext.rs"}

{"content": "//! `serde_json::Value` 便捷访问器: 让 wiki/typed 层的 dict 导航保持
//! Python 风格的可读性(`entry["Base"]["InitComponents"]` 风格的链式访问)。

use serde_json::{Map, Value};

/// Value 访问扩展(Python dict/list 语义的 Rust 版).
pub trait JsonExt {
    /// `obj.get(key)` — 任意值(含非对象)上安全取键.
    fn g(&self, key: &str) -> Option<&Value>;

    /// `obj.get(key)` 且必须是字符串.
    fn g_str(&self, key: &str) -> Option<&str>;

    /// 取字符串或默认值(非字符串/缺失 → 默认).
    fn s_or<'a>(&'a self, default: &'a str) -> &'a str;

    /// 取字符串(缺失/非字符串 → 空串).
    fn s(&self) -> &str;

    /// 取 u64 或默认.
    fn u_or(&self, default: u64) -> u64;

    /// 取 i64 或默认.
    fn i_or(&self, default: i64) -> i64;

    /// 取 f64 或默认.
    fn f_or(&self, default: f64) -> f64;

    /// 取 bool 或默认.
    fn b_or(&self, default: bool) -> bool;

    /// 视图为数组(非数组 → 空切片).
    fn arr(&self) -> &[Value];

    /// 视图为对象(非对象 → 空 map).
    fn obj(&self) -> &Map<String, Value>;

    /// 视图为对象(非对象 → None).
    fn as_obj(&self) -> Option<&Map<String, Value>>;

    /// 字符串化展示值(与 Python `str(x)` 语义对齐: 浮点整数带 `.0`).
    fn py_str(&self) -> String;
}

impl JsonExt for Value {
    fn g(&self, key: &str) -> Option<&Value> {
        self.as_object().and_then(|m| m.get(key))
    }

    fn g_str(&self, key: &str) -> Option<&str> {
        self.g(key).and_then(Value::as_str)
    }

    fn s_or<'a>(&'a self, default: &'a str) -> &'a str {
        self.as_str().unwrap_or(default)
    }

    fn s(&self) -> &str {
        self.as_str().unwrap_or("")
    }

    fn u_or(&self, default: u64) -> u64 {
        self.as_u64().unwrap_or(default)
    }

    fn i_or(&self, default: i64) -> i64 {
        self.as_i64().unwrap_or(default)
    }

    fn f_or(&self, default: f64) -> f64 {
        self.as_f64().unwrap_or(default)
    }

    fn b_or(&self, default: bool) -> bool {
        self.as_bool().unwrap_or(default)
    }

    fn arr(&self) -> &[Value] {
        self.as_array().map(Vec::as_slice).unwrap_or(&[])
    }

    fn obj(&self) -> &Map<String, Value> {
        self.as_object().unwrap_or(&EMPTY_MAP)
    }

    fn as_obj(&self) -> Option<&Map<String, Value>> {
        self.as_object()
    }

    fn py_str(&self) -> String {
        match self {
            Value::Number(n) => {
