{"content": "//! FText 处理: 保留完整结构, 提供文案查询.
//!
//! 数据里 FText 永远是完整 dict: `{Context, TextMapID, TextMapHashID}`。
//! hash 是正式键(13 语/翻译管线); Context 只是内嵌的当前语言文本。
//! 文案查询走本模块, 绝不拍平。
//!
//! - [`ftext_text`]: 默认展示文本 — Context 优先, 否则 hash → TextMap 查询。
//! - [`ftext_langs`]: hash → {语言: 文本}(13 语)。

use std::collections::HashMap;

use serde_json::Value;

use crate::textmap::TextMapIndex;
use crate::value_ext::JsonExt;

/// 返回 FText dict 原样(结构处处保留).
pub fn ftext_dict(ftext: &Value) -> &Value {
    ftext
}

/// 最佳展示文本: Context 优先, 然后 TextMap(SC 优先, 回退任意语言), 最后空串.
pub fn ftext_text(ftext: Option<&Value>, textmap: Option<&TextMapIndex>) -> String {
    let Some(ftext) = ftext else { return String::new() };
    if let Some(ctx) = ftext.get("Context").and_then(Value::as_str) {
        if !ctx.is_empty() {
            return ctx.to_string();
        }
    }
    let hash = ftext.get("TextMapHashID").and_then(Value::as_u64).unwrap_or(0);
    if hash != 0 {
        if let Some(index) = textmap {
            let langs = index.lookup(hash);
            if let Some(sc) = langs.get(&1) {
                return sc.clone();
            }
            if let Some(first) = langs.values().next() {
                return first.clone();
            }
        }
    }
    String::new()
}

/// {Language 枚举值 → 文本} for TextMapHashID.
pub fn ftext_langs(ftext: Option<&Value>, textmap: &TextMapIndex) -> HashMap<i32, String> {
    let Some(ftext) = ftext else { return HashMap::new() };
    let hash = ftext.get("TextMapHashID").and_then(Value::as_u64).unwrap_or(0);
    textmap.lookup(hash)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn context_preferred() {
        let name = json!({"Context": "刃", "TextMapID": "x", "TextMapHashID": 640733071491943868u64});
        assert_eq!(ftext_text(Some(&name), None), "刃");
    }

    #[test]
    fn hash_without_index_empty() {
        let name = json!({"TextMapHashID": 640733071491943868u64});
        assert_eq!(ftext_text(Some(&name), None), "");
        assert_eq!(ftext_text(None, None), "");
    }

    #[test]
    fn langs_empty_without_index() {
        let name = json!({"TextMapHashID": 640733071491943868u64});
        let fake = TextMapIndex {
            root: std::path::PathBuf::new(),
            lang_by_prefix: Default::default(),
            hash_langs: Default::default(),
        };
        assert!(ftext_langs(Some(&name), &fake).is_empty());
    }
}
