{"content": "//! `serde_json::Value` 便捷访问器: 让 wiki/typed 层的 dict 导航保持
//! Python 风格的可读性(`entry["Base"]["InitComponents"]` 风格的链式访问)。

use serde_json::{Map, Value};

/// Value 访问扩展(Python dict/list 语义的 Rust 版).
pub trait JsonExt {
    /// `obj.get(key)` — 任意值(含非对象)上安全取键.
    fn g(&self, key: &str) -> Option<&Value>;

    /// `obj.get(key)` 且必须是字符串.
    fn g_str(&self, key: &str) -> Option<&str>;

    /// 取字符串或默认值(非字符串/缺失 → 默认).
    fn s_or<'a>(&'a self, default: &'a str) -> &'a str;

    /// 取字符串(缺失/非字符串 → 空串).
    fn s(&self) -> &str;

    /// 取 u64 或默认.
    fn u_or(&self, default: u64) -> u64;

    /// 取 i64 或默认.
    fn i_or(&self, default: i64) -> i64;

    /// 取 f64 或默认.
    fn f_or(&self, default: f64) -> f64;

    /// 取 bool 或默认.
    fn b_or(&self, default: bool) -> bool;

    /// 视图为数组(非数组 → 空切片).
    fn arr(&self) -> &[Value];

    /// 视图为对象(非对象 → 空 map).
    fn obj(&self) -> &Map<String, Value>;

    /// 视图为对象(非对象 → None).
    fn as_obj(&self) -> Option<&Map<String, Value>>;

    /// 字符串化展示值(与 Python `str(x)` 语义对齐: 浮点整数带 `.0`).
    fn py_str(&self) -> String;
}

impl JsonExt for Value {
    fn g(&self, key: &str) -> Option<&Value> {
        self.as_object().and_then(|m| m.get(key))
    }

    fn g_str(&self, key: &str) -> Option<&str> {
        self.g(key).and_then(Value::as_str)
    }

    fn s_or<'a>(&'a self, default: &'a str) -> &'a str {
        self.as_str().unwrap_or(default)
    }

    fn s(&self) -> &str {
        self.as_str().unwrap_or("")
    }

    fn u_or(&self, default: u64) -> u64 {
        self.as_u64().unwrap_or(default)
    }

    fn i_or(&self, default: i64) -> i64 {
        self.as_i64().unwrap_or(default)
    }

    fn f_or(&self, default: f64) -> f64 {
        self.as_f64().unwrap_or(default)
    }

    fn b_or(&self, default: bool) -> bool {
        self.as_bool().unwrap_or(default)
    }

    fn arr(&self) -> &[Value] {
        self.as_array().map(Vec::as_slice).unwrap_or(&[])
    }

    fn obj(&self) -> &Map<String, Value> {
        self.as_object().unwrap_or(&EMPTY_MAP)
    }

    fn as_obj(&self) -> Option<&Map<String, Value>> {
        self.as_object()
    }

    fn py_str(&self) -> String {
        match self {
            Value::Number(n) => {
                if let Some(i) = n.as_i64() {
                    i.to_string()
                } else if let Some(f) = n.as_f64() {
                    crate::json_py::py_float_str(f)
                } else {
                    n.to_string()
                }
            }
            Value::String(s) => s.clone(),
            Value::Bool(b) => b.to_string(),
            Value::Null => String::new(),
            Value::Array(_) | Value::Object(_) => self.to_string(),
        }
    }
}

static EMPTY_MAP: Map<String, Value> = Map::new();

/// 顶层字段集合(与 Python `dict.keys()` 对齐, 用于行键 ⊆ 字段键校验).
pub fn keys_of(obj: &Map<String, Value>) -> Vec<&str> {
    obj.keys().map(String::as_str).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn accessors() {
        let v = json!({"Name": "刃", "ID": 22200, "Ratio": 0.5, "Ok": true, "List": [1, 2], "Nested": {"X": "y"}});
        assert_eq!(v.g_str("Name"), Some("刃"));
        assert_eq!(v.g("Missing").and_then(Value::as_str), None);
        assert_eq!(v.g("Name").unwrap().s_or("?"), "刃");
        assert_eq!(v.g("Missing").unwrap_or(&Value::Null).s_or("?"), "?");
        assert_eq!(v.g("ID").unwrap().u_or(0), 22200);
        assert_eq!(v.g("Ratio").unwrap().f_or(0.0), 0.5);
        assert!(v.g("Ok").unwrap().b_or(false));
        assert_eq!(v.g("List").unwrap().arr().len(), 2);
        assert_eq!(v.g("Nested").unwrap().g_str("X"), Some("y"));
        assert_eq!(v.g("Nested").unwrap().obj().len(), 1);
        // 非对象上取键安全返回 None
        assert_eq!(v.g("List").unwrap().g("X"), None);
    }

    #[test]
    fn py_str_formats() {
        assert_eq!(json!(312.0).py_str(), "312.0");
        assert_eq!(json!(90.0).py_str(), "90.0");
        assert_eq!(json!(0.5).py_str(), "0.5");
        assert_eq!(json!(42).py_str(), "42");
        assert_eq!(json!("abc").py_str(), "abc");
        assert_eq!(json!(true).py_str(), "True"); // Python str(True)
        assert_eq!(json!(null).py_str(), "");
    }
}
