{"content": "//! Python `json.dumps(ensure_ascii=False, indent=N)` 兼容写出器.
//!
//! 用于与 Python 实现的对拍产物字节级一致:
//! - 缩进规则与 CPython 相同: 每个容器(对象/数组)内层 `level += 1`,
//!   内容缩进 `indent * level`, 闭合括号缩进 `indent * (level - 1)`;
//! - 分隔符: 对象 `,` + 换行缩进 与 `: `; 数组 `,` + 换行缩进;
//! - 字符串转义与 Python 相同(`"` `\` 控制字符 `\u00xx`, 非 ASCII 原样);
//! - 浮点: Python `repr(float)` 近似(整数浮点带 `.0`).
//!
//! 行数据契约: 任意表行都是 str→object 的只读映射(具体形状见 wiki/rows.rs)。

use std::fmt::Write as _;

use serde_json::Value;

/// 把 value 写成 Python `json.dumps(value, ensure_ascii=False, indent=N)` 形状的文本.
pub fn to_python_json(value: &Value, indent: usize) -> String {
    let mut out = String::new();
    write_value(&mut out, value, indent, 0);
    out
}

fn write_value(out: &mut String, value: &Value, indent: usize, level: usize) {
    match value {
        Value::Null => out.push_str("null"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Number(n) => out.push_str(&py_number_str(n)),
        Value::String(s) => write_py_string(out, s),
        Value::Array(items) => write_array(out, items, indent, level),
        Value::Object(map) => write_object(out, map, indent, level),
    }
}

fn write_array(out: &mut String, items: &[Value], indent: usize, level: usize) {
    if items.is_empty() {
        out.push_str("[]");
        return;
    }
    out.push('[');
    let inner = level + 1;
    for (i, item) in items.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        newline_indent(out, indent, inner);
        write_value(out, item, indent, inner);
    }
    newline_indent(out, indent, level);
    out.push(']');
}

fn write_object(out: &mut String, map: &serde_json::Map<String, Value>, indent: usize, level: usize) {
    if map.is_empty() {
        out.push_str("{}");
        return;
    }
    out.push('{');
    let inner = level + 1;
    for (i, (key, value)) in map.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        newline_indent(out, indent, inner);
        write_py_string(out, key);
        out.push_str(": ");
        write_value(out, value, indent, inner);
    }
    newline_indent(out, indent, level);
    out.push('}');
}

fn newline_indent(out: &mut String, indent: usize, level: usize) {
    out.push('\n');
    for _ in 0..indent * level {
        out.push(' ');
    }
}

/// Python 字符串转义(`ensure_ascii=False`): 转义 `"` `\` 与 <0x20 控制字符.
fn write_py_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Python `str(float)` / `repr(float)` 近似: 整数浮点带 `.0`.
pub fn py_float_str(f: f64) -> String {
    if f == f.trunc() && f.is_finite() {
        format!("{f:.1}")
    } else {
        format!("{f}")
    }
}

fn py_number_str(n: &serde_json::Number) -> String {
    if let Some(i) = n.as_i64() {
        i.to_string()
    } else if let Some(u) = n.as_u64() {
        u.to_string()
    } else if let Some(f) = n.as_f64() {
        py_float_str(f)
    } else {
        n.to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn matches_python_indent_one() {
        let v = json!([
            {"Base": {"EditorName": "0.2"}, "ID": 22200, "List": [1, 2], "Name": "刃</script>"},
            {"X": null}
        ]);
        let text = to_python_json(&v, 1);
        let expected = "[\n {\n  \"Base\": {\n   \"EditorName\": \"0.2\"\n  },\n  \"ID\": 22200,\n  \"List\": [\n   1,\n   2\n  ],\n  \"Name\": \"刃</script>\"\n },\n {\n  \"X\": null\n }\n]";
        assert_eq!(text, expected);
    }

    #[test]
    fn empty_containers() {
        assert_eq!(to_python_json(&json!({}), 1), "{}");
        assert_eq!(to_python_json(&json!([]), 1), "[]");
        assert_eq!(to_python_json(&json!({"a": []}), 1), "{\n \"a\": []\n}");
    }

    #[test]
    fn floats_and_escapes() {
        assert_eq!(py_float_str(312.0), "312.0");
        assert_eq!(py_float_str(0.5), "0.5");
        assert_eq!(py_float_str(-0.0), "-0.0");
        let v = json!({"s": "a\"b\\c\u{01}d"});
        assert_eq!(to_python_json(&v, 0), "{\"s\": \"a\\\"b\\\\c\\u0001d\"}");
    }
}
