//!
//! JSON 是编辑器格式: 完整标准 JSON, 每个配置一个文件(6.3 万文件)。
//! 两种文件形态:
//!
//! - 单文件表: `{root}/{load_path}.json` 是整个表 message, 顶层键是
//!   loader 的 repeated/map 字段名(如 `Table/TrainerChs.json` → `{"TrainerList": [...]}`)
//! - 目录型: `{root}/{load_path}/{index_value}.json` 一个文件一条
//!   (如 `Entity/ChsTrainer/22200.json`)
//!
//! 值一律是纯 `serde_json::Value`(无 protobuf 对象)。FText 保持 dict
//! (见 ftext); 多态组件条目保留 `$type`(见 components)。
//!
//! 失败行为: 缺文件记日志并报错([`JsonConfigError::Missing`]);
//! 坏 JSON 记日志并报错([`JsonConfigError::Parse`]); 批量迭代可
//! `skip_errors` 跳过坏文件。
//!
//! 函数式优先: 核心加载逻辑是模块级纯函数(`load_json` / `load_single_entries` /
//! `load_dir_entry` / `iter_dir_entries`); [`JsonConfig`] 只是冻结值对象
//! (root + registry), 实例方法为纯函数的薄委托。

use std::path::{Path, PathBuf};
use std::sync::Arc;

use log::warn;
use serde_json::Value;

use crate::registry::{LoaderDef, Registry};

/// 配置文件无法加载/解析.
#[derive(Debug, thiserror::Error)]
pub enum JsonConfigError {
    #[error("missing file: {0}")]
    Missing(PathBuf),
    #[error("cannot parse json: {0} [{1}]")]
    Parse(String, PathBuf),
    #[error("cannot find entry field for {0} [{1}]")]
    NoEntryField(String, String),
    #[error("entry field {0} of {1} is not a list/map [{2}]")]
    BadEntryField(String, String, String),
}

/// 不可变值对象: 绑定 BinaryData/Config 根目录与 Registry.
#[derive(Debug, Clone)]
pub struct JsonConfig {
    pub root: PathBuf,
    pub registry: Arc<Registry>,
}

impl JsonConfig {
    /// 构建 (root, registry) 冻结值对象(registry 由 [`crate::registry::build_registry`] 生成).
    pub fn open(root: impl Into<PathBuf>) -> JsonConfig {
        JsonConfig { root: root.into(), registry: crate::registry::build_registry() }
    }

    pub fn open_with(root: impl Into<PathBuf>, registry: Arc<Registry>) -> JsonConfig {
        JsonConfig { root: root.into(), registry }
    }

    // ------------------------------------------------------------------ files
    pub fn single_file_path(&self, loader: &LoaderDef) -> PathBuf {
        single_file_path(&self.root, loader)
    }

    pub fn dir_file_path(&self, loader: &LoaderDef, index_value: i64) -> PathBuf {
        dir_file_path(&self.root, loader, index_value)
    }

    // ------------------------------------------------------------------ load
    pub fn load_json(&self, path: impl AsRef<Path>) -> Result<Value, JsonConfigError> {
        load_json(path.as_ref())
    }

    pub fn load_single(&self, loader: &LoaderDef) -> Result<Value, JsonConfigError> {
        load_json(&single_file_path(&self.root, loader))
    }

    pub fn load_single_entries(&self, loader: &LoaderDef) -> Result<Vec<Value>, JsonConfigError> {
        load_single_entries(&self.root, loader)
    }

    pub fn load_dir_entry(
        &self,
        loader: &LoaderDef,
        index_value: i64,
    ) -> Result<Value, JsonConfigError> {
        load_dir_entry(&self.root, loader, index_value)
    }

    pub fn iter_dir_entries(
        &self,
        loader: &LoaderDef,
        skip_errors: bool,
    ) -> Result<Vec<(i64, Value)>, JsonConfigError> {
        iter_dir_entries(&self.root, loader, skip_errors)
    }
}

// ------------------------------------------------------------------ files
pub fn single_file_path(root: &Path, loader: &LoaderDef) -> PathBuf {
    root.join(format!("{}.json", loader.load_path))
}

pub fn dir_file_path(root: &Path, loader: &LoaderDef, index_value: i64) -> PathBuf {
    root.join(&loader.load_path).join(format!("{index_value}.json"))
}

// ------------------------------------------------------------------ load
/// 读一个 JSON 文件为 Value(缺文件/坏文件记日志并报错).
pub fn load_json(path: &Path) -> Result<Value, JsonConfigError> {
    if !path.is_file() {
        warn!("missing file: {}", path.display());
        return Err(JsonConfigError::Missing(path.to_path_buf()));
    }
    let text = std::fs::read_to_string(path).map_err(|e| {
        warn!("read failed: {}: {e}", path.display());
        JsonConfigError::Parse(e.to_string(), path.to_path_buf())
    })?;
    serde_json::from_str(&text).map_err(|e| {
        warn!("json parse failed: {}", path.display());
        JsonConfigError::Parse(e.to_string(), path.to_path_buf())
    })
}

/// 读单文件表顶层 JSON 对象.
pub fn load_single(root: &Path, loader: &LoaderDef) -> Result<Value, JsonConfigError> {
    load_json(&single_file_path(root, loader))
}

/// 单文件表条目列表(自动定位 repeated/map 顶层键).
///
/// `{"TrainerList": [...]}` → `[...]`。顶层键缺失时报
/// [`JsonConfigError::NoEntryField`]。
pub fn load_single_entries(root: &Path, loader: &LoaderDef) -> Result<Vec<Value>, JsonConfigError> {
    let data = load_single(root, loader)?;
    let Some(field) = loader.entry_field.as_deref() else {
        // Fallback: 唯一值是 list 的顶层键(与 Python 一致)
        let candidates: Vec<&Value> = data
            .as_object()
            .map(|m| m.values().filter(|v| v.is_array()).collect())
            .unwrap_or_default();
        if candidates.len() == 1 {
            return Ok(candidates[0].as_array().cloned().unwrap_or_default());
        }
        return Err(JsonConfigError::NoEntryField(
            loader.message_name.clone(),
            loader.load_path.clone(),
        ));
    };
    let value = data.get(field).ok_or_else(|| {
        JsonConfigError::NoEntryField(loader.message_name.clone(), loader.load_path.clone())
    })?;
    match value {
        Value::Array(items) => Ok(items.clone()),
        Value::Object(map) => Ok(map.values().cloned().collect()),
        _ => Err(JsonConfigError::BadEntryField(
            field.to_string(),
            loader.message_name.clone(),
            loader.load_path.clone(),
        )),
    }
}

/// 读目录型表的一条(文件名 = 索引值).
pub fn load_dir_entry(root: &Path, loader: &LoaderDef, index_value: i64) -> Result<Value, JsonConfigError> {
    load_json(&dir_file_path(root, loader, index_value))
}

/// 逐条产出 (index_value, entry); `skip_errors` 跳过坏文件.
pub fn iter_dir_entries(
    root: &Path,
    loader: &LoaderDef,
    skip_errors: bool,
) -> Result<Vec<(i64, Value)>, JsonConfigError> {
    let directory = root.join(&loader.load_path);
    if !directory.is_dir() {
        return Err(JsonConfigError::Missing(directory));
    }
    let mut entries: Vec<(i64, Value)> = Vec::new();
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&directory)
        .map_err(|e| JsonConfigError::Parse(e.to_string(), directory.clone()))?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    for path in paths {
        let Some(stem) = path.file_stem().and_then(|s| s.to_str()) else { continue };
        let Ok(index) = stem.parse::<i64>() else { continue };
        match load_json(&path) {
            Ok(entry) => entries.push((index, entry)),
            Err(e) => {
                if !skip_errors {
                    return Err(e);
                }
            }
        }
    }
    Ok(entries)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn loader(load_path: &str, entry_field: Option<&str>) -> LoaderDef {
        LoaderDef {
            message_name: "pd.TestTableConfig".into(),
            load_path: load_path.into(),
            is_single_file: entry_field.is_some(),
            index_field: None,
            entry_field: entry_field.map(str::to_string),
        }
    }

    fn tmp_dir() -> tempfile::TempDir {
        tempfile::tempdir().unwrap()
    }

    #[test]
    fn loads_single_file_entries() {
        let dir = tmp_dir();
        let root = dir.path();
        std::fs::create_dir_all(root.join("Table")).unwrap();
        std::fs::write(
            root.join("Table/Test.json"),
            r#"{"TrainerList": [{"ID": 1, "Name": {"Context": "刃", "TextMapID": "x", "TextMapHashID": 5}}]}"#,
        )
        .unwrap();
        let ld = loader("Table/Test", Some("TrainerList"));
        let entries = load_single_entries(root, &ld).unwrap();
        assert_eq!(entries.len(), 1);
        assert_eq!(entries[0].g_str("Name").and_then(|_| None), None);
        assert_eq!(entries[0].g("Name").unwrap().g_str("Context"), Some("刃"));
    }

    #[test]
    fn missing_file_is_missing_error() {
        let dir = tmp_dir();
        let ld = loader("Table/Nope", Some("List"));
        match load_single_entries(dir.path(), &ld) {
            Err(JsonConfigError::Missing(p)) => assert!(p.to_string_lossy().contains("Nope")),
            other => panic!("expected Missing, got {other:?}"),
        }
    }

    #[test]
    fn bad_json_is_parse_error() {
        let dir = tmp_dir();
        std::fs::create_dir_all(dir.path().join("Table")).unwrap();
        std::fs::write(dir.path().join("Table/Bad.json"), "{not json").unwrap();
        let ld = loader("Table/Bad", Some("List"));
        match load_single_entries(dir.path(), &ld) {
            Err(JsonConfigError::Parse(..)) => {}
            other => panic!("expected Parse, got {other:?}"),
        }
    }

    #[test]
    fn missing_entry_field_errors() {
        let dir = tmp_dir();
        std::fs::create_dir_all(dir.path().join("Table")).unwrap();
        std::fs::write(dir.path().join("Table/NoField.json"), r#"{"Other": [1]}"#).unwrap();
        let ld = loader("Table/NoField", Some("Missing"));
        match load_single_entries(dir.path(), &ld) {
            Err(JsonConfigError::NoEntryField(..)) => {}
            other => panic!("expected NoEntryField, got {other:?}"),
        }
    }

    #[test]
    fn entry_field_fallback_single_list_key() {
        let dir = tmp_dir();
        std::fs::create_dir_all(dir.path().join("Table")).unwrap();
        std::fs::write(dir.path().join("Table/Fallback.json"), r#"{"Solo": [{"ID": 1}]}"#).unwrap();
        let ld = loader("Table/Fallback", None);
        let entries = load_single_entries(dir.path(), &ld).unwrap();
        assert_eq!(entries.len(), 1);
    }

    #[test]
    fn map_table_entries_are_values() {
        let dir = tmp_dir();
        std::fs::create_dir_all(dir.path().join("Table")).unwrap();
        std::fs::write(
            dir.path().join("Table/MapTable.json"),
            r#"{"Configs": {"a": {"ID": 1}, "b": {"ID": 2}}}"#,
        )
        .unwrap();
        let ld = loader("Table/MapTable", Some("Configs"));
        let entries = load_single_entries(dir.path(), &ld).unwrap();
        assert_eq!(entries.len(), 2);
    }

    #[test]
    fn iter_dir_entries_skips_non_int_names() {
        let dir = tmp_dir();
        std::fs::create_dir_all(dir.path().join("Dir")).unwrap();
        std::fs::write(dir.path().join("Dir/1.json"), r#"{"ID": 1}"#).unwrap();
        std::fs::write(dir.path().join("Dir/abc.json"), r#"{"ID": 2}"#).unwrap();
        std::fs::write(dir.path().join("Dir/2.json"), r#"{"ID": 2}"#).unwrap();
        let ld = loader("Dir", None);
        let entries = iter_dir_entries(dir.path(), &ld, false).unwrap();
        let ids: Vec<i64> = entries.iter().map(|(i, _)| *i).collect();
        assert_eq!(ids, vec![1, 2]);
    }

    #[test]
    fn iter_dir_skip_errors() {
        let dir = tmp_dir();
        std::fs::create_dir_all(dir.path().join("Dir")).unwrap();
        std::fs::write(dir.path().join("Dir/1.json"), r#"{"ID": 1}"#).unwrap();
        std::fs::write(dir.path().join("Dir/2.json"), "{bad").unwrap();
        std::fs::write(dir.path().join("Dir/3.json"), r#"{"ID": 3}"#).unwrap();
        let ld = loader("Dir", None);
        let entries = iter_dir_entries(dir.path(), &ld, true).unwrap();
        assert_eq!(entries.len(), 2);
        assert!(iter_dir_entries(dir.path(), &ld, false).is_err());
    }
}
