    (11, "TH"),
    (12, "VI"),
    (13, "ID"),
];

/// 拆 `{lang_prefix}{table_id:08d}`(8 位定宽补零表号).
///
/// 例: `100001000` → (1, 1000) [SC], `1000001000` → (10, 1000) [TH],
/// `1010000000` → (10, 10000000) [TH]。定宽消除 1 与 10 前缀歧义。
pub fn split_textmap_filename(name: &str) -> Result<(i32, i64), String> {
    for prefix in (1..=13).rev() {
        let ps = prefix.to_string();
        if name.starts_with(&ps) && name.len() == ps.len() + 8 {
            let table: i64 = name[ps.len()..]
                .parse()
                .map_err(|_| format!("not a textmap filename: {name:?}"))?;
            return Ok((prefix, table));
        }
    }
    Err(format!("not a textmap filename: {name:?}"))
}

/// 不可变值对象: hash → {语言枚举值 → 文案} 全量索引.
#[derive(Debug, Clone, Default)]
pub struct TextMapIndex {
    pub root: PathBuf,
    pub lang_by_prefix: HashMap<i32, i32>,
    pub hash_langs: HashMap<u64, HashMap<i32, String>>,
}

impl TextMapIndex {
    /// 返回 {Language 枚举值 → 文案}(克隆, 与 Python `lookup` 返回新 dict 一致).
    pub fn lookup(&self, hash_id: u64) -> HashMap<i32, String> {
        self.hash_langs.get(&hash_id).cloned().unwrap_or_default()
    }

    /// {简体中文: …, 英文: …}(LANG_NAMES 键).
    pub fn lookup_named(&self, hash_id: u64) -> HashMap<String, String> {
        self.lookup(hash_id)
            .into_iter()
            .map(|(lang, text)| {
                let key = LANG_NAMES
                    .iter()
                    .find(|(l, _)| *l == lang)
                    .map(|(_, n)| (*n).to_string())
                    .unwrap_or_else(|| lang.to_string());
                (key, text)
            })
            .collect()
    }

    /// {SC: …, EN: …}(LANG_CODES 键).
    pub fn lookup_codes(&self, hash_id: u64) -> HashMap<String, String> {
        self.lookup(hash_id)
            .into_iter()
            .map(|(lang, text)| {
                let key = LANG_CODES
                    .iter()
                    .find(|(l, _)| *l == lang)
                    .map(|(_, c)| (*c).to_string())
                    .unwrap_or_else(|| lang.to_string());
                (key, text)
            })
            .collect()
    }

    pub fn len(&self) -> usize {
        self.hash_langs.len()
    }

    pub fn is_empty(&self) -> bool {
        self.hash_langs.is_empty()
    }

    /// 构建索引(兼容旧调用; 纯构建函数见 [`build_textmap_index`]).
    pub fn open(root: impl Into<PathBuf>) -> TextMapIndex {
        build_textmap_index(root.into())
    }
}

/// 纯函数: TextMapLanguageTable 的 前缀 → 语言枚举值 映射.
fn load_language_table(root: &Path) -> HashMap<i32, i32> {
    let config = JsonConfig::open(root);
    let Some(loader) = config.registry.loader_by_path("Global/TextMapLanguageTable") else {
        return HashMap::new();
    };
    let Ok(table) = config.load_single(loader) else { return HashMap::new() };
    let mut by_prefix: HashMap<i32, String> = HashMap::new();
    if let Some(configs) = table.get("Configs").and_then(serde_json::Value::as_object) {
        for (lang_name, cfg) in configs {
            let Some(prefix) = cfg.get("TableIDPrefix").and_then(serde_json::Value::as_i64)
            else {
                continue;
            };
            by_prefix.insert(prefix as i32, lang_name.clone());
        }
    }
    // map 键是枚举名(如 "LANGUAGE_SC"), 转枚举值
    let mut resolved: HashMap<i32, i32> = HashMap::new();
    for (prefix, lang_name) in by_prefix {
        if let Some(value) = config.registry.enum_value("Language", &lang_name) {
            resolved.insert(prefix, value as i32);
        }
    }
    resolved
}

fn scan_hash_langs(root: &Path, lang_by_prefix: &HashMap<i32, i32>) -> HashMap<u64, HashMap<i32, String>> {
    let textmap_dir = root.join("TextMap");
    if !textmap_dir.is_dir() {
        return HashMap::new();
    }
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&textmap_dir)
        .map(|rd| {
            rd.filter_map(|e| e.ok().map(|e| e.path()))
                .filter(|p| p.extension().is_some_and(|e| e == "json"))
                .collect()
        })
        .unwrap_or_default();
    paths.sort();
    let per_file: Vec<HashMap<u64, (i32, String)>> = paths
        .par_iter()
        .filter_map(|path| {
            let Some(stem) = path.file_stem().and_then(|s| s.to_str()) else {
                return None;
            };
            let Ok((prefix, _table_id)) = split_textmap_filename(stem) else {
                return None;
            };
            let Some(&lang) = lang_by_prefix.get(&prefix) else {
                return None;
            };
            let text = std::fs::read_to_string(path).ok()?;
            let data: serde_json::Value = serde_json::from_str(&text).ok()?;
            let mut out = HashMap::new();
            if let Some(configs) = data.get("Configs").and_then(serde_json::Value::as_array) {
                for config in configs {
                    let hash_id = config.get("TextMapHashID").and_then(serde_json::Value::as_u64);
                    let content = config.get("Content").and_then(serde_json::Value::as_str);
                    if let (Some(hash_id), Some(content)) = (hash_id, content) {
                        out.insert(hash_id, (lang, content.to_string()));
                    }
                }
            }
            Some(out)
        })
        .collect();

    let mut hash_langs: HashMap<u64, HashMap<i32, String>> = HashMap::new();
    for file in per_file {
        for (hash_id, (lang, content)) in file {
            hash_langs.entry(hash_id).or_default().insert(lang, content);
        }
    }
    hash_langs
}

/// 纯构建函数: 扫描全部 TextMap 文件, 一次性构造冻结 [`TextMapIndex`].
pub fn build_textmap_index(root: PathBuf) -> TextMapIndex {
    let lang_by_prefix = load_language_table(&root);
    let hash_langs = scan_hash_langs(&root, &lang_by_prefix);
    TextMapIndex { root, lang_by_prefix, hash_langs }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn split_filename() {
        assert_eq!(split_textmap_filename("100001000").unwrap(), (1, 1000));
        assert_eq!(split_textmap_filename("1000001000").unwrap(), (10, 1000));
        assert_eq!(split_textmap_filename("100002000").unwrap(), (1, 2000));
        assert_eq!(split_textmap_filename("1000002000").unwrap(), (10, 2000));
        assert_eq!(split_textmap_filename("1010000000").unwrap(), (10, 10000000));
        assert_eq!(split_textmap_filename("1300001000").unwrap(), (13, 1000));
        assert!(split_textmap_filename("abc").is_err());
    }

    #[test]
    fn lookup_missing_hash_empty() {
        let idx = TextMapIndex::default();
        assert!(idx.lookup(999_999_999_999_999_999).is_empty());
        assert!(idx.lookup_named(1).is_empty());
    }

    #[test]
    fn lookup_named_and_codes() {
        let mut hash_langs = HashMap::new();
        hash_langs.insert(1u64, HashMap::from([(1, "刃".into()), (3, "Blade".into())]));
        let idx = TextMapIndex { root: PathBuf::new(), lang_by_prefix: HashMap::new(), hash_langs };
        let named = idx.lookup_named(1);
        assert_eq!(named.get("简体中文").map(String::as_str), Some("刃"));
        let codes = idx.lookup_codes(1);
        assert_eq!(codes.get("SC").map(String::as_str), Some("刃"));
        assert_eq!(codes.get("EN").map(String::as_str), Some("Blade"));
    }

    #[test]
    fn scan_from_tmp_dir() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        // 语言表(单文件表, 无 loader 时跳过) + 直接放 TextMap 文件, 无语言表 → 空
        std::fs::create_dir_all(root.join("TextMap")).unwrap();
        std::fs::write(
            root.join("TextMap/100001000.json"),
            r#"{"Configs": [{"TextMapHashID": 5, "Content": "刃"}]}"#,
        )
        .unwrap();
        let idx = build_textmap_index(root.to_path_buf());
        // 无 Global/TextMapLanguageTable → lang_by_prefix 空 → 索引空
        assert!(idx.lang_by_prefix.is_empty());
        assert!(idx.hash_langs.is_empty());
    }
}
