{"content": "//! SoftObjectPath 工具: 按 P4 同步资源树解析资源 hash/路径.
//!
//! 运行时 `.bin` 配置把 `SoftObjectPath` 存成只有 `AssetHash`(uint64)。
//! 实际资源路径在 P4 资源树, 例如
//! `//<depot>/main/ProjABC/Assets/Res/Prefabrication/UI/SpriteOutput/`。
//!
//! 本模块提供三种能力(全部基于路径, 不做 hash 逆向):
//!
//! - [`SoftPathIndex::build`]: 扫描本地(P4 同步)资源目录, 产出资产清单;
//! - [`extract_hash_map`]: 从编辑器 JSON 提取 hash→路径映射
//!   (编辑器格式把 SoftObjectPath 序列化为 `{Name, Path, Type, AssetHash}`);
//! - [`get_content`] / [`fetch`]: 按 depot-relative path 取内容
//!   (本地 workspace 拷贝, `p4 print` 兜底)。
//!
//! 典型用法::
//!
//!     index = SoftPathIndex::build(root_dir)        # 扫描 SpriteOutput
//!     hash_map = extract_hash_map(json_root)        # 编辑器 JSON → {hash: path}
//!     path = resolve(&hash_map, 2696647427999178046)
//!     fetch(path, out_dir, workspace_root)          # 拷贝(或 p4 print)

use std::cell::RefCell;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use log::warn;
use rayon::prelude::*;
use serde_json::Value;

/// 编辑器 SoftObjectPath 序列化键.
const SOP_KEYS: [&str; 4] = ["Name", "Path", "Type", "AssetHash"];

/// 资源树里的一个资产.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssetEntry {
    /// depot-relative 路径, 如 `Assets/Res/.../Avatar2048/222_00.png`.
    pub path: String,
    pub size: u64,
    pub local_path: PathBuf,
}

/// 不可变值对象: P4 同步资源目录的资产清单(构造后只读).
#[derive(Debug, Clone, Default)]
pub struct SoftPathIndex {
    by_path: HashMap<String, AssetEntry>,
}

impl SoftPathIndex {
    /// 递归扫描 *root* 找资产文件(跳过 `.meta`)。
    pub fn build(root: &Path) -> SoftPathIndex {
        let mut entries = Vec::new();
        let mut stack = vec![root.to_path_buf()];
        while let Some(dir) = stack.pop() {
            let Ok(rd) = std::fs::read_dir(&dir) else { continue };
            for entry in rd.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    stack.push(path);
                } else if path.extension().is_some_and(|e| e == "meta") {
                    continue;
                } else if path.is_file() {
                    let rel = path.strip_prefix(root).unwrap_or(&path);
                    let rel_str = rel.to_string_lossy().replace('\\', "/");
                    let size = std::fs::metadata(&path).map(|m| m.len()).unwrap_or(0);
                    entries.push(AssetEntry { path: rel_str, size, local_path: path });
                }
            }
        }
        entries.sort_by(|a, b| a.path.cmp(&b.path));
        SoftPathIndex { by_path: entries.into_iter().map(|e| (e.path.clone(), e)).collect() }
    }

    pub fn paths(&self) -> Vec<String> {
        let mut v: Vec<String> = self.by_path.keys().cloned().collect();
        v.sort();
        v
    }

    pub fn len(&self) -> usize {
        self.by_path.len()
    }

    pub fn is_empty(&self) -> bool {
        self.by_path.is_empty()
    }

    /// 写清单为 JSON(paths 相对 *root*).
    pub fn save(&self, out: &Path) -> std::io::Result<()> {
        let items: Vec<Value> = self
            .by_path
            .values()
            .map(|e| {
                serde_json::json!({"path": e.path, "size": e.size})
            })
            .collect();
        let text = crate::json_py::to_python_json(&Value::Array(items), 2);
        std::fs::write(out, text)
    }

    /// 从清单重建(local_path 退化为相对路径本身).
    pub fn load(manifest: &Path) -> std::io::Result<SoftPathIndex> {
        let text = std::fs::read_to_string(manifest)?;
        let data: Value = serde_json::from_str(&text)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
        let entries: Vec<AssetEntry> = data
            .as_array()
            .map(|arr| {
                arr.iter()
                    .filter_map(|e| {
                        let path = e.get("path")?.as_str()?.to_string();
                        let size = e.get("size").and_then(Value::as_u64).unwrap_or(0);
                        Some(AssetEntry { path: path.clone(), size, local_path: PathBuf::from(path) })
                    })
                    .collect()
            })
            .unwrap_or_default();
        Ok(SoftPathIndex { by_path: entries.into_iter().map(|e| (e.path.clone(), e)).collect() })
    }

    pub fn find(&self, path: &str) -> Option<&AssetEntry> {
        self.by_path.get(path)
    }
}

fn looks_like_sop(obj: &serde_json::Map<String, Value>) -> Option<(u64, String)> {
    if !SOP_KEYS.iter().all(|k| obj.contains_key(*k)) {
        return None;
    }
    let asset_hash = obj.get("AssetHash")?.as_u64()?;
    let path = obj.get("Path")?.as_str()?.to_string();
    Some((asset_hash, path))
}

fn walk_sop(obj: &Value, out: &mut HashMap<u64, String>) {
    match obj {
        Value::Object(map) => {
            if let Some((hash, path)) = looks_like_sop(map) {
                out.insert(hash, path);
            }
            for v in map.values() {
                walk_sop(v, out);
            }
        }
        Value::Array(items) => {
            for v in items {
                walk_sop(v, out);
            }
        }
        _ => {}
    }
}

/// 从编辑器 JSON 构建 `{AssetHash: path}`。
///
/// 遍历 *json_root*(如 `BinaryData/Config`), 挑出所有长得像编辑器
/// SoftObjectPath 的对象(含 `Name/Path/Type/AssetHash` 四键)。
pub fn extract_hash_map(json_root: &Path) -> HashMap<u64, String> {
    let mut paths: Vec<PathBuf> = Vec::new();
    let mut stack = vec![json_root.to_path_buf()];
    while let Some(dir) = stack.pop() {
        if dir.is_file() {
            if dir.extension().is_some_and(|e| e == "json") {
                paths.push(dir);
            }
            continue;
        }
        let Ok(rd) = std::fs::read_dir(&dir) else { continue };
        for entry in rd.flatten() {
            let p = entry.path();
            if p.is_dir() {
                stack.push(p);
            } else if p.extension().is_some_and(|e| e == "json") {
                paths.push(p);
            }
        }
    }
    let per_file: Vec<HashMap<u64, String>> = paths
        .par_iter()
        .filter_map(|p| {
            let text = std::fs::read_to_string(p).ok()?;
            let data: Value = serde_json::from_str(&text).ok()?;
            let mut out = HashMap::new();
            walk_sop(&data, &mut out);
            Some(out)
        })
        .collect();
    let mut result: HashMap<u64, String> = HashMap::new();
    for m in per_file {
        result.extend(m);
    }
    result
}

/// 把 AssetHash 映射为 depot-relative 路径(未知 → None).
pub fn resolve(hash_map: &HashMap<u64, String>, asset_hash: u64) -> Option<String> {
    hash_map.get(&asset_hash).cloned()
}

/// 取资源内容失败.
#[derive(Debug, thiserror::Error)]
pub enum SoftPathError {
    #[error("asset not available: {0}")]
    NotFound(String),
    #[error("io: {0}")]
    Io(#[from] std::io::Error),
    #[error("p4 print failed: {0}")]
    P4(String),
}

/// 资源内容提供者: 输入 depot-relative path, 输出文件内容 bytes(取不到为 None).
pub trait ContentProvider: Send + Sync {
    fn get_content(&self, path: &str) -> Option<Vec<u8>>;
}

/// [`ContentProvider`] 实现: 本地 workspace 优先, `p4 print` 兜底.
#[derive(Debug, Clone, Default)]
pub struct AssetLoader {
    pub workspace_root: Option<PathBuf>,
    pub p4_client: Option<String>,
}

impl ContentProvider for AssetLoader {
    fn get_content(&self, path: &str) -> Option<Vec<u8>> {
        get_content(path, self.workspace_root.as_deref(), self.p4_client.as_deref())
    }
}

thread_local! {
    static LOADER: RefCell<Option<Arc<dyn ContentProvider>>> = const { RefCell::new(None) };
}

/// 注入 provider 到当前线程, 返回 guard(离开作用域自动恢复).
pub struct AssetLoaderGuard;

impl Drop for AssetLoaderGuard {
    fn drop(&mut self) {
        LOADER.with(|cell| *cell.borrow_mut() = None);
    }
}

pub fn set_asset_loader(provider: Arc<dyn ContentProvider>) -> AssetLoaderGuard {
    LOADER.with(|cell| *cell.borrow_mut() = Some(provider));
    AssetLoaderGuard
}

/// 当前线程的 provider; 未注入则报错.
pub fn require_asset_loader() -> Result<Arc<dyn ContentProvider>, String> {
    LOADER.with(|cell| {
        cell.borrow()
            .as_ref()
            .cloned()
            .ok_or_else(|| "ContentProvider 未注入: 请先用 abc_db::softpath::asset_loader(...)".into())
    })
}

/// 作用域注入: 构造 [`AssetLoader`](或自定义 provider), 离开作用域自动恢复.
pub fn asset_loader(
    workspace_root: Option<PathBuf>,
    p4_client: Option<String>,
    provider: Option<Arc<dyn ContentProvider>>,
) -> AssetLoaderGuard {
    let impl_: Arc<dyn ContentProvider> = provider.unwrap_or_else(|| {
        Arc::new(AssetLoader { workspace_root, p4_client })
    });
    set_asset_loader(impl_)
}

/// 按 depot-relative *path* 取内容。
///
/// 优先级: 本地 workspace 文件(`workspace_root/path`) → `p4 print`
/// (`p4_client` = `-c` 参数)。取不到返回 None。
pub fn get_content(
    path: &str,
    workspace_root: Option<&Path>,
    p4_client: Option<&str>,
) -> Option<Vec<u8>> {
    if let Some(root) = workspace_root {
        let src = root.join(path);
        if src.is_file() {
            return std::fs::read(&src).ok();
        }
        warn!("local file missing: {}", src.display());
    }
    if let Some(client) = p4_client {
        if let Ok(data) = p4_print(path, client) {
            return Some(data);
        }
    }
    None
}

/// 通过 `p4 print` 从 depot 下载 *path* 的内容.
fn p4_print(path: &str, client: &str) -> Result<Vec<u8>, SoftPathError> {
    let depot_path = format!("//<depot>/main/ProjABC/{path}");
    let tmp_dir = tempfile::tempdir().map_err(SoftPathError::Io)?;
    let dest = tmp_dir.path().join(
        Path::new(path).file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default(),
    );
    let output = std::process::Command::new("p4")
        .args(["-c", client, "print", "-o"])
        .arg(&dest)
        .arg(&depot_path)
        .output()
        .map_err(|e| SoftPathError::P4(format!("p4 not found or failed: {e}")))?;
    if !output.status.success() {
        let msg = String::from_utf8_lossy(&output.stderr).trim().to_string();
        return Err(SoftPathError::P4(format!("p4 print failed for {depot_path}: {msg}")));
    }
    std::fs::read(&dest).map_err(SoftPathError::Io)
}

/// 把资源取到 *out_dir*。
///
/// 优先级: 本地 workspace 拷贝 → `p4 print`。返回写出的文件路径。
pub fn fetch(
    path: &str,
    out_dir: &Path,
    workspace_root: Option<&Path>,
    p4_client: Option<&str>,
) -> Result<PathBuf, SoftPathError> {
    let Some(data) = get_content(path, workspace_root, p4_client) else {
        return Err(SoftPathError::NotFound(path.to_string()));
    };
    std::fs::create_dir_all(out_dir)?;
    let dest = out_dir.join(Path::new(path).file_name().unwrap_or_default());
    std::fs::write(&dest, data)?;
    Ok(dest)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn index_build_skips_meta() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().join("SpriteOutput");
        std::fs::create_dir_all(root.join("Avatar/Avatar2048")).unwrap();
        std::fs::create_dir_all(root.join("Skill/IconSkill256")).unwrap();
        std::fs::write(root.join("Avatar/Avatar2048/222_00.png"), b"fake-png-bytes").unwrap();
        std::fs::write(root.join("Avatar/Avatar2048/222_00.png.meta"), "guid: abc\n").unwrap();
        std::fs::write(root.join("Skill/IconSkill256/100_01.png"), b"x").unwrap();
        let index = SoftPathIndex::build(&root);
        assert_eq!(index.len(), 2);
        assert!(index.paths().iter().any(|p| p == "Avatar/Avatar2048/222_00.png"));
        assert!(index.paths().iter().all(|p| !p.contains(".meta")));
    }

    #[test]
    fn index_save_load_roundtrip() {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path().join("SpriteOutput");
        std::fs::create_dir_all(root.join("Avatar")).unwrap();
        std::fs::write(root.join("Avatar/222_00.png"), b"fake-png-bytes").unwrap();
        let index = SoftPathIndex::build(&root);
        let manifest = dir.path().join("manifest.json");
        index.save(&manifest).unwrap();
        let loaded = SoftPathIndex::load(&manifest).unwrap();
        assert_eq!(loaded.paths(), index.paths());
        let entry = loaded.find("Avatar/222_00.png").unwrap();
        assert_eq!(entry.size, b"fake-png-bytes".len() as u64);
    }

    #[test]
    fn extract_hash_map_walks_nested() {
        let dir = tempfile::tempdir().unwrap();
        let cfg = dir.path().join("cfg");
        std::fs::create_dir_all(&cfg).unwrap();
        std::fs::write(
            cfg.join("a.json"),
            r#"{"Soft": {"Name": "222_00", "Path": "Assets/Res/SpriteOutput/Avatar/222_00.png", "Type": "UnityEngine.Sprite", "AssetHash": 123456789}}"#,
        )
        .unwrap();
        std::fs::write(
            cfg.join("b.json"),
            r#"{"Nested": [{"AssetHash": 1, "Path": "p.png", "Type": "T", "Name": "n"}]}"#,
        )
        .unwrap();
        std::fs::write(cfg.join("c.json"), r#"{"NoSop": 1}"#).unwrap();
