{"content": "//! abc-db CLI.

use std::path::PathBuf;

use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "abc-db", version, about = "ABC 项目配置数据解析工具(Rust 实现)")]
pub struct Cli {
    #[command(subcommand)]
    pub cmd: Command,
}

#[derive(Subcommand)]
pub enum Command {
    /// 从 proto 重新生成 registry 快照(内嵌 src/registry_snapshot.json).
    GenRegistry {
        /// proto 根目录(默认 ABC_PROTO_ROOT 或本机 P4 workspace).
        #[arg(long)]
        proto_root: Option<PathBuf>,
        /// 输出路径(默认 src/registry_snapshot.json).
        #[arg(long)]
        output: Option<PathBuf>,
    },
    /// SoftObjectPath 资源解析.
    Softpath {
        #[command(subcommand)]
        cmd: SoftpathCmd,
    },
    /// TextMap 文案查询.
    Textmap {
        #[command(subcommand)]
        cmd: TextmapCmd,
    },
    /// WIKI 静态站点构建.
    Wiki {
        /// 输出目录(默认 output/wiki).
        #[arg(long, default_value = "output/wiki")]
        out: PathBuf,
    },
    /// 角色(TrainerCommonConfig)全量导出(引用解析 + 13 语 map).
    Roles {
        /// 输出路径(默认 output/roles.json).
        #[arg(long, default_value = "output/roles.json")]
        out: PathBuf,
    },
    /// 心象名称/原画/技能端到端提取示例.
    ExtractTrainers,
    /// 生成 wiki-app 前端数据(profiles.ts + 资源取回).
    FrontendData,
}

#[derive(Subcommand)]
pub enum SoftpathCmd {
    /// 扫描资源目录生成清单.
    Index {
        root: PathBuf,
        #[arg(long)]
        output: Option<PathBuf>,
    },
    /// 列出清单.
    List {
        #[arg(long, default_value = "output/softpath-index.json")]
        manifest: PathBuf,
    },
    /// 解析 AssetHash → 路径(经编辑器 JSON 提取的 hash 映射).
    Resolve {
        hash: u64,
        #[arg(long)]
        json_root: PathBuf,
    },
    /// 取资源到输出目录.
    Fetch {
        path: String,
        out: PathBuf,
        #[arg(long)]
        workspace_root: Option<PathBuf>,
        #[arg(long)]
        p4_client: Option<String>,
    },
}

#[derive(Subcommand)]
pub enum TextmapCmd {
    /// 按 TextMapHashID 查 13 语文案.
    Lookup {
        hash: u64,
        #[arg(long)]
        root: PathBuf,
    },
}

/// 默认数据根(ABC_BIN_ROOT 或本机 P4 workspace).
pub fn default_bin_root() -> PathBuf {
    std::env::var_os("ABC_BIN_ROOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(
                "~/Perforce/ABC_Project_<client>/ProjABC/BinaryData/Config",
            )
        })
}
", "file_path": "src/cli.rs"}

