{"content": "//! abc-db 二进制入口.

mod cli;

use std::path::PathBuf;
use std::process::ExitCode;

use clap::Parser;

use abc_db::registry::default_proto_root;

use crate::cli::{Cli, Command, SoftpathCmd, TextmapCmd};

/// 极简 stderr logger(log crate 实现).
struct StderrLogger;
impl log::Log for StderrLogger {
    fn enabled(&self, _metadata: &log::Metadata) -> bool {
        true
    }
    fn log(&self, record: &log::Record) {
        eprintln!("[{}] {}", record.level(), record.args());
    }
    fn flush(&self) {}
}

fn main() -> ExitCode {
    let _ = log::set_logger(&StderrLogger);
    log::set_max_level(log::LevelFilter::Info);
    let cli = Cli::parse();
    match run(cli) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

fn run(cli: Cli) -> Result<(), Box<dyn std::error::Error>> {
    match cli.cmd {
        Command::GenRegistry { proto_root, output } => {
            let root = proto_root.unwrap_or_else(default_proto_root);
            let reg = abc_db::registry::build_registry_from_protos(&root)?;
            let text = abc_db::registry::registry_to_json(&reg);
            let out = output.unwrap_or_else(|| PathBuf::from("src/registry_snapshot.json"));
            std::fs::write(&out, text)?;
            println!(
                "registry: {} loaders, {} super_fields, {} refs, {} enum_key_maps, {} streaming → {}",
                reg.loaders.len(),
                reg.super_fields.len(),
                reg.refs.len(),
                reg.enum_key_maps.len(),
                reg.streaming_messages.len(),
                out.display()
            );
            Ok(())
        }
        Command::Softpath { cmd } => match cmd {
            SoftpathCmd::Index { root, output } => {
                let index = abc_db::softpath::SoftPathIndex::build(&root);
                let out = output.unwrap_or_else(|| PathBuf::from("output/softpath-index.json"));
                index.save(&out)?;
                println!("indexed {} assets → {}", index.len(), out.display());
                Ok(())
            }
            SoftpathCmd::List { manifest } => {
                let index = abc_db::softpath::SoftPathIndex::load(&manifest)?;
                println!("{} assets:", index.len());
                for p in index.paths() {
                    println!("  {p}");
                }
                Ok(())
            }
            SoftpathCmd::Resolve { hash, json_root } => {
                let map = abc_db::softpath::extract_hash_map(&json_root);
                match abc_db::softpath::resolve(&map, hash) {
                    Some(path) => {
                        println!("{path}");
                        Ok(())
                    }
                    None => Err(format!("no asset path for hash {hash}").into()),
                }
            }
            SoftpathCmd::Fetch { path, out, workspace_root, p4_client } => {
                let dest = abc_db::softpath::fetch(
                    &path,
                    &out,
                    workspace_root.as_deref(),
                    p4_client.as_deref(),
                )?;
                println!("{}", dest.display());
                Ok(())
            }
        },
        Command::Textmap { cmd } => match cmd {
            TextmapCmd::Lookup { hash, root } => {
                let index = abc_db::textmap::TextMapIndex::open(&root);
                let codes = index.lookup_codes(hash);
                if codes.is_empty() {
                    println!("(no entry for hash {hash})");
                }
                for (lang, text) in codes {
                    println!("{lang}\t{text}");
                }
                Ok(())
            }
        },
        Command::Wiki { out } => {
            let root = crate::cli::default_bin_root();
            let stats = abc_db::wiki::build_wiki_site(&root, &out)?;
            println!(
                "wiki built: {} pages, {} images, {:.1} MB → {}",
                stats.pages, stats.images, stats.size_mb, out.display()
            );
            Ok(())
        }
        Command::Roles { out } => {
            let root = crate::cli::default_bin_root();
            let count = abc_db::wiki::export_roles(&root, &out)?;
            println!("roles: {count} → {}", out.display());
            Ok(())
        }
        Command::ExtractTrainers => {
            let root = crate::cli::default_bin_root();
            abc_db::wiki::extract_trainers_demo(&root)?;
            Ok(())
        }
        Command::FrontendData => {
            let root = crate::cli::default_bin_root();
            abc_db::wiki::gen_frontend_data(&root)?;
            Ok(())
        }
    }
}
", "file_path": "src/main.rs"}

