/// typed 模型错误(严格验证失败/IO 失败).
#[derive(Debug, thiserror::Error)]
pub enum ModelError {
    #[error("json: {0}")]
    Json(#[from] serde_json::Error),
    #[error("io: {0}")]
    Io(#[from] std::io::Error),
    #[error("{0}")]
    Message(String),
}

/// 语言(enum.proto; 名字=短码, 值=proto 枚举值).
