/// proto 字符串枚举宏: 数据值为枚举名字符串, 严格解析, 缺省取首成员.
macro_rules! proto_str_enum {
    ($(#[$meta:meta])* pub enum $name:ident { $($var:ident = $val:literal),+ $(,)? }) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
        pub enum $name { $($var),+ }

        impl $name {
            pub fn from_str_name(s: &str) -> Option<Self> {
                match s {
                    $($val => Some(Self::$var),)+
                    _ => None,
                }
            }
            pub fn str_name(self) -> &'static str {
                match self {
                    $(Self::$var => $val,)+
                }
            }
        }

        impl Default for $name {
            fn default() -> Self { Self::$name::first() }
        }

        impl $name {
            const fn first() -> Self {
                // 取第一个成员(proto 0 号成员约定)
                #[allow(non_upper_case_globals)]
                const FIRST: $name = $name::$first_variant;
                FIRST
            }
        }

        impl std::str::FromStr for $name {
            type Err = String;
            fn from_str(s: &str) -> Result<Self, Self::Err> {
                Self::from_str_name(s).ok_or_else(|| format!("invalid {}: {s}", stringify!($name)))
            }
        }

        impl Serialize for $name {
            fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
                s.serialize_str(self.str_name())
            }
        }

        impl<'de> Deserialize<'de> for $name {
            fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
                struct V;
                impl<'de> serde::de::Visitor<'de> for V {
                    type Value = $name;
                    fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                        write!(f, "a {} enum name string", stringify!($name))
                    }
                    fn visit_str<E: serde::de::Error>(self, s: &str) -> Result<Self::Value, E> {
                        $name::from_str_name(s)
                            .ok_or_else(|| E::custom(format!("invalid {}: {s}", stringify!($name))))
                    }
                }
                d.deserialize_str(V)
            }
        }
    };
}

/// 配置表条目公共基类(super_field_name 组合进业务模型).
///
/// 来源: Table/TableItemBase.proto; EditorIndex/EditorName 为 FIELD_NOT_ALL
/// (编辑器专用, JSON 里有, bin 无)。
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct TableItemBase {
    #[serde(rename = "EditorIndex", alias = "editor_index", default, skip_serializing_if = "Option::is_none")]
    pub editor_index: Option<i64>,
    #[serde(rename = "EditorName", alias = "editor_name", default, skip_serializing_if = "Option::is_none")]
    pub editor_name: Option<String>,
}

/// 本地化文本引用. 正式键为 TextMapHashID(13 语/翻译管线);
/// Context/TextMapID 为编辑器内嵌。lang_map 为派生字段(resolve 时注入)。
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct FText {
    #[serde(rename = "TextMapHashID", alias = "text_map_hash_id")]
    pub text_map_hash_id: u64,
    #[serde(rename = "Context", alias = "context", default, skip_serializing_if = "Option::is_none")]
    pub context: Option<String>,
    #[serde(rename = "TextMapID", alias = "text_map_id", default, skip_serializing_if = "Option::is_none")]
    pub text_map_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lang_map: Option<HashMap<Language, String>>,
}

impl FText {
    /// 注入 13 语 map(resolve 阶段; 源 JSON 无此键).
    pub fn inject_lang_map(&mut self, textmap: &TextMapIndex) {
        let langs = textmap.lookup(self.text_map_hash_id);
        let map = langs
            .into_iter()
            .filter_map(|(v, text)| Language::from_value(v as i64).map(|lang| (lang, text)))
            .collect();
        self.lang_map = Some(map);
    }
}

/// 资源引用. 正式键为 AssetHash; Name/Path/Type 为编辑器内嵌(运行时已剥离).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct SoftObjectPath {
    #[serde(rename = "AssetHash", alias = "asset_hash")]
    pub asset_hash: u64,
    #[serde(rename = "Name", alias = "name", default, skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    #[serde(rename = "Path", alias = "path", default, skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
    #[serde(rename = "Type", alias = "type", default, skip_serializing_if = "Option::is_none")]
    pub type_: Option<String>,
}

impl SoftObjectPath {
    /// 取资源内容: 从当前线程取注入的 ContentProvider.
    ///
    /// provider 未注入时报错; 本对象无 Path 或资源不可用时返回 None。
    pub fn get_content(&self) -> Result<Option<Vec<u8>>, String> {
        let Some(path) = &self.path else { return Ok(None) };
        let provider = softpath::require_asset_loader()?;
        Ok(provider.get_content(path))
    }
}

/// 物品+数量(奖励/消耗通用). ItemID 为 RowKeyReference → ItemTable.ID.
///
/// item_id 运行时解析为 ItemConfig(Table/Item); 无 resolver 时保持原始 ID。
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ItemData {
    #[serde(rename = "ItemID", alias = "item_id", default, skip_serializing_if = "Option::is_none")]
    pub item_id: Option<RefOpt<crate::typed::item_config::ItemConfig>>,
    #[serde(rename = "Num", alias = "num", default)]
    pub num: i64,
}

/// 引用字段值: 原始 ID(解析前) 或 目标模型(解析后).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum RefOpt<T> {
    Raw(i64),
    Resolved(Arc<T>),
}

impl<T> RefOpt<T> {
    pub fn raw_id(&self) -> Option<i64> {
        match self {
            RefOpt::Raw(id) => Some(*id),
            RefOpt::Resolved(_) => None,
        }
    }

    pub fn as_model(&self) -> Option<&T> {
        match self {
            RefOpt::Raw(_) => None,
            RefOpt::Resolved(m) => Some(m.as_ref()),
        }
    }
}

impl<T: PartialEq> PartialEq for RefOpt<T> {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (RefOpt::Raw(a), RefOpt::Raw(b)) => a == b,
            (RefOpt::Resolved(a), RefOpt::Resolved(b)) => a == b,
            _ => false,
        }
    }
}

/// 玩法语义标签(如 AdvControl.MuteMove).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct GameplayTag {
    #[serde(rename = "Tag", alias = "tag")]
    pub tag: String,
}

/// 玩法语义标签容器.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct GameplayTagContainer {
    #[serde(rename = "Tags", alias = "tags", default)]
    pub tags: Vec<GameplayTag>,
}

/// 32 位定点数(战斗数值; 避免浮点误差).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Fixed {
    #[serde(rename = "Raw", alias = "raw")]
    pub raw: i64,
    #[serde(rename = "RealValue", alias = "real_value")]
    pub real_value: f64,
}

/// `$type` 多态组件/条件的宽松容器(extra 字段全保留).
///
/// 来源: 实体 InitComponents 等 google.protobuf.Any 字段的 JSON 形态
/// `{"$type": "/pd.XxxConfig", ...}`; 仅校验 `$type`, 其余字段原样保留。
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct AnyComponent {
    #[serde(rename = "$type", default, skip_serializing_if = "Option::is_none")]
    pub type_: Option<String>,
    #[serde(flatten)]
    pub extra: Map<String, Value>,
}

/// 表元数据(对应 Python `__table__`).
#[derive(Debug, Clone, Copy)]
pub struct TableMeta {
    pub load_path: &'static str,
    /// 单文件表顶层列表键; 目录型为 None(文件名 = 索引值).
    pub entry_field: Option<&'static str>,
    /// 单文件表索引键.
    pub index_key: &'static str,
}

/// 表模型: 解析 + 引用解析两阶段接口.
pub trait TableModel: Sized + Send + Sync + 'static {
    const TABLE: TableMeta;

    /// 严格解析(无 resolver/textmap; 引用字段保持原始 ID).
    fn from_value(v: &Value) -> Result<Self, ModelError>;

    /// 引用解析: refs 解析跨表引用, textmap 注入 FText.lang_map.
    fn resolve(
        &mut self,
        refs: Option<&crate::typed::refs::RefResolver>,
        textmap: Option<&TextMapIndex>,
    ) -> Result<(), ModelError>;
}

/// 显式 null 列表字段辅助: `null` → None, 缺失 → None, 数组 → Some(vec).
pub fn de_opt_list<'de, D, T>(d: D) -> Result<Option<Vec<T>>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: Deserialize<'de>,
{
    let v = Option::<Vec<T>>::deserialize(d)?;
    Ok(v)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn language_roundtrip() {
        assert_eq!(Language::from_value(1), Some(Language::SC));
        assert_eq!(Language::from_value(13), Some(Language::ID));
        assert_eq!(Language::from_value(0), None);
        assert_eq!(serde_json::to_value(Language::SC).unwrap(), json!(1));
        let m: HashMap<Language, String> = HashMap::from([(Language::SC, "刃".into())]);
        assert_eq!(
            serde_json::to_value(m).unwrap(),
            json!({"1": "刃"})
        );
    }

    proto_str_enum! {
        /// 测试枚举.
        pub enum TestEnum { ZERO = "TEST_ZERO", ONE = "TEST_ONE" }
    }

    #[test]
    fn proto_str_enum_works() {
        assert_eq!(TestEnum::from_str_name("TEST_ONE"), Some(TestEnum::ONE));
        assert_eq!(TestEnum::default(), TestEnum::ZERO);
        assert_eq!(serde_json::to_string(&TestEnum::ONE).unwrap(), "\"TEST_ONE\"");
        let v: TestEnum = serde_json::from_value(json!("TEST_ZERO")).unwrap();
        assert_eq!(v, TestEnum::ZERO);
        assert!(serde_json::from_value::<TestEnum>(json!("NOPE")).is_err());
        assert!(serde_json::from_value::<TestEnum>(json!(1)).is_err());
    }

    #[test]
    fn ftext_inject_lang_map() {
        let mut tm = crate::textmap::TextMapIndex::default();
        tm.hash_langs.insert(5, HashMap::from([(1, "刃".into()), (3, "Blade".into())]));
        let mut f = FText { text_map_hash_id: 5, ..Default::default() };
        f.inject_lang_map(&tm);
        let map = f.lang_map.unwrap();
        assert_eq!(map.get(&Language::SC).map(String::as_str), Some("刃"));
        assert_eq!(map.get(&Language::EN).map(String::as_str), Some("Blade"));
    }

    #[test]
    fn ref_opt_untagged() {
        let v: RefOpt<i64> = serde_json::from_value(json!(10)).unwrap();
        assert_eq!(v, RefOpt::Raw(10));
        assert!(serde_json::from_value::<RefOpt<i64>>(json!({"a": 1})).is_err());
    }
}
