{"content": "//! typed 模型的运行时引用解析.
//!
//! 模型在 `TableModel::TABLE` 声明表元数据(load_path / entry_field /
//! index_key); [`RefResolver::load`] 按需加载目标条目(单文件表查 entry
//! 字段, 目录表读 `{id}.json`), 按 `(load_path, id)` 缓存, 递归解析嵌套
//! 引用, 环通过 loading 栈返回 None(宽松)。缺 id/缺文件也返回 None。

use std::any::Any;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use log::warn;
use serde_json::Value;

use crate::textmap::TextMapIndex;
use crate::typed::common::{ModelError, TableModel};

/// 按需跨表引用加载器(缓存 + 环守卫).
pub struct RefResolver {
    root: PathBuf,
    textmap: Option<Arc<TextMapIndex>>,
    inner: Mutex<Inner>,
}

struct Inner {
    cache: std::collections::HashMap<&'static str, std::collections::HashMap<i64, Arc<dyn Any + Send + Sync>>>,
    loading: Vec<&'static str>,
}

impl RefResolver {
    pub fn new(root: impl Into<PathBuf>, textmap: Option<Arc<TextMapIndex>>) -> RefResolver {
        RefResolver {
            root: root.into(),
            textmap,
            inner: Mutex::new(Inner { cache: Default::default(), loading: Vec::new() }),
        }
    }

    /// 加载一条被引用条目(宽松: 缺 id/缺条目/环 → None).
    pub fn load<T: TableModel>(&self, entry_id: Option<i64>) -> Result<Option<Arc<T>>, ModelError> {
        let Some(entry_id) = entry_id else { return Ok(None) };
        let name = <T as TableModel>::TABLE.load_path;
        let mut inner = self.inner.lock().unwrap();
        if let Some(cached) = inner.cache.get(name).and_then(|m| m.get(&entry_id)) {
            return Ok(Some(cached.clone().downcast::<T>().expect("cache type mismatch")));
        }
        if inner.loading.contains(&name) {
            warn!("reference cycle detected at {name}");
            return Ok(None);
        }
        inner.loading.push(name);
        let instance = self.load_entry::<T>(entry_id);
        inner.loading.pop();
        let instance = instance?;
        if let Some(instance) = &instance {
            inner
                .cache
                .entry(name)
                .or_default()
                .insert(entry_id, instance.clone() as Arc<dyn Any + Send + Sync>);
        }
        Ok(instance)
    }

    fn load_entry<T: TableModel>(&self, entry_id: i64) -> Result<Option<Arc<T>>, ModelError> {
        let meta = <T as TableModel>::TABLE;
        let raw = if let Some(entry_field) = meta.entry_field {
            // 单文件表: {root}/{load_path}.json → entry_field 列表 → 按 index_key 匹配
            let path = self.root.join(format!("{}.json", meta.load_path));
            let data: Value = read_json(&path)?;
            let Some(list) = data.get(entry_field).and_then(Value::as_array) else {
                return Ok(None);
            };
            list.iter()
                .find(|item| item.get(meta.index_key).and_then(Value::as_i64) == Some(entry_id))
                .cloned()
        } else {
            // 目录型: {root}/{load_path}/{entry_id}.json
            let path = self.root.join(&meta.load_path).join(format!("{entry_id}.json"));
            if !path.is_file() {
                return Ok(None);
            }
            Some(read_json(&path)?)
        };
        let Some(raw) = raw else { return Ok(None) };
        let mut model = T::from_value(&raw)?;
        model.resolve(Some(self), self.textmap.as_deref())?;
        Ok(Some(Arc::new(model)))
    }
}

fn read_json(path: &Path) -> Result<Value, ModelError> {
    let text = std::fs::read_to_string(path)?;
    Ok(serde_json::from_str(&text)?)
}

/// 通用表加载: RefResolver(+TextMapIndex) 组装, 逐条严格解析.
///
/// `resolve=true`: 引用字段解析为目标模型实例(惰性+缓存+环安全)。
/// `resolve_textmap=true`: 构建 TextMapIndex, 所有 FText.lang_map 注入
/// 13 语 map(含经 RefResolver 加载的引用表条目)。
pub fn load_entries<T: TableModel>(
    root: impl AsRef<Path>,
    resolve: bool,
    resolve_textmap: bool,
) -> Result<Vec<T>, ModelError> {
    let root = root.as_ref().to_path_buf();
    let textmap = if resolve_textmap {
        Some(Arc::new(TextMapIndex::open(&root)))
    } else {
        None
    };
    let refs = if resolve {
        Some(RefResolver::new(&root, textmap.clone()))
    } else {
        None
    };
    let meta = <T as TableModel>::TABLE;
    let path = root.join(format!("{}.json", meta.load_path));
    let data: Value = read_json(&path)?;
    let Some(entry_field) = meta.entry_field else {
        return Err(ModelError::Message(format!(
            "load_entries requires single-file table: {}",
            meta.load_path
        )));
    };
    let list = data
        .get(entry_field)
        .and_then(Value::as_array)
        .ok_or_else(|| ModelError::Message(format!("no entry field {entry_field} in {path:?}")))?;
    let mut out = Vec::with_capacity(list.len());
    for entry in list {
        let mut model = T::from_value(entry)?;
        model.resolve(refs.as_ref(), textmap.as_deref())?;
        out.push(model);
    }
    Ok(out)
}
