fn bin_root() -> PathBuf {
    std::env::var_os("ABC_BIN_ROOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(
                "~/Perforce/ABC_Project_<client>/ProjABC/BinaryData/Config",
            )
        })
}

fn data_available() -> bool {
    bin_root().join("Table/TrainerCommon.json").is_file()
}

#[test]
fn alias_field_mapping() {
    let cfg: TrainerCommonConfig = serde_json::from_value(serde_json::json!({
        "ID": 7,
        "Name": {"TextMapHashID": 123},
        "GachaResultPhoto": {"AssetHash": 9},
    }))
    .unwrap();
    assert_eq!(cfg.id, 7);
    assert_eq!(cfg.name, Some(FText { text_map_hash_id: 123, ..Default::default() }));
    assert_eq!(
        cfg.gacha_result_photo,
        Some(SoftObjectPath { asset_hash: 9, ..Default::default() })
    );
}

#[test]
fn populate_by_name() {
    let cfg: TrainerCommonConfig = serde_json::from_value(serde_json::json!({
        "id": 3,
        "name": {"text_map_hash_id": 1},
    }))
    .unwrap();
    assert_eq!(cfg.id, 3);
    assert_eq!(cfg.name.unwrap().text_map_hash_id, 1);
}

#[test]
fn common_models() {
    let ftext: FText =
        serde_json::from_value(serde_json::json!({"TextMapHashID": 1, "Context": "刃", "TextMapID": "x"}))
            .unwrap();
    assert_eq!(ftext.context.as_deref(), Some("刃"));
    let item: ItemData = serde_json::from_value(serde_json::json!({"ItemID": 5, "Num": 2})).unwrap();
    assert_eq!(item.item_id, Some(RefOpt::Raw(5)));
    let base: TableItemBase =
        serde_json::from_value(serde_json::json!({"EditorName": "0.2"})).unwrap();
    assert_eq!(base.editor_name.as_deref(), Some("0.2"));
}

#[test]
fn load_all_real_data() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let rows = load_all(&bin_root(), true, false).unwrap();
    assert_eq!(rows.len(), 29);
    let t22200 = rows.iter().find(|r| r.id == 22200).unwrap();
    assert_eq!(t22200.name.as_ref().unwrap().context.as_deref(), Some("刃"));
    let costs = t22200.rank_up_cost.as_ref().unwrap();
    assert_eq!(costs[0].rank, 0);
    assert_eq!(
        t22200.adv_character_entity_config_id_json_config_type.as_deref(),
        Some("AdvCharacterEntityConfig")
    );
}

#[test]
fn reference_resolution() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let rows = load_all(&bin_root(), true, false).unwrap();
    let t22200 = rows.iter().find(|r| r.id == 22200).unwrap();
    // tag → TrainerTagConfig(单文件表)
    let tag = t22200.tag.as_ref().unwrap().as_model().unwrap();
    assert_eq!(tag.id, 10);
    assert_eq!(tag.tag_desc.as_ref().unwrap().context.as_deref(), Some("单体增益"));
    // 实体(目录型)引用
    let adv = t22200
        .adv_character_entity_config_id
        .as_ref()
        .unwrap()
        .as_model()
        .unwrap();
    assert_eq!(adv.role_id, 22200);
    assert!(t22200.ui_entity_config.as_ref().unwrap().as_model().is_some());
    // 组件($type 多态)
    let comps = &adv.base.init_components;
    assert_eq!(comps.len(), 19);
    assert_eq!(
        comps[0].type_.as_deref(),
        Some("/pd.AdvPerceptionEntityComponentConfig")
    );
    // 嵌套 ItemData → ItemConfig
    let items: Vec<&ItemData> = t22200
        .rank_up_cost
        .iter()
        .flat_map(|c| c.rank_up_cost.iter())
        .chain(t22200.repeat_get_reward.iter().flatten())
        .collect();
