    assert_eq!(null_row.id, 30000);
    assert!(null_row.level_reward_list.is_none());
}

#[test]
fn round_trip_fidelity() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let text = std::fs::read_to_string(bin_root().join("Table/TrainerCommon.json")).unwrap();
    let data: serde_json::Value = serde_json::from_str(&text).unwrap();
    for entry in data.get("TrainerList").unwrap().as_array().unwrap() {
        let model: TrainerCommonConfig = serde_json::from_value(entry.clone()).unwrap();
        let dumped = serde_json::to_value(&model).unwrap();
        let src = entry.as_object().unwrap();
        let dst = dumped.as_object().unwrap();
        for (key, source_val) in src {
            let dumped_val = dst.get(key);
            match source_val {
                serde_json::Value::Null => {
                    // exclude_none: 源 null 在 dump 中缺失 → 视为相等
                    assert!(dumped_val.is_none() || dumped_val == Some(&serde_json::Value::Null), "{key}");
                }
                serde_json::Value::Object(_) => {
                    if let Some(serde_json::Value::Object(dv)) = dumped_val {
                        let src_filtered: serde_json::Map<String, serde_json::Value> = src
                            .get(key)
                            .unwrap()
                            .as_object()
                            .unwrap()
                            .iter()
                            .filter(|(_, v)| !v.is_null())
                            .map(|(k, v)| (k.clone(), v.clone()))
                            .collect();
                        assert_eq!(&src_filtered, dv, "{key}");
                    } else {
                        panic!("{key}: expected object, got {dumped_val:?}");
                    }
                }
                _ => assert_eq!(source_val, dumped_val.expect(key), "{key}"),
            }
        }
    }
}

#[test]
fn serialization_outputs_instances() {
    // resolve=True 时 dump 出嵌套实例 dict, 不是原始 ID
    let t = TrainerCommonConfig {
        tag: Some(RefOpt::Resolved(std::sync::Arc::new(TrainerTagConfig {
            id: 10,
            tag_desc: Some(FText { text_map_hash_id: 1, ..Default::default() }),
            ..Default::default()
        }))),
        rank_up_cost: Some(vec![TrainerRankUpCost {
            rank: 0,
            rank_up_cost: vec![ItemData {
                item_id: Some(RefOpt::Resolved(std::sync::Arc::new(ItemConfig {
                    id: 400136,
                    ..Default::default()
                }))),
                num: 1,
            }],
        }]),
        ..Default::default()
    };
    let dumped = serde_json::to_value(&t).unwrap();
    let tag = dumped.get("Tag").unwrap();
    assert_eq!(tag.get("ID").unwrap(), &serde_json::json!(10));
    let item = &dumped.get("RankUpCost").unwrap()[0]["RankUpCost"][0]["ItemID"];
    assert_eq!(item.get("ID").unwrap(), &serde_json::json!(400136));
}

#[test]
fn enum_parsing() {
    let cfg: ItemConfig = serde_json::from_value(serde_json::json!({
        "ID": 1,
        "Type": "ITEM_TYPE_VIRTUAL",
        "SubType": "ITEM_SUB_TYPE_VIRTUAL",
        "UseType": "ITEM_USE_TYPE_NONE",
        "OverrideInventoryType": "InventoryTabType_None",
        "RedDotLevel": "ItemRedDotLevel_SelfOnly",
        "RewardSortingOrderType": "RewardSortingOrderType_Scoin",
    }))
    .unwrap();
    assert_eq!(cfg.type_, ItemType::VIRTUAL);
    assert_eq!(cfg.use_type, ItemUseType::NONE);
    assert!(serde_json::from_value::<ItemConfig>(serde_json::json!({"ID": 1, "Type": "ITEM_TYPE_UNKNOWN"}))
        .is_err());
    assert!(serde_json::from_value::<ItemConfig>(serde_json::json!({"ID": 1, "UseType": "NOPE"})).is_err());
}

#[test]
fn enum_defaults() {
    let cfg: ItemConfig = serde_json::from_value(serde_json::json!({"ID": 1})).unwrap();
    assert_eq!(cfg.type_, ItemType::NONE);
}

#[test]
fn item_real_data_enums() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let text = std::fs::read_to_string(bin_root().join("Table/Item.json")).unwrap();
    let data: serde_json::Value = serde_json::from_str(&text).unwrap();
    let resolver = RefResolver::new(&bin_root(), None);
    let rows: Vec<ItemConfig> = data
        .get("ItemList")
        .unwrap()
        .as_array()
        .unwrap()
        .iter()
        .map(|e| {
            let mut m = ItemConfig::from_value(e).unwrap();
            m.resolve(Some(&resolver), None).unwrap();
            m
        })
        .collect();
    assert_eq!(rows.len(), 1226);
    assert!(rows.iter().all(|r| r.type_ != ItemType::NONE || r.id == 0));
}

#[test]
fn ftext_lang_map_injection() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let rows = load_all(&bin_root(), true, true).unwrap();
    let t22200 = rows.iter().find(|r| r.id == 22200).unwrap();
    let name = t22200.name.as_ref().unwrap();
    let lang_map = name.lang_map.as_ref().unwrap();
    assert_eq!(lang_map.get(&Language::SC).map(String::as_str), Some("刃"));
    let story = t22200.story.as_ref().unwrap();
    assert!(story.lang_map.is_some());
}

#[test]
fn strict_validation_errors() {
    for bad in [
        serde_json::json!({"ID": "abc"}),
        serde_json::json!({"Name": {"TextMapHashID": "x"}}),
        serde_json::json!({"RankUpCost": [{"Rank": "高"}]}),
        serde_json::json!({"GachaResultPhoto": {"AssetHash": 1, "Path": 123}}),
    ] {
        assert!(serde_json::from_value::<TrainerCommonConfig>(bad).is_err(), "expected error");
    }
}

#[test]
fn missing_fields_defaults() {
    let cfg: TrainerCommonConfig = serde_json::from_value(serde_json::json!({"ID": 1})).unwrap();
    assert_eq!(cfg.id, 1);
    assert!(cfg.name.is_none());
    assert!(cfg.rank_up_cost.is_none());
    assert!(!cfg.coming_soon);
}

#[test]
fn sub_models() {
    let r: TrainerRankUpCost =
        serde_json::from_value(serde_json::json!({"Rank": 1, "RankUpCost": [{"ItemID": 4, "Num": 1}]}))
            .unwrap();
    assert_eq!(r.rank_up_cost[0].item_id, Some(RefOpt::Raw(4)));
    let lvl: LevelRewardConfig = serde_json::from_value(serde_json::json!({"Level": 10, "RewardID": 611})).unwrap();
    assert_eq!(lvl.reward_id, 611);
}
