                            .filter(|(_, v)| !v.is_null())
                            .map(|(k, v)| (k.clone(), v.clone()))
                            .collect();
                        assert_eq!(&src_filtered, dv, "{key}");
                    } else {
                        panic!("{key}: expected object, got {dumped_val:?}");
                    }
                }
                _ => assert_eq!(source_val, dumped_val.expect(key), "{key}"),
            }
        }
    }
}

