{"content": "//! 导出层(函数式): 按 definitions 中的 table 定义加载数据并导出为纯 dict(JSON).
//!
//! 约定(与 Python 版一致):
//! - 字段名 = definitions.FieldDef.key(英文字段, 与需求表字段一一对应)
//! - FText → 简体中文纯文本(不要 textmap 多语言 map)
//! - fixed 定点数 RealValue 保留源字符串
//! - 顶层 row 的键 ⊆ 该表定义的字段键(「只要这些字段」由 validate 强制)
//!
//! 行形状: `serde_json::Map<String, Value>`(键插入序 = Python dict 构造序,
//! 保证导出 JSON 字节一致)。类型化访问器 `entries_of/entries_by_of/dir_entry_of`
//! 在 Python 端只是 TypedDict 标注, Rust 端同样无运行时开销。

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use indexmap::IndexMap;
use log::{info, warn};
use serde_json::{Map, Value};

use crate::components;
use crate::jsonconfig;
use crate::registry::{Registry, build_registry};
use crate::textmap::TextMapIndex;
use crate::value_ext::JsonExt;

use super::definitions::{ALL_TABLES, TableDef};

/// 行 = 字符串键 → JSON 值的对象(键序 = 插入序).
pub type Row = Map<String, Value>;

/// 缓存键: 单文件表(load_path) 或 目录型单条(load_path, index).
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum CacheKey {
    Table(String),
    Dir(String, i64),
}

/// 冻结上下文: 提取管线的显式上下文(root / registry / textmap / 缓存).
pub struct ExtractContext {
    pub root: PathBuf,
    pub registry: Arc<Registry>,
    pub textmap: Arc<TextMapIndex>,
    table_cache: Mutex<HashMap<String, Arc<Vec<Value>>>>,
    dir_cache: Mutex<HashMap<(String, i64), Option<Arc<Value>>>>,
}

impl ExtractContext {
    pub fn new(root: impl Into<PathBuf>, registry: Arc<Registry>, textmap: Arc<TextMapIndex>) -> ExtractContext {
        ExtractContext {
            root: root.into(),
            registry,
            textmap,
            table_cache: Mutex::new(HashMap::new()),
            dir_cache: Mutex::new(HashMap::new()),
        }
    }

    /// 基于当前数据根构建默认上下文(registry 用内嵌快照).
    pub fn open(root: impl Into<PathBuf>) -> ExtractContext {
        let root = root.into();
        let registry = build_registry();
        let textmap = Arc::new(TextMapIndex::open(&root));
        ExtractContext::new(root, registry, textmap)
    }

    // ---------------------------------------------------------------- 加载(缓存)
    /// 单文件表条目(缓存; 失败 → 空列表, 与 Python `_entries_raw` 一致).
    pub fn table_entries(&self, load_path: &str) -> Arc<Vec<Value>> {
        if let Some(cached) = self.table_cache.lock().unwrap().get(load_path) {
            return cached.clone();
        }
        let entries: Vec<Value> = match self.registry.loader_by_path(load_path) {
            Some(loader) => match jsonconfig::load_single_entries(&self.root, loader) {
                Ok(items) => items,
                Err(e) => {
                    warn!("load {load_path} failed: {e}");
                    Vec::new()
                }
            },
            None => {
                warn!("no loader for {load_path}");
                Vec::new()
            }
        };
        let arc = Arc::new(entries);
        self.table_cache.lock().unwrap().insert(load_path.to_string(), arc.clone());
        arc
    }

    /// 单文件表条目按 id_field 建索引(键序 = 条目序, 缺失/非整数键丢弃).
    pub fn table_entries_by(&self, load_path: &str, id_field: &str) -> IndexMap<i64, Value> {
        let mut by_id: IndexMap<i64, Value> = IndexMap::new();
        for e in self.table_entries(load_path).iter() {
            if let Some(id) = e.get(id_field).and_then(Value::as_i64) {
                by_id.insert(id, e.clone());
            }
        }
        by_id
    }

    /// 目录型单条(缓存; index=None/缺失/坏文件 → None).
    pub fn dir_entry(&self, load_path: &str, index: Option<i64>) -> Option<Arc<Value>> {
        let Some(index) = index else { return None };
        if let Some(cached) = self.dir_cache.lock().unwrap().get(&(load_path.to_string(), index)) {
            return cached.clone();
        }
        let result = match self.registry.loader_by_path(load_path) {
            Some(loader) => match jsonconfig::load_dir_entry(&self.root, loader, index) {
                Ok(entry) => Some(Arc::new(entry)),
                Err(_) => None,
            },
            None => None,
        };
        self.dir_cache
            .lock()
            .unwrap()
            .insert((load_path.to_string(), index), result.clone());
        result
    }

    /// 目录型全量(跳过坏文件).
    pub fn iter_dir(&self, load_path: &str) -> Vec<(i64, Value)> {
        match self.registry.loader_by_path(load_path) {
            Some(loader) => {
                jsonconfig::iter_dir_entries(&self.root, loader, true).unwrap_or_default()
            }
            None => Vec::new(),
        }
    }

    // ---------------------------------------------------------------- 类型化访问器
    pub fn entries_of(&self, load_path: &str) -> Arc<Vec<Value>> {
        self.table_entries(load_path)
    }

    pub fn entries_by_of(&self, load_path: &str, id_field: &str) -> IndexMap<i64, Value> {
        self.table_entries_by(load_path, id_field)
    }

    pub fn dir_entry_of(&self, load_path: &str, index: Option<i64>) -> Option<Arc<Value>> {
        self.dir_entry(load_path, index)
    }

    // ---------------------------------------------------------------- text/img
    /// FText → 纯文本(简体中文优先, 回退繁体/其他语言).
    pub fn ftext_text(&self, field: Option<&Value>) -> String {
        let Some(field) = field else { return String::new() };
        let hash = field.get("TextMapHashID").and_then(Value::as_u64).unwrap_or(0);
        if hash == 0 {
            return String::new();
        }
        let m = self.textmap.lookup_codes(hash);
        if let Some(sc) = m.get("SC") {
            return sc.clone();
        }
        if let Some(tc) = m.get("TC") {
            return tc.clone();
        }
        m.values().next().cloned().unwrap_or_default()
    }

    pub fn ftext_zh(&self, field: Option<&Value>) -> String {
        self.ftext_text(field)
    }
}

/// SoftObjectPath dict → Path 字符串(或 '').
pub fn soft_path(field: Option<&Value>) -> String {
    field
        .and_then(Value::as_object)
        .and_then(|o| o.get("Path"))
        .and_then(Value::as_str)
        .unwrap_or("")
        .to_string()
}

/// 取 InitAttributes 中某属性的 RealValue(保持源字符串).
pub fn attr_value(attrs: &Map<String, Value>, name: &str) -> Option<String> {
    let v = attrs.get(name)?;
    let rv = v.get("RealValue")?;
    Some(rv.py_str())
}

/// Python `float(x or 0.0)` 语义: 数字或数字字符串 → f64.
fn as_f64(v: Option<&Value>) -> f64 {
    match v {
        Some(Value::Number(n)) => n.as_f64().unwrap_or(0.0),
        Some(Value::String(s)) => s.parse::<f64>().unwrap_or(0.0),
        _ => 0.0,
    }
}

/// Python `round(x, 2)`(银行家舍入, half-to-even).
pub fn py_round(x: f64, digits: i32) -> f64 {
    let factor = 10f64.powi(digits);
    let scaled = x * factor;
    let floor = scaled.floor();
    let diff = scaled - floor;
    let rounded = if diff > 0.5 {
        floor + 1.0
    } else if diff < 0.5 {
        floor
    } else if floor % 2.0 == 0.0 {
        floor
    } else {
        floor + 1.0
    };
    rounded / factor
}

/// 枚举 → 中文(按实际数据值).
fn zh(value: Option<&Value>, mapping: &HashMap<&str, &str>) -> String {
    match value.and_then(Value::as_str) {
        None => String::new(),
        Some(v) => mapping.get(v).map(|s| s.to_string()).unwrap_or_else(|| v.to_string()),
    }
}

fn zh_map(pairs: &[(&str, &str)]) -> HashMap<&'static str, &'static str> {
    pairs.iter().map(|(k, v)| (*k, *v)).collect()
}

