// 元理
// =====================================================================
pub fn extract_trait(ctx: &ExtractContext) -> Vec<Row> {
    let trait_by_id = ctx.entries_by_of("Table/Trait", "ID");
    let mut rows = Vec::new();
    for (tid, it) in trait_by_id {
        let file = ctx.dir_entry("ChessGame/ChsTrait", Some(tid)).cloned().unwrap_or(Value::Null);
        let ctd = file.get("ChessTraitConditionDesc").and_then(Value::as_object).cloned().unwrap_or_default();
        let mut layers: Vec<Row> = Vec::new();
        let mut keys: Vec<&String> = ctd.keys().collect();
        keys.sort();
        for rank in keys {
            let e = ctd.get(rank).cloned().unwrap_or(Value::Null);
            let mut layer = Map::new();
            layer.insert("rank".into(), json!(rank.parse::<i64>().unwrap_or(0)));
            layer.insert("desc".into(), json!(ctx.ftext_text(e.get("Desc"))));
            let formulas = e.get("SkillFormulas").cloned().unwrap_or(Value::Null);
            layer.insert("formulas".into(), if formulas.is_null() { json!({}) } else { formulas });
            layers.push(layer);
        }
        let desc = layers.first().and_then(|l| l.get("desc")).cloned().unwrap_or(Value::Null);
        let mut row = Map::new();
        row.insert("id".into(), json!(tid));
        row.insert("name".into(), json!(ctx.ftext_text(it.get("TraitName"))));
        let icon = first_nonempty(&[&soft_path(it.get("Icon128")), &soft_path(it.get("IconPath"))]);
        row.insert("icon".into(), json!(icon));
        row.insert("layers".into(), json!(layers));
        row.insert("desc".into(), desc);
        rows.push(row);
    }
    rows
}

