pub fn trainer_partner_skill_ids(ctx: &ExtractContext, sprite_ids: &[Option<i64>]) -> Vec<i64> {
    let mut out = Vec::new();
    for sid in sprite_ids {
        let Some(sid) = sid else { continue };
        let Some(ent) = ctx.dir_entry("Entity/ChsChessPiece", Some(*sid)) else { continue };
        let comps = ent.get("Base").and_then(|b| b.get("InitComponents")).and_then(Value::as_array);
        let Some(comps) = comps else { continue };
        for (_t, comp) in components::iter_components(comps) {
            if comp.g_str("$type") != Some("/pd.AbilityEntityComponentConfig") {
                continue;
            }
            let cond_skills = comp.get("ConditionSkills").and_then(Value::as_array);
            if let Some(cds) = cond_skills {
                for cd in cds {
                    let cond = cd.get("Condition").cloned().unwrap_or(Value::Null);
                    if cond.g_str("$type").unwrap_or("").contains("ChsHasExclusiveTrainerCondition") {
                        if let Some(skill_id) = cd.get("SkillID").and_then(Value::as_i64) {
                            out.push(skill_id);
                        }
                    }
                }
            }
        }
    }
    out
}

/// 心象技能: Entity/ChsTrainer 实体 → UltSkill, 回退 TrainerChs.UltSkillID.
pub fn trainer_ult_skill(ctx: &ExtractContext, trainer: &Value) -> Option<i64> {
    let eid = i_or_fallback(trainer.get("EntityConfigID"), trainer.get("ID"));
    let ult_skill_id = trainer.get("UltSkillID").and_then(Value::as_i64);
    let Some(eid) = eid else { return ult_skill_id };
    if let Some(ent) = ctx.dir_entry("Entity/ChsTrainer", Some(eid)) {
        let comps = ent.get("Base").and_then(|b| b.get("InitComponents")).and_then(Value::as_array);
        if let Some(comps) = comps {
            for (_t, comp) in components::iter_components(comps) {
                if comp.g_str("$type") == Some("/pd.ChsTrainerAbilityEntityComponentConfig") {
                    return i_or_fallback(comp.get("UltSkill"), trainer.get("UltSkillID"));
                }
            }
        }
    }
    ult_skill_id
}

/// 心象技能对应心识: Entity 中 ConditionSkills 的心识条件 BreakID.
pub fn trainer_ult_break_ids(ctx: &ExtractContext, trainer: &Value) -> Vec<i64> {
    let eid = i_or_fallback(trainer.get("EntityConfigID"), trainer.get("ID"));
    let Some(eid) = eid else { return Vec::new() };
    let Some(ent) = ctx.dir_entry("Entity/ChsTrainer", Some(eid)) else { return Vec::new() };
    let mut out = Vec::new();
    let comps = ent.get("Base").and_then(|b| b.get("InitComponents")).and_then(Value::as_array);
    if let Some(comps) = comps {
        for (_t, comp) in components::iter_components(comps) {
            if comp.g_str("$type") != Some("/pd.ChsTrainerAbilityEntityComponentConfig") {
                continue;
            }
            if let Some(cds) = comp.get("ConditionSkills").and_then(Value::as_array) {
                for cd in cds {
                    let cond = cd.get("Condition").cloned().unwrap_or(Value::Null);
                    if cond.g_str("$type").unwrap_or("").contains("TrainerSkillTrainerBreakCondition") {
                        if let Some(bid) = cd.get("BreakID").and_then(Value::as_i64) {
                            out.push(bid);
                        }
                    }
                }
            }
        }
    }
    out
}

/// 1-30 级数值: value(L) = base * (1 + 累计成长加成(L)); 展示保留 2 位小数.
pub fn trainer_level_values(ctx: &ExtractContext, base: f64, addend_key: &str) -> Vec<Row> {
    let growth = ctx.entries_by_of("Table/TrainerLevelGrowth", "Level");
    let mut out = Vec::new();
    for lv in 1..=30 {
        let g = growth.get(&lv).cloned().unwrap_or(Value::Null);
        let a = g.get("AttributeAddendRatio").and_then(Value::as_object);
        let addend = a
            .and_then(|m| m.get(addend_key))
            .and_then(|v| as_f64(Some(v.get("RealValue").unwrap_or(&Value::Null))).into())
            .unwrap_or(0.0);
        let value = base * (1.0 + addend);
        let mut row = Map::new();
        row.insert("level".into(), json!(lv));
        row.insert("value".into(), json!(py_round(value, 2)));
        out.push(row);
    }
    out
}

pub fn extract_trainer(ctx: &ExtractContext) -> Vec<Row> {
    let common_by_id = ctx.entries_by_of("Table/TrainerCommon", "ID");
    let attr_by_id = ctx.entries_by_of("Table/TrainerAttributeTable", "ID");
    let mut rows = Vec::new();
    for it in ctx.entries_of("Table/TrainerChs").iter() {
        let tid = it.get("ID").and_then(Value::as_i64).unwrap_or(0);
        let common = common_by_id.get(&tid).cloned().unwrap_or(Value::Null);
        let attrs = attr_by_id
            .get(&tid)
            .and_then(|a| a.get("InitAttributes"))
            .and_then(Value::as_object)
            .cloned()
            .unwrap_or_default();
        let partner: Vec<Option<i64>> = it
            .get("ExclusiveSprite")
            .and_then(Value::as_array)
            .map(|a| a.iter().map(|x| x.get("SpriteConfigID").and_then(Value::as_i64)).collect())
            .unwrap_or_default();

        let trait_id = it.get("CombinationalTraitID").and_then(Value::as_i64);
        let mut trait_skill_ids: Vec<i64> = Vec::new();
        if let Some(trait_id) = trait_id {
            let trait_file = ctx
                .dir_entry("ChessGame/ChsTrait", Some(trait_id))
                .cloned()
                .unwrap_or(Value::Null);
            let tts = trait_file
                .get("TrainerTraitSkills")
                .and_then(Value::as_object)
                .and_then(|m| m.get(&tid.to_string()))
                .cloned()
                .unwrap_or(Value::Null);
            if let Some(datas) = tts.get("TraitSkillDatas").and_then(Value::as_array) {
                for sd in datas {
                    if let Some(sid) = sd.get("SkillID").and_then(Value::as_i64) {
                        trait_skill_ids.push(sid);
                    }
                }
            }
        }

        let base_passive =
            as_f64(attr_value(&attrs, "EntityAttribute_TrainerPassivePowerBase").map(|s| Value::String(s)).as_ref().or(None).and_then(|_| None)).max(0.0);
        let base_active = as_f64(attr_value(&attrs, "EntityAttribute_TrainerActivePowerBase").and_then(|s| s.parse::<f64>().ok()));

        let mut row = Map::new();
        row.insert("id".into(), json!(tid));
        row.insert("name".into(), json!(ctx.ftext_text(it.get("Name"))));
        let portrait = first_nonempty(&[&soft_path(it.get("Poster")), &soft_path(common.get("Poster"))]);
        row.insert("portrait".into(), json!(portrait));
        let icon = first_nonempty(&[&soft_path(it.get("IconPath")), &soft_path(it.get("AvatarHead64Path"))]);
        row.insert("icon".into(), json!(icon));
        row.insert("rarity".into(), it.get("Rarity").cloned().unwrap_or(Value::Null));
        row.insert("traitId".into(), json!(trait_id));
        row.insert("partnerSpriteIds".into(), json!(partner.iter().flatten().collect::<Vec<_>>()));
        row.insert(
            "passivePower".into(),
            json!(trainer_level_values(ctx, base_passive, "EntityAttribute_TrainerPassivePowerGrowthAddend")),
        );
        row.insert(
            "activePower".into(),
            json!(trainer_level_values(ctx, base_active, "EntityAttribute_TrainerActivePowerGrowthAddend")),
        );
        row.insert("maxMp".into(), json!(attr_value(&attrs, "EntityAttribute_MaxMPBase")));
        row.insert("mpRegen".into(), json!(attr_value(&attrs, "EntityAttribute_MPRegenBase")));
        row.insert("initialMp".into(), json!(attr_value(&attrs, "EntityAttribute_InitialMPBase")));
        row.insert("traitSkillIds".into(), json!(trait_skill_ids));
        row.insert("partnerSkillIds".into(), json!(trainer_partner_skill_ids(ctx, &partner)));
        row.insert("ultSkillId".into(), json!(trainer_ult_skill(ctx, it)));
        rows.push(row);
    }
    rows
}
