// =====================================================================
// 角色技能
// =====================================================================
fn skill_row_template(skill_id: i64) -> Row {
    let mut row = Map::new();
    row.insert("id".into(), json!(skill_id));
    row.insert("trainerIds".into(), json!(Vec::<i64>::new()));
    row.insert("skillType".into(), json!(Vec::<String>::new()));
    row.insert("breakIds".into(), json!(Vec::<i64>::new()));
    row.insert("effectTags".into(), json!(Vec::<String>::new()));
