fn push_unique<T: PartialEq + Clone>(list: &mut Vec<T>, value: T) {
    if !list.contains(&value) {
        list.push(value);
    }
}

pub fn extract_trainer_skill(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows: IndexMap<i64, Row> = IndexMap::new();
    for tr in ctx.entries_of("Table/TrainerChs").iter() {
        let tid = tr.get("ID").and_then(Value::as_i64).unwrap_or(0);
        // 心象技能
        let ult = trainer_ult_skill(ctx, tr);
        if let Some(ult) = ult {
            let row = rows.entry(ult).or_insert_with(|| skill_row_template(ult));
            push_unique(&mut vec_get_mut(row, "trainerIds"), tid);
            push_unique(&mut vec_get_mut(row, "skillType"), "心象技能".to_string());
            for b in trainer_ult_break_ids(ctx, tr) {
                push_unique(&mut vec_get_mut(row, "breakIds"), b);
            }
        }
        // 元理技能(基础元理技能 = DisplayType MainSkill)
        let trait_id = tr.get("CombinationalTraitID").and_then(Value::as_i64);
        if let Some(trait_id) = trait_id {
            let trait_file = ctx
                .dir_entry("ChessGame/ChsTrait", Some(trait_id))
                .cloned()
                .unwrap_or(Value::Null);
            let tts = trait_file
                .get("TrainerTraitSkills")
                .and_then(Value::as_object)
                .and_then(|m| m.get(&tid.to_string()))
                .cloned()
                .unwrap_or(Value::Null);
            if let Some(datas) = tts.get("TraitSkillDatas").and_then(Value::as_array) {
                for sd in datas {
                    let Some(sid) = sd.get("SkillID").and_then(Value::as_i64) else { continue };
                    let row = rows.entry(sid).or_insert_with(|| skill_row_template(sid));
                    push_unique(&mut vec_get_mut(row, "trainerIds"), tid);
                    let label = if sd.g_str("DisplayType") == Some("TrainerTraitSkillDisplayType_MainSkill")
                    {
                        "元理技能(基础)"
                    } else {
                        "元理技能"
                    };
