pub fn extract_trainer_break(ctx: &ExtractContext) -> Vec<Row> {
    let break_by_id = ctx.entries_by_of("Table/TrainerBreak", "ID");
    let effect_by_id = ctx.entries_by_of("Table/TrainerBreakEffect", "TrainerID");
    let mut rows: Vec<Row> = Vec::new();
    for (tid, tr) in break_by_id {
        let mut effects: HashMap<(Option<i64>, Option<i64>), Value> = HashMap::new();
        if let Some(list) = effect_by_id.get(&tid).and_then(|e| e.get("BreakEffectList")).and_then(Value::as_array) {
            for be in list {
                effects.insert(
                    (be.get("BreakID").and_then(Value::as_i64), be.get("BreakLevel").and_then(Value::as_i64)),
                    be.clone(),
                );
            }
        }
        if let Some(breaks) = tr.get("BreakList").and_then(Value::as_array) {
            for b in breaks {
                let bid = b.get("BreakId").and_then(Value::as_i64);
                let level = b.get("Level").and_then(Value::as_i64);
                let be = effects
                    .get(&(bid, level))
                    .or_else(|| effects.get(&(bid, Some(1))))
                    .cloned()
                    .unwrap_or(Value::Null);
                let mut skill_id: Option<i64> = None;
                let mut enhance: Vec<Row> = Vec::new();
                if let Some(effect_list) = be.get("BreakEffectList").and_then(Value::as_array) {
                    for ef in effect_list {
                        if let Some(sid) = ef.get("SkillID").and_then(Value::as_i64) {
                            skill_id = Some(sid);
                        }
                        let attrs = ef
                            .get("TrainerAttributeEnhance")
                            .or_else(|| ef.get("SpriteAttributeEnhance"))
                            .and_then(Value::as_object);
                        if let Some(attrs) = attrs {
                            for (k, v) in attrs {
                                let mut item = Map::new();
                                item.insert("attribute".into(), json!(k));
                                let rv = v.get("RealValue").map(|x| x.py_str()).unwrap_or_default();
                                item.insert("value".into(), json!(rv));
                                enhance.push(item);
                            }
                        }
                    }
                }
                let mut row = Map::new();
                row.insert("id".into(), json!(bid));
                row.insert("trainerId".into(), json!(tid));
                row.insert("skillId".into(), json!(skill_id));
                row.insert("level".into(), json!(level));
                row.insert("effect".into(), json!(enhance));
                rows.push(row);
            }
        }
    }
    rows.sort_by_key(|r| {
        (
            r.get("trainerId").and_then(Value::as_i64).unwrap_or(0),
            r.get("id").and_then(Value::as_i64).unwrap_or(0),
        )
    });
    rows
}

