pub fn extract_trainer_constellation(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows: Vec<Row> = Vec::new();
    for tr in ctx.entries_of("Table/TrainerChs").iter() {
        let tid = tr.get("ID").and_then(Value::as_i64).unwrap_or(0);
        let ult = trainer_ult_skill(ctx, tr);
        let ranks = ult.map(|u| skill_rank_descs(ctx, u)).unwrap_or_default();
        let diff_by_rank: HashMap<i64, String> = ranks
            .iter()
            .map(|r| {
                (
                    r.get("rank").and_then(Value::as_i64).unwrap_or(0),
                    r.get("diffDesc").and_then(Value::as_str).unwrap_or("").to_string(),
                )
            })
            .collect();
        if let Some(rank_up_descs) = tr.get("RankUpDesc").and_then(Value::as_array) {
            for r in rank_up_descs {
                let rank = r.get("Rank").and_then(Value::as_i64);
