        if let Some(rank_up_descs) = tr.get("RankUpDesc").and_then(Value::as_array) {
            for r in rank_up_descs {
                let rank = r.get("Rank").and_then(Value::as_i64);
                let mut row = Map::new();
                row.insert("id".into(), json!(format!("{tid}-{}", rank.unwrap_or(0))));
                row.insert("trainerId".into(), json!(tid));
                row.insert("rank".into(), json!(rank));
                row.insert("name".into(), json!(ctx.ftext_text(r.get("Title"))));
                let effect = diff_by_rank.get(&rank.unwrap_or(0)).cloned().unwrap_or_default();
                row.insert("effectDesc".into(), json!(effect));
                rows.push(row);
            }
        }
    }
    rows.sort_by_key(|r| {
        (
            r.get("trainerId").and_then(Value::as_i64).unwrap_or(0),
            r.get("rank").and_then(Value::as_i64).unwrap_or(0),
        )
    });
    rows
}

