// 精灵
// =====================================================================
pub fn sprite_attr_values(ctx: &ExtractContext, sprite_id: Option<i64>) -> IndexMap<String, Vec<Row>> {
    let mut out: IndexMap<String, Vec<Row>> = IndexMap::new();
    let Some(sprite_id) = sprite_id else { return out };
    let init = ctx.entries_by_of("Table/ChessPieceInitAttribute", "ID").get(&sprite_id).cloned().unwrap_or(Value::Null);
    let init_attrs = init.get("InitAttributes").and_then(Value::as_object).cloned().unwrap_or_default();
    let level_growth = ctx.entries_by_of("Table/ChessPieceLevelGrowth", "Level");
    let break_growth = ctx.entries_by_of("Table/ChessPieceBreakthroughGrowth", "BreakthroughLevel");
    let sprite_level = ctx.entries_by_of("Table/SpriteLevel", "Level");

    let growth_keys: [(&str, &str); 5] = [
        ("EntityAttribute_MaxHPBase", "EntityAttribute_MaxHPGrowthAddend"),
        ("EntityAttribute_AttackDamageBase", "EntityAttribute_AttackDamageGrowthAddend"),
        ("EntityAttribute_AbilityPowerBase", "EntityAttribute_AbilityPowerGrowthAddend"),
        ("EntityAttribute_ArmorBase", "EntityAttribute_ArmorGrowthAddend"),
        ("EntityAttribute_MagicResistanceBase", "EntityAttribute_MagicResistanceGrowthAddend"),
    ];
    for (base_key, addend_key) in growth_keys {
        let base_v = init_attrs.get(base_key).cloned().unwrap_or(Value::Null);
        let base = as_f64(base_v.get("RealValue"));
        let mut per_level: Vec<Row> = Vec::new();
        for lv in 1..=60 {
            let addend = level_growth
                .get(&lv)
                .and_then(|g| g.get("AttributeAddendRatio"))
                .and_then(Value::as_object)
                .and_then(|m| m.get(addend_key))
                .map(|v| as_f64(v.get("RealValue")))
                .unwrap_or(0.0);
            let break_lv = sprite_level
                .get(&lv)
                .and_then(|s| s.get("LevelBreak"))
                .and_then(Value::as_i64)
                .unwrap_or(0);
            let break_addend = break_growth
                .get(&break_lv)
                .and_then(|g| g.get("AttributeAddendRatio"))
                .and_then(Value::as_object)
                .and_then(|m| m.get(addend_key))
                .map(|v| as_f64(v.get("RealValue")))
                .unwrap_or(0.0);
            let before = py_round(base * (1.0 + addend), 2);
            let after = py_round(base * (1.0 + addend + break_addend), 2);
            let mut row = Map::new();
            row.insert("level".into(), json!(lv));
            row.insert("break".into(), json!(break_lv));
            row.insert("before".into(), json!(before));
            row.insert("after".into(), json!(after));
            per_level.push(row);
        }
        out.insert(base_key.to_string(), per_level);
    }
    // 无成长属性(常数)
    for key in [
        "EntityAttribute_AttackRateBase",
        "EntityAttribute_MaxMPBase",
        "EntityAttribute_InitialMPBase",
        "EntityAttribute_MaxMPRatio",
    ] {
        let v = init_attrs.get(key).cloned().unwrap_or(Value::Null);
        if v.get("RealValue").is_some() {
            let value = py_round(as_f64(v.get("RealValue")), 2);
            let mut row = Map::new();
            row.insert("level".into(), json!(1));
            row.insert("break".into(), json!(0));
            row.insert("before".into(), json!(value));
            row.insert("after".into(), json!(value));
            out.insert(key.to_string(), vec![row]);
        }
    }
    out
}

pub fn extract_sprite(ctx: &ExtractContext) -> Vec<Row> {
    let common_by_id = ctx.entries_by_of("Table/SpriteCommon", "SpriteID");
    let prof_by_id = ctx.entries_by_of("Table/SpriteProfession", "ID");
    let habitat_by_id = ctx.entries_by_of("Table/Habitat", "ID");
    let personality_tpl = ctx.entries_by_of("Table/SpritePersonality", "Id");
    // 栖息地反查: 精灵ID → [栖息地ID]
    let mut habitat_of_sprite: HashMap<i64, Vec<i64>> = HashMap::new();
    for (hid, h) in &habitat_by_id {
        if let Some(list) = h.get("SpriteIDList").and_then(Value::as_array) {
            for sid in list.iter().filter_map(Value::as_i64) {
                habitat_of_sprite.entry(sid).or_default().push(*hid);
            }
        }
    }
    let mut rows = Vec::new();
    for it in ctx.entries_of("Table/SpriteChs").iter() {
        let sid = it.get("ChsID").and_then(Value::as_i64).unwrap_or(0);
        let common = common_by_id.get(&sid).cloned().unwrap_or(Value::Null);
        let traits = it.get("Traits").and_then(Value::as_array).cloned().unwrap_or_default();
        // 可获得的性格
        let tpl = common
            .get("PersonalityTemplateId")
            .and_then(Value::as_i64)
            .and_then(|pid| personality_tpl.get(&pid))
            .cloned()
            .unwrap_or(Value::Null);
        let mut weight_ids: Vec<i64> = Vec::new();
        if let Some(qualities) = tpl.get("QualityList").and_then(Value::as_array) {
            for q in qualities {
                if let Some(map) = q.get("PersonalityWeightMap").and_then(Value::as_object) {
                    for (pid, w) in map {
                        if !w.is_null() && w.as_bool() != Some(false) && w.as_i64() != Some(0) {
                            if let Ok(pid) = pid.parse::<i64>() {
                                weight_ids.push(pid);
                            }
                        }
                    }
                }
            }
        }
        weight_ids.sort_unstable();
        weight_ids.dedup();
        let personality_ids = weight_ids;
        // 异色
        let mut shiny: Vec<Row> = Vec::new();
        let mut shiny_ids: Vec<i64> = Vec::new();
        if let Some(rare) = common.get("RareShinySkinId").and_then(Value::as_i64) {
            shiny_ids.push(rare);
        }
        if let Some(normal) = common.get("NormalShinySkinWeightList").and_then(Value::as_object) {
            for k in normal.keys() {
                if let Ok(k) = k.parse::<i64>() {
                    shiny_ids.push(k);
                }
            }
        }
        for sid_ in shiny_ids {
            let skin = ctx.dir_entry("Skin", Some(sid_)).cloned().unwrap_or(Value::Null);
            let mut s = Map::new();
            s.insert("id".into(), json!(sid_));
            s.insert("name".into(), json!(ctx.ftext_text(skin.get("Name"))));
            let head = first_nonempty(&[&soft_path(skin.get("SpriteHead256")), &soft_path(skin.get("SpriteHead64"))]);
            s.insert("head".into(), json!(head));
            s.insert("image1024".into(), json!(soft_path(skin.get("SpriteImage1024"))));
            shiny.push(s);
        }
        let attrs = sprite_attr_values(ctx, Some(sid));
        let energy = attrs
            .get("EntityAttribute_MaxMPBase")
            .and_then(|rows| rows.first())
            .and_then(|r| r.get("after"))
            .cloned();
        let trait_id = traits.first().and_then(|t| t.get("TraitId")).cloned();
        let mut row = Map::new();
        row.insert("id".into(), json!(sid));
        row.insert("name".into(), json!(ctx.ftext_text(it.get("ChsSpriteName"))));
        row.insert("artwork".into(), json!(soft_path(common.get("SpriteImage1024"))));
        let head = first_nonempty(&[&soft_path(it.get("SpriteHead256")), &soft_path(it.get("SpriteHead64"))]);
        row.insert("head".into(), json!(head));
        row.insert("rarity".into(), it.get("Rarity").cloned().unwrap_or(Value::Null));
        row.insert("traitId".into(), trait_id.unwrap_or(Value::Null));
        row.insert("energy".into(), energy.unwrap_or(Value::Null));
        row.insert("height".into(), common.get("Height").cloned().unwrap_or(Value::Null));
        let intro = first_nonempty(&[&ctx.ftext_text(common.get("Description")), &ctx.ftext_text(common.get("SubDescription"))]);
        row.insert("intro".into(), json!(intro));
        row.insert("position".into(), json!(zh(it.get("PositionTag"), &position_zh())));
        row.insert("damageType".into(), json!(zh(it.get("SpriteDamageType"), &damage_zh())));
        row.insert("battleType".into(), json!(zh(it.get("BattleTypeTag"), &battle_zh())));
        let profession = it
            .get("ProfessionID")
            .and_then(Value::as_i64)
            .and_then(|pid| prof_by_id.get(&pid))
            .and_then(|p| Some(ctx.ftext_text(p.get("ProfessionName"))))
            .unwrap_or_default();
        row.insert("profession".into(), json!(profession));
        row.insert("obtain".into(), json!(ctx.ftext_text(common.get("FromDesc"))));
        row.insert("attributes".into(), json!(attrs));
        let story = first_nonempty(&[&ctx.ftext_text(common.get("Story")), &ctx.ftext_text(common.get("Description"))]);
        row.insert("story".into(), json!(story));
        row.insert("shiny".into(), json!(shiny));
        row.insert("habitatIds".into(), json!(habitat_of_sprite.get(&sid).cloned().unwrap_or_default()));
        row.insert("personalityIds".into(), json!(personality_ids));
        rows.push(row);
    }
    rows
}
