// =====================================================================
// 精灵技能
// =====================================================================
fn sprite_skill_row_template(skill_id: i64) -> Row {
    let mut row = Map::new();
    row.insert("id".into(), json!(skill_id));
    row.insert("spriteIds".into(), json!(Vec::<i64>::new()));
    row.insert("skillType".into(), json!(Vec::<String>::new()));
    row.insert("name".into(), json!(""));
    row.insert("icon".into(), json!(""));
    row.insert("tags".into(), json!(Vec::<String>::new()));
    row.insert("desc".into(), json!(Vec::<Row>::new()));
    row
}

pub fn extract_sprite_skill(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows: IndexMap<i64, Row> = IndexMap::new();
    for it in ctx.entries_of("Table/SpriteChs").iter() {
        let sid = it.get("ChsID").and_then(Value::as_i64).unwrap_or(0);
        let Some(ent) = ctx.dir_entry("Entity/ChsChessPiece", Some(sid)) else { continue };
        let Some(comps) = ent.get("Base").and_then(|b| b.get("InitComponents")).and_then(Value::as_array) else {
            continue;
        };
        for (_t, comp) in components::iter_components(comps) {
            if comp.g_str("$type") != Some("/pd.AbilityEntityComponentConfig") {
                continue;
            }
            let mut slots: Vec<(String, Option<i64>)> = Vec::new();
            slots.push(("普通攻击".into(), comp.get("NormalAttackSkill").and_then(Value::as_i64)));
            slots.push(("大招".into(), comp.get("UltimateSkill").and_then(Value::as_i64)));
            if let Some(list) = comp.get("SkillList").and_then(Value::as_array) {
                for (i, s) in list.iter().enumerate() {
                    slots.push((format!("技能{}", i + 1), s.as_i64()));
                }
            }
            if let Some(cds) = comp.get("ConditionSkills").and_then(Value::as_array) {
                for cd in cds {
                    let cond = cd.get("Condition").cloned().unwrap_or(Value::Null);
                    let type_name = cond.g_str("$type").unwrap_or("");
                    if type_name.contains("ChsHasExclusiveTrainerCondition") {
                        continue; // 同行技能归角色
                    }
                    let label = format!("条件技能({})", type_name.rsplit('.').next().unwrap_or(""));
                    slots.push((label, cd.get("SkillID").and_then(Value::as_i64)));
                }
            }
            for (_slot, skill_id) in slots {
                let Some(skill_id) = skill_id else { continue };
                let row = rows.entry(skill_id).or_insert_with(|| sprite_skill_row_template(skill_id));
                push_unique_in(row, "spriteIds", json!(sid));
                push_unique_in(row, "skillType", json!("战斗技能"));
            }
        }
    }
    let mut out: Vec<Row> = Vec::new();
    for (skill_id, mut row) in rows {
        let (_, msg) = skill_file(ctx, skill_id);
        let base = msg.get("Base").cloned().unwrap_or(Value::Null);
        let desc = msg
            .get("SkillDescConfig")
            .or_else(|| base.get("SkillDescConfig"))
            .cloned()
            .unwrap_or(Value::Null);
        row.insert("name".into(), json!(ctx.ftext_text(desc.get("SkillName"))));
        row.insert("icon".into(), json!(soft_path(desc.get("SkillIcon"))));
        row.insert("tags".into(), json!(skill_tags(ctx, skill_id)));
        row.insert("desc".into(), json!(skill_rank_descs(ctx, skill_id)));
        out.push(row);
    }
    out.sort_by_key(|r| r.get("id").and_then(Value::as_i64).unwrap_or(0));
    out
}

// =====================================================================
// 精灵命座
// =====================================================================
pub fn extract_sprite_constellation(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows: Vec<Row> = Vec::new();
    for it in ctx.entries_of("Table/SpriteChs").iter() {
        let sid = it.get("ChsID").and_then(Value::as_i64).unwrap_or(0);
        let Some(ent) = ctx.dir_entry("Entity/ChsChessPiece", Some(sid)) else { continue };
        let Some(comps) = ent.get("Base").and_then(|b| b.get("InitComponents")).and_then(Value::as_array) else {
            continue;
        };
        let mut skill_ids: Vec<i64> = Vec::new();
        for (_t, comp) in components::iter_components(comps) {
            if comp.g_str("$type") != Some("/pd.AbilityEntityComponentConfig") {
                continue;
            }
            for s in [comp.get("NormalAttackSkill"), comp.get("UltimateSkill")] {
                if let Some(s) = s.and_then(Value::as_i64) {
                    skill_ids.push(s);
                }
            }
            if let Some(list) = comp.get("SkillList").and_then(Value::as_array) {
                for s in list.iter().filter_map(Value::as_i64) {
                    skill_ids.push(s);
                }
            }
        }
        skill_ids.sort_unstable();
        skill_ids.dedup();
        for skill_id in skill_ids {
            let ranks = skill_rank_descs(ctx, skill_id);
            for r in ranks {
                let rank = r.get("rank").and_then(Value::as_i64).unwrap_or(0);
                if rank <= 0 {
                    continue;
                }
                let mut row = Map::new();
                row.insert("id".into(), json!(format!("{sid}-{rank}")));
                row.insert("spriteId".into(), json!(sid));
                row.insert("rank".into(), json!(rank));
                row.insert("name".into(), json!(format!("Rank {rank}")));
                let effect = r.get("diffDesc").and_then(Value::as_str).unwrap_or("").to_string();
                row.insert("effectDesc".into(), json!(effect));
                rows.push(row);
            }
        }
    }
    rows.sort_by_key(|r| {
        (
            r.get("spriteId").and_then(Value::as_i64).unwrap_or(0),
            r.get("rank").and_then(Value::as_i64).unwrap_or(0),
        )
    });
    rows
}

// =====================================================================
// 精灵性格
// =====================================================================
pub fn extract_personality(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows = Vec::new();
    for it in ctx.entries_of("Table/SpritePersonalityEffect").iter() {
        let pid = it.get("ID").and_then(Value::as_i64).unwrap_or(0);
        let person = ctx.dir_entry("ChessGame/ChessPersonality", Some(pid)).cloned().unwrap_or(Value::Null);
        let rank_desc = person.get("ChessPersonalityRankDesc").and_then(Value::as_object).cloned().unwrap_or_default();
        let mut keys: Vec<&String> = rank_desc.keys().collect();
        keys.sort_by_key(|s| num_sort_key(s));
        let mut ranks: Vec<Row> = Vec::new();
        for q in keys {
            let e = rank_desc.get(q).cloned().unwrap_or(Value::Null);
            let mut item = Map::new();
            let quality: Value = match q.parse::<i64>() {
                Ok(n) => json!(n),
                Err(_) => json!(q),
            };
            item.insert("quality".into(), quality);
            item.insert("name".into(), json!(ctx.ftext_text(e.get("Name"))));
            item.insert("desc".into(), json!(ctx.ftext_text(e.get("Desc"))));
            let formulas = e.get("SkillFormulas").cloned().unwrap_or(Value::Null);
            item.insert("formulas".into(), if formulas.is_null() { json!({}) } else { formulas });
            ranks.push(item);
        }
        // 回退: RankList[quality].AttributeModifyActions
        let mut fallback: Vec<Row> = Vec::new();
        if let Some(rank_list) = it.get("RankList").and_then(Value::as_object) {
            for (q, r) in rank_list {
                let mut actions: Vec<Row> = Vec::new();
                if let Some(attr_map) = r.get("AttributeModifyActions").and_then(Value::as_object) {
                    for (k, v) in attr_map {
                        let mut a = Map::new();
                        a.insert("attribute".into(), json!(k));
                        let rv = v.get("RealValue").map(|x| x.py_str()).unwrap_or_default();
                        a.insert("value".into(), json!(rv));
                        actions.push(a);
                    }
                }
                if !actions.is_empty() {
                    let mut f = Map::new();
                    f.insert("quality".into(), json!(q));
                    f.insert("actions".into(), json!(actions));
                    fallback.push(f);
                }
            }
        }
        let name = ctx.ftext_text(it.get("Name"));
        let name = if name.is_empty() {
            it.get("Base")
                .and_then(|b| b.get("EditorName"))
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string()
        } else {
            name
        };
        let mut row = Map::new();
        row.insert("id".into(), json!(pid));
        row.insert("name".into(), json!(name));
        row.insert("ranks".into(), json!(ranks));
        row.insert("effect".into(), json!(fallback));
        rows.push(row);
    }
    rows
}

