pub fn extract_sprite_skill(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows: IndexMap<i64, Row> = IndexMap::new();
    for it in ctx.entries_of("Table/SpriteChs").iter() {
        let sid = it.get("ChsID").and_then(Value::as_i64).unwrap_or(0);
        let Some(ent) = ctx.dir_entry("Entity/ChsChessPiece", Some(sid)) else { continue };
        let Some(comps) = ent.get("Base").and_then(|b| b.get("InitComponents")).and_then(Value::as_array) else {
            continue;
        };
        for (_t, comp) in components::iter_components(comps) {
            if comp.g_str("$type") != Some("/pd.AbilityEntityComponentConfig") {
                continue;
            }
            let mut slots: Vec<(String, Option<i64>)> = Vec::new();
            slots.push(("普通攻击".into(), comp.get("NormalAttackSkill").and_then(Value::as_i64)));
            slots.push(("大招".into(), comp.get("UltimateSkill").and_then(Value::as_i64)));
            if let Some(list) = comp.get("SkillList").and_then(Value::as_array) {
                for (i, s) in list.iter().enumerate() {
                    slots.push((format!("技能{}", i + 1), s.as_i64()));
                }
            }
            if let Some(cds) = comp.get("ConditionSkills").and_then(Value::as_array) {
                for cd in cds {
                    let cond = cd.get("Condition").cloned().unwrap_or(Value::Null);
                    let type_name = cond.g_str("$type").unwrap_or("");
                    if type_name.contains("ChsHasExclusiveTrainerCondition") {
                        continue; // 同行技能归角色
                    }
                    let label = format!("条件技能({})", type_name.rsplit('.').next().unwrap_or(""));
                    slots.push((label, cd.get("SkillID").and_then(Value::as_i64)));
                }
            }
            for (_slot, skill_id) in slots {
                let Some(skill_id) = skill_id else { continue };
                let row = rows.entry(skill_id).or_insert_with(|| sprite_skill_row_template(skill_id));
                push_unique_in(row, "spriteIds", json!(sid));
                push_unique_in(row, "skillType", json!("战斗技能"));
            }
        }
    }
    let mut out: Vec<Row> = Vec::new();
    for (skill_id, mut row) in rows {
        let (_, msg) = skill_file(ctx, skill_id);
        let base = msg.get("Base").cloned().unwrap_or(Value::Null);
        let desc = msg
            .get("SkillDescConfig")
            .or_else(|| base.get("SkillDescConfig"))
            .cloned()
            .unwrap_or(Value::Null);
        row.insert("name".into(), json!(ctx.ftext_text(desc.get("SkillName"))));
        row.insert("icon".into(), json!(soft_path(desc.get("SkillIcon"))));
        row.insert("tags".into(), json!(skill_tags(ctx, skill_id)));
        row.insert("desc".into(), json!(skill_rank_descs(ctx, skill_id)));
        out.push(row);
    }
    out.sort_by_key(|r| r.get("id").and_then(Value::as_i64).unwrap_or(0));
    out
}

