pub fn extract_sprite_constellation(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows: Vec<Row> = Vec::new();
    for it in ctx.entries_of("Table/SpriteChs").iter() {
        let sid = it.get("ChsID").and_then(Value::as_i64).unwrap_or(0);
        let Some(ent) = ctx.dir_entry("Entity/ChsChessPiece", Some(sid)) else { continue };
        let Some(comps) = ent.get("Base").and_then(|b| b.get("InitComponents")).and_then(Value::as_array) else {
            continue;
        };
        let mut skill_ids: Vec<i64> = Vec::new();
        for (_t, comp) in components::iter_components(comps) {
            if comp.g_str("$type") != Some("/pd.AbilityEntityComponentConfig") {
                continue;
            }
            for s in [comp.get("NormalAttackSkill"), comp.get("UltimateSkill")] {
                if let Some(s) = s.and_then(Value::as_i64) {
                    skill_ids.push(s);
                }
            }
            if let Some(list) = comp.get("SkillList").and_then(Value::as_array) {
                for s in list.iter().filter_map(Value::as_i64) {
                    skill_ids.push(s);
                }
            }
        }
        skill_ids.sort_unstable();
        skill_ids.dedup();
        for skill_id in skill_ids {
            let ranks = skill_rank_descs(ctx, skill_id);
            for r in ranks {
                let rank = r.get("rank").and_then(Value::as_i64).unwrap_or(0);
                if rank <= 0 {
                    continue;
                }
                let mut row = Map::new();
                row.insert("id".into(), json!(format!("{sid}-{rank}")));
                row.insert("spriteId".into(), json!(sid));
                row.insert("rank".into(), json!(rank));
                row.insert("name".into(), json!(format!("Rank {rank}")));
                let effect = r.get("diffDesc").and_then(Value::as_str).unwrap_or("").to_string();
                row.insert("effectDesc".into(), json!(effect));
                rows.push(row);
            }
        }
    }
    rows.sort_by_key(|r| {
        (
            r.get("spriteId").and_then(Value::as_i64).unwrap_or(0),
            r.get("rank").and_then(Value::as_i64).unwrap_or(0),
        )
    });
    rows
}

