                        let mut a = Map::new();
                        a.insert("attribute".into(), json!(k));
                        let rv = v.get("RealValue").map(|x| x.py_str()).unwrap_or_default();
                        a.insert("value".into(), json!(rv));
                        actions.push(a);
                    }
                }
                if !actions.is_empty() {
                    let mut f = Map::new();
                    f.insert("quality".into(), json!(q));
                    f.insert("actions".into(), json!(actions));
                    fallback.push(f);
                }
            }
        }
        let name = ctx.ftext_text(it.get("Name"));
        let name = if name.is_empty() {
            it.get("Base")
                .and_then(|b| b.get("EditorName"))
                .and_then(Value::as_str)
                .unwrap_or("")
                .to_string()
        } else {
            name
        };
        let mut row = Map::new();
        row.insert("id".into(), json!(pid));
        row.insert("name".into(), json!(name));
        row.insert("ranks".into(), json!(ranks));
        row.insert("effect".into(), json!(fallback));
        rows.push(row);
    }
    rows
}

// =====================================================================
// 栖息地 / 物品
// =====================================================================
pub fn extract_habitat(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows = Vec::new();
    for it in ctx.entries_of("Table/Habitat").iter() {
        let mut row = Map::new();
        row.insert("id".into(), it.get("ID").cloned().unwrap_or(Value::Null));
        row.insert("name".into(), json!(ctx.ftext_text(it.get("HabitatName"))));
        row.insert(
            "spriteIds".into(),
            it.get("SpriteIDList").cloned().unwrap_or_else(|| json!([])),
        );
        rows.push(row);
    }
    rows
}

pub fn extract_item(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows = Vec::new();
    for it in ctx.entries_of("Table/Item").iter() {
        let mut row = Map::new();
        row.insert("id".into(), it.get("ID").cloned().unwrap_or(Value::Null));
        row.insert("type".into(), it.get("Type").cloned().unwrap_or(Value::Null));
        row.insert("subType".into(), it.get("SubType").cloned().unwrap_or(Value::Null));
        row.insert("name".into(), json!(ctx.ftext_text(it.get("ItemName"))));
        row.insert("icon".into(), json!(soft_path(it.get("ItemIcon"))));
        row.insert("rarity".into(), it.get("Rarity").cloned().unwrap_or(Value::Null));
        row.insert("desc".into(), json!(ctx.ftext_text(it.get("ItemDesc"))));
        row.insert("subDesc".into(), json!(ctx.ftext_text(it.get("ItemSubDesc"))));
        let sources: Vec<String> = it
            .get("FromList")
            .and_then(Value::as_array)
            .map(|a| a.iter().map(|f| ctx.ftext_text(f.get("Desc"))).collect())
            .unwrap_or_default();
        row.insert("sources".into(), json!(sources));
        rows.push(row);
    }
    rows
}

// =====================================================================
// 巅峰俱乐部
// =====================================================================
pub fn extract_pata_star_sprite(ctx: &ExtractContext) -> Vec<Row> {
    let common_by_id = ctx.entries_by_of("Table/SpriteCommon", "SpriteID");
    let chs_by_id = ctx.entries_by_of("Table/SpriteChs", "ChsID");
    let mut rows = Vec::new();
    let file = ctx.dir_entry("ChessGame/PataStarSprite", Some(1)).cloned().unwrap_or(Value::Null);
    let list = file.get("PataStarSpriteConfigList").and_then(Value::as_array).cloned().unwrap_or_default();
    for it in &list {
        let sid = it.get("SpriteID").and_then(Value::as_i64).unwrap_or(0);
        let common = common_by_id.get(&sid).cloned().unwrap_or(Value::Null);
        let chs = chs_by_id.get(&sid).cloned().unwrap_or(Value::Null);
        let traits = chs.get("Traits").and_then(Value::as_array).cloned().unwrap_or_default();
        let ldc = it.get("LawConditionDesc").and_then(Value::as_object).cloned().unwrap_or_default();
        let trait_id = traits.first().and_then(|t| t.get("TraitId")).cloned();
        let mut row = Map::new();
        row.insert("id".into(), it.get("ID").cloned().unwrap_or(Value::Null));
        row.insert("spriteId".into(), json!(sid));
        row.insert("artwork".into(), json!(soft_path(common.get("SpriteImage1024"))));
        row.insert("rarity".into(), chs.get("Rarity").cloned().unwrap_or(Value::Null));
        row.insert("traitId".into(), trait_id.unwrap_or(Value::Null));
        row.insert("brief".into(), json!(ctx.ftext_text(it.get("BriefDesc"))));
        row.insert("effect".into(), json!(ctx.ftext_text(ldc.get("0").and_then(|x| x.get("Desc")))));
        row.insert("effect100".into(), json!(ctx.ftext_text(ldc.get("1").and_then(|x| x.get("Desc")))));
        row.insert("effect200".into(), json!(ctx.ftext_text(ldc.get("2").and_then(|x| x.get("Desc")))));
        rows.push(row);
    }
    rows
}

pub fn extract_pata_law(ctx: &ExtractContext) -> Vec<Row> {
    let mut law_ids: Vec<i64> = Vec::new();
    let file = ctx.dir_entry("ChessGame/PataLawGroup", Some(1)).cloned().unwrap_or(Value::Null);
    let list = file.get("PataLawGroupConfigList").and_then(Value::as_array).cloned().unwrap_or_default();
    for grp in &list {
        if let Some(ids) = grp.get("LawIDList").and_then(Value::as_array) {
            for lid in ids.iter().filter_map(Value::as_i64) {
                if !law_ids.contains(&lid) {
                    law_ids.push(lid);
                }
            }
        }
    }
    let law_by_id = ctx.entries_by_of("Table/Law", "ID");
    let mut rows = Vec::new();
    for law_id in law_ids {
        let file = ctx.dir_entry("ChessGame/ChsLaw", Some(law_id)).cloned().unwrap_or(Value::Null);
        let rd = file.get("ChessLawRankDesc").and_then(Value::as_object).cloned().unwrap_or_default();
        let r0 = rd.get("0").cloned().unwrap_or(Value::Null);
        let table_law = law_by_id.get(&law_id).cloned().unwrap_or(Value::Null);
        let mut row = Map::new();
        row.insert("id".into(), json!(law_id));
        row.insert("name".into(), json!(ctx.ftext_text(r0.get("Name"))));
        row.insert("icon".into(), json!(soft_path(table_law.get("IconPath"))));
        row.insert("desc".into(), json!(ctx.ftext_text(r0.get("Desc"))));
        let rarity = if rd.is_empty() { Value::Null } else { json!(rd.len()) };
        row.insert("rarity".into(), rarity);
        rows.push(row);
    }
    rows
}

pub fn extract_pata_shop_item(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows = Vec::new();
    let file = ctx.dir_entry("ChessGame/PataShopItem", Some(1)).cloned().unwrap_or(Value::Null);
    let list = file.get("PataShopItemList").and_then(Value::as_array).cloned().unwrap_or_default();
    for it in &list {
        let desc = it.get("Desc").cloned().unwrap_or(Value::Null);
        let mut row = Map::new();
        row.insert("id".into(), it.get("ItemID").cloned().unwrap_or(Value::Null));
        row.insert("name".into(), json!(ctx.ftext_text(desc.get("Name"))));
        row.insert("icon".into(), json!(soft_path(it.get("ItemIcon"))));
        row.insert("rank".into(), it.get("ItemRank").cloned().unwrap_or(Value::Null));
        row.insert("desc".into(), json!(ctx.ftext_text(desc.get("Desc"))));
        rows.push(row);
    }
    rows
}

pub fn extract_pata_equip(ctx: &ExtractContext) -> Vec<Row> {
    let mut rows = Vec::new();
    for it in ctx.entries_of("Table/ChsEquipment").iter() {
        let eid = it.get("ID").and_then(Value::as_i64).unwrap_or(0);
        let file = ctx.dir_entry("ChessGame/ChsEquipment", Some(eid)).cloned().unwrap_or(Value::Null);
        let rank_desc = file.get("ChessEquipRankDesc").and_then(Value::as_object).cloned().unwrap_or_default();
        let rank_list = it.get("RankList").and_then(Value::as_object).cloned().unwrap_or_default();
        let mut keys: Vec<&String> = rank_list.keys().collect();
        keys.sort_by_key(|s| num_sort_key(s));
        let mut ranks: Vec<Row> = Vec::new();
        for rank in keys {
            let e = rank_list.get(rank).cloned().unwrap_or(Value::Null);
            let mut actions: Vec<Row> = Vec::new();
            if let Some(attr_map) = e.get("AttributeModifyActions").and_then(Value::as_object) {
                for (k, v) in attr_map {
                    let mut a = Map::new();
                    a.insert("attribute".into(), json!(k));
                    let rv = v.get("RealValue").map(|x| x.py_str()).unwrap_or_default();
                    a.insert("value".into(), json!(rv));
                    actions.push(a);
                }
            }
            let rd = rank_desc.get(rank.as_str()).or_else(|| rank_desc.get(rank.as_str())).cloned().unwrap_or(Value::Null);
            let mut item = Map::new();
            item.insert("rank".into(), json!(rank.parse::<i64>().unwrap_or(0)));
            item.insert("name".into(), json!(ctx.ftext_text(rd.get("Name"))));
            item.insert("effect".into(), json!(ctx.ftext_text(rd.get("Desc"))));
            item.insert("attributes".into(), json!(actions));
            ranks.push(item);
        }
        let r0_name = rank_desc.get("1").or_else(|| rank_desc.get("0")).cloned().unwrap_or(Value::Null);
        let mut row = Map::new();
        row.insert("id".into(), json!(eid));
        row.insert("shopRank".into(), Value::Null);
        row.insert("name".into(), json!(ctx.ftext_text(r0_name.get("Name"))));
        let icon = first_nonempty(&[&soft_path(it.get("IconPath")), &soft_path(it.get("IconPath64"))]);
        row.insert("icon".into(), json!(icon));
        row.insert("ranks".into(), json!(ranks));
        let attributes = ranks.first().map(|r| r.get("attributes").cloned().unwrap_or_else(|| json!([]))).unwrap_or_else(|| json!([]));
        row.insert("attributes".into(), attributes);
        row.insert("effect".into(), json!(ctx.ftext_text(r0_name.get("Desc"))));
        rows.push(row);
    }
    rows
}

// =====================================================================
// 专有名词 / 扭蛋
// =====================================================================
pub fn extract_glossary(_ctx: &ExtractContext) -> Vec<Row> {
    // 当前版本 Global/FTextGlossaryConfig.json Items 为空, 无词条数据源
    Vec::new()
}

pub fn extract_gacha(ctx: &ExtractContext) -> Vec<Row> {
    let pool_by_id = ctx.entries_by_of("Table/GachaPool", "GachaID");
    let addition = ctx.entries_of("Table/GachaRewardAdditionItem");
    let mut rows = Vec::new();
    for it in ctx.entries_of("Global/GachaBanner").iter() {
        let gid = it.get("GachaID").and_then(Value::as_i64).unwrap_or(0);
        let pool = pool_by_id.get(&gid).cloned().unwrap_or(Value::Null);
        let add_id = pool.get("AdditionID").and_then(Value::as_i64);
        let mut ups: Vec<Row> = Vec::new();
        if let Some(add_id) = add_id {
            for u in addition.iter() {
                if u.get("ID").and_then(Value::as_i64) == Some(add_id) && u.get("IsUp").and_then(Value::as_bool).unwrap_or(false) {
                    let item = u.get("Item").cloned().unwrap_or(Value::Null);
                    let mut up = Map::new();
                    up.insert("itemId".into(), item.get("ItemID").cloned().unwrap_or(Value::Null));
                    up.insert("num".into(), item.get("Num").cloned().unwrap_or(Value::Null));
                    ups.push(up);
                }
            }
        }
        let mut row = Map::new();
        row.insert("id".into(), json!(gid));
        row.insert("name".into(), json!(ctx.ftext_text(it.get("Name"))));
        row.insert("startTime".into(), Value::Null);
        row.insert("endTime".into(), Value::Null);
        row.insert("ups".into(), json!(ups));
        row.insert("icon".into(), json!(soft_path(it.get("LabelIcon"))));
        row.insert("poolType".into(), json!(zh(pool.get("GachaType"), &gacha_type_zh())));
        row.insert("gameVersion".into(), Value::Null);
        rows.push(row);
    }
    rows
}

// =====================================================================
// 调度
// =====================================================================
/// 按 table key 取提取函数.
pub fn extractor_fn(key: &str) -> Option<fn(&ExtractContext) -> Vec<Row>> {
    match key {
        "trait" => Some(extract_trait),
        "trainer" => Some(extract_trainer),
        "trainer_skill" => Some(extract_trainer_skill),
        "trainer_break" => Some(extract_trainer_break),
        "trainer_constellation" => Some(extract_trainer_constellation),
        "sprite" => Some(extract_sprite),
        "sprite_skill" => Some(extract_sprite_skill),
        "sprite_constellation" => Some(extract_sprite_constellation),
        "personality" => Some(extract_personality),
        "habitat" => Some(extract_habitat),
        "item" => Some(extract_item),
        "pata_star_sprite" => Some(extract_pata_star_sprite),
        "pata_law" => Some(extract_pata_law),
        "pata_shop_item" => Some(extract_pata_shop_item),
        "pata_equip" => Some(extract_pata_equip),
        "glossary" => Some(extract_glossary),
        "gacha" => Some(extract_gacha),
        _ => None,
    }
}

fn validate(table: &TableDef, rows: &[Row]) {
    let defined: std::collections::HashSet<&str> = table.fields.iter().map(|f| f.key.as_str()).collect();
    for row in rows {
        let extra: Vec<&str> = row.keys().map(String::as_str).filter(|k| !defined.contains(k)).collect();
        if !extra.is_empty() {
            warn!("table {}: 未定义字段 {:?}", table.key, extra);
        }
    }
}

/// 纯函数: 按 definitions 遍历调度全部提取器, 返回 {table key: rows}.
pub fn run_all(ctx: &ExtractContext) -> IndexMap<String, Vec<Row>> {
    let mut out: IndexMap<String, Vec<Row>> = IndexMap::new();
    for table in ALL_TABLES() {
        let Some(fn_) = extractor_fn(&table.key) else {
            warn!("no extractor for table {}", table.key);
            out.insert(table.key.clone(), Vec::new());
            continue;
        };
        let rows = fn_(ctx);
        validate(table, &rows);
        info!("{:<22} {:5} 条", table.key, rows.len());
        out.insert(table.key.clone(), rows);
    }
    out
}
