{"content": "//! HTML wiki 站点生成: 由 definitions + 导出数据生成静态可查看的 wiki.
//!
//! 输出 output/wiki/:
//!   index.html            总览(分类卡片 + 分类搜索)
//!   category-<key>.html   每个分类一页(内嵌数据, 卡片 + 搜索/筛选 + 详情弹窗)
//!   data/<key>.json       导出数据 + schema
//!   assets/               图片(从 ProjABC Assets 按需拷贝) + style.css + app.js

use std::collections::{HashMap, HashSet};
use std::path::Path;

use log::warn;
use serde_json::{Map, Value};

use super::definitions::TableDef;
use super::extract::{Row, Rows};

/// 行数据契约: 任意表行都是 str→object 的只读映射(具体形状见 extract.rs).
pub type Rows = IndexMapValue;

/// 数据: {table key: rows}.
pub type IndexMapValue = indexmap::IndexMap<String, Vec<Row>>;

pub const SPRITE_OUTPUT_PREFIX: &str = "Assets/Res/Prefabrication/UI/SpriteOutput/";

/// 常见属性中文名回退(AttributeFormats 未覆盖的基础属性).
pub const ATTR_ZH_FALLBACK: [(&str, &str); 18] = [
    ("EntityAttribute_MaxHPBase", "生命值"),
    ("EntityAttribute_AttackDamageBase", "攻击力"),
    ("EntityAttribute_AbilityPowerBase", "魔法强度"),
    ("EntityAttribute_ArmorBase", "护甲"),
    ("EntityAttribute_MagicResistanceBase", "魔法抗性"),
    ("EntityAttribute_AttackRateBase", "攻击速度"),
    ("EntityAttribute_MaxMPBase", "能量上限"),
    ("EntityAttribute_InitialMPBase", "初始能量"),
    ("EntityAttribute_MaxMPRatio", "能量上限(比例)"),
    ("EntityAttribute_TrainerPassivePowerBase", "共鸣"),
    ("EntityAttribute_TrainerActivePowerBase", "专注"),
    ("EntityAttribute_MPRegenBase", "能量回复"),
    ("EntityAttribute_TrainerPassivePowerGrowthAddend", "共鸣成长"),
    ("EntityAttribute_TrainerActivePowerGrowthAddend", "专注成长"),
    ("EntityAttribute_InitialMPAddend", "初始能量(加)"),
    ("EntityAttribute_TrainerActivePowerRatio", "专注(比例)"),
    ("EntityAttribute_MPRegenAddend", "能量回复(加)"),
    ("EntityAttribute_MaxHPRatio", "生命值(比例)"),
];

/// 递归收集所有以 SpriteOutput 开头的图片路径字符串.
fn iter_image_paths(obj: &Value, out: &mut HashSet<String>) {
    match obj {
        Value::Object(map) => {
            for v in map.values() {
                iter_image_paths(v, out);
            }
        }
        Value::Array(items) => {
            for v in items {
                iter_image_paths(v, out);
            }
        }
        Value::String(s) if s.starts_with(SPRITE_OUTPUT_PREFIX) => {
            out.insert(s.clone());
        }
        _ => {}
    }
}

/// 把数据引用的图片从 ProjABC Assets 拷贝到 out_dir/assets/(去 SpriteOutput 前缀).
pub fn copy_assets(data: &IndexMapValue, projabc_root: &Path, out_dir: &Path) -> usize {
    let src_root = projabc_root.join("Assets/Res/Prefabrication/UI/SpriteOutput");
    let mut paths: HashSet<String> = HashSet::new();
    for rows in data.values() {
        for row in rows {
            iter_image_paths(&Value::Object(row.clone()), &mut paths);
        }
    }
    let target = out_dir.join("assets");
    let _ = std::fs::create_dir_all(&target);
    let mut copied = 0usize;
    let mut sorted: Vec<&String> = paths.iter().collect();
    sorted.sort();
    for p in sorted {
        let lower = p.to_lowercase();
        if !(lower.ends_with(".png")
            || lower.ends_with(".jpg")
            || lower.ends_with(".jpeg")
            || lower.ends_with(".webp"))
        {
            continue;
        }
        let rel = &p[SPRITE_OUTPUT_PREFIX.len()..];
        let dst = target.join(rel);
        if dst.exists() {
            copied += 1;
            continue;
        }
        let src = src_root.join(rel);
        if src.exists() {
            if let Some(parent) = dst.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if std::fs::copy(&src, &dst).is_ok() {
                copied += 1;
            }
        }
    }
    copied
}

/// json → 内嵌 JS 安全字符串(避免 `</script>` 截断).
pub fn js_safe(value: &Value) -> String {
    crate::json_py::to_python_json_compact(value).replace("</", "<\\/")
}

/// 首页分类卡片最多展示的字段徽章数.
const BADGE_FIELDS: usize = 12;

fn category_page(table: &TableDef, rows: &[Row], out_dir: &Path) -> std::io::Result<()> {
    let table_json = js_safe(&serde_json::to_value(table).expect("table serialization"));
    let data_json = js_safe(&Value::Array(rows.iter().cloned().map(Value::Object).collect()));
    let html = format!(
        r#"<!doctype html><html lang="zh"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title} - ABC 数据 Wiki</title><link rel="stylesheet" href="assets/style.css"></head>
<body>
<header>
  <span class="logo">ABC 数据 Wiki</span>
  <a class="crumb" href="index.html">← 首页</a>
  <span class="crumb">{title}</span>
  <input id="q" type="search" placeholder="搜索 {title}… (名称/ID/文本)">
  <span class="crumb" id="cnt"></span>
</header>
<div class="wrap">
  <div class="chips" id="chips"></div>
  <div class="stat" id="stat"></div>
  <div class="grid" id="grid"></div>
</div>
<div class="overlay" id="ov"><div class="modal"><button class="close" onclick="document.getElementById('ov').classList.remove('show')">×</button>
<div id="modal-body"></div></div></div>
<script>window.__TABLE__ = {table_json}; window.__DATA__ = {data_json};</script>
<script src="assets/app.js"></script>
</body></html>"#,
        title = table.title,
        table_json = table_json,
        data_json = data_json,
    );
    std::fs::write(out_dir.join(format!("category-{}.html", table.key)), html)
}

fn index_page(tables: &[&TableDef], counts: &HashMap<String, usize>, out_dir: &Path) -> std::io::Result<()> {
    // 分组(按 group 首次出现序)
    let mut groups: Vec<(String, Vec<&TableDef>)> = Vec::new();
    for t in tables {
        match groups.iter_mut().find(|(g, _)| g == &t.group) {
            Some((_, list)) => list.push(t),
            None => groups.push((t.group.clone(), vec![*t])),
        }
    }
    let mut cards = String::new();
    let mut search_index: Vec<Map<String, Value>> = Vec::new();
    for (g, ts) in &groups {
        cards.push_str(&format!("<h2 style='margin-top:26px'>{g}</h2>"));
        for t in ts {
            let n = counts.get(&t.key).copied().unwrap_or(0);
            let badges: String = t
                .fields
                .iter()
                .take(BADGE_FIELDS)
                .map(|f| format!("<span class=\"badge\">{}</span>", f.zh))
                .collect();
            let ellipsis = if t.fields.len() > BADGE_FIELDS { "…" } else { "" };
            cards.push_str(&format!(
                r#"<a class="cat" href="category-{}.html">
<h3>{} <span class="n">{} 条</span></h3>
<div class="desc">{}</div>
<div>{}{}</div></a>"#,
                t.key, t.title, n, t.description, badges, ellipsis
            ));
            let mut item = Map::new();
            item.insert("t".into(), Value::String(t.key.clone()));
            item.insert("i".into(), Value::String(t.title.clone()));
            search_index.push(item);
        }
    }
    let index_json = js_safe(&Value::Array(search_index.into_iter().map(Value::Object).collect()));
    let html = format!(
        r#"<!doctype html><html lang="zh"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>ABC 数据 Wiki</title><link rel="stylesheet" href="assets/style.css"></head>
<body>
<header><span class="logo">ABC 数据 Wiki</span>
<input id="q" type="search" placeholder="搜索分类…">
<span class="crumb" id="cnt"></span></header>
<div class="wrap"><div id="hits"></div>{cards}</div>
<script>const INDEX = {index_json};</script>
<script src="assets/app.js"></script></body></html>"#,
        cards = cards,
        index_json = index_json,
    );
    std::fs::write(out_dir.join("index.html"), html)
}

/// Global/TrainerGlobalConfig.json → AttributeFormats 元数据 {key:{name,format}}.
fn attr_meta(projabc_root: &Path) -> Map<String, Value> {
    let mut meta: Map<String, Value> = Map::new();
    let p = projabc_root.join("BinaryData/Config/Global/TrainerGlobalConfig.json");
    if let Ok(text) = std::fs::read_to_string(&p) {
        if let Ok(d) = serde_json::from_str::<Value>(&text) {
            if let Some(formats) = d.get("AttributeFormats").and_then(Value::as_object) {
                for (k, v) in formats {
                    let name = v
                        .get("Name")
                        .and_then(|n| n.get("Context"))
                        .and_then(Value::as_str)
                        .map(str::to_string)
                        .unwrap_or_else(|| {
                            ATTR_ZH_FALLBACK
                                .iter()
                                .find(|(key, _)| *key == k)
                                .map(|(_, n)| n.to_string())
                                .unwrap_or_else(|| k.clone())
                        });
                    let format = v
                        .get("ValueFormat")
                        .and_then(Value::as_str)
                        .unwrap_or("")
                        .to_string();
                    let mut item = Map::new();
                    item.insert("name".into(), Value::String(name));
                    item.insert("format".into(), Value::String(format));
                    meta.insert(k.clone(), Value::Object(item));
                }
            }
        } else {
