    for table in tables {
        let rows = data.get(&table.key).cloned().unwrap_or_default();
        category_page(table, &rows, out_dir)?;
    }

    let size: u64 = walk_size(out_dir);
    Ok(WikiStats {
        pages: tables.len() + 1,
        images,
        size_mb: (size as f64 / 1024.0 / 1024.0 * 10.0).round() / 10.0,
    })
}

fn walk_size(dir: &Path) -> u64 {
    let mut total = 0u64;
    if let Ok(rd) = std::fs::read_dir(dir) {
        for entry in rd.flatten() {
            let p = entry.path();
            if p.is_dir() {
                total += walk_size(&p);
            } else if let Ok(m) = std::fs::metadata(&p) {
                total += m.len();
            }
        }
    }
    total
}

