{"content": "//! WIKI: table 定义 + 导出层 + 静态 wiki 站点生成.
//!
//! - definitions.rs: 需求表 → TableDef/FieldDef 声明(分类/字段/来源/路径)
//! - extract.rs:    导出层, 按 definitions 加载全部表, 输出按分类的 JSON
//! - html.rs:       由 definitions + 导出数据生成静态 wiki(index + 分类页)
//! - 顶层入口: build_wiki_site / export_roles / extract_trainers_demo /
//!   gen_frontend_data(供 CLI 调用)

pub mod definitions;
pub mod extract;
pub mod html;

use std::path::Path;

use extract::ExtractContext;
use html::Data;

/// 构建完整 wiki 站点; 返回统计 {pages, images, size_mb}.
pub fn build_wiki_site(
    bin_root: &Path,
    out_dir: &Path,
