    if type(a) != type(b): return (path, f'type {type(a).__name__} vs {type(b).__name__}', repr(a)[:80])
    if isinstance(a, dict):
        if a.keys() != b.keys(): return (path, 'keys', f'{set(a)^set(b)}')
        for k in a:
            d = first_diff(a[k], b[k], f'{path}.{k}' if path else k, depth+1)
            if d: return d
        return None
    if isinstance(a, list):
        if len(a) != len(b): return (path, f'len {len(a)} vs {len(b)}', '')
        for i, (x, y) in enumerate(zip(a, b)):
            d = first_diff(x, y, f'{path}[{i}]', depth+1)
