        data.push(lang_map_keys_to_codes(&value));
    }
    if let Some(parent) = out.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(
        out,
        crate::json_py::to_python_json(&serde_json::Value::Array(data), 1),
    )?;
    Ok(rows.len())
}

/// 递归移除 null 值键(与 pydantic `exclude_none=True` 一致; 数组元素不动).
fn strip_nulls(value: &serde_json::Value) -> serde_json::Value {
    use serde_json::Value;
    match value {
        Value::Object(map) => {
            let mut out = serde_json::Map::new();
            for (k, v) in map {
                if v.is_null() {
                    continue;
                }
                out.insert(k.clone(), strip_nulls(v));
            }
            Value::Object(out)
        }
        Value::Array(items) => Value::Array(items.iter().map(strip_nulls).collect()),
        other => other.clone(),
    }
