{"content": "//! wiki 层集成测试(镜像 Python test_wiki.py): 定义唯一性 / 提取器覆盖 /
//! 纯性 / 17 表行数与关键行断言 / html 站点构建。

use std::path::PathBuf;

use abc_db::wiki::definitions::{all_tables, table_by_key};
use abc_db::wiki::extract::{
    ExtractContext, extract_gacha, extract_glossary, extract_habitat, extract_item,
    extract_pata_equip, extract_pata_law, extract_pata_shop_item, extract_pata_star_sprite,
    extract_personality, extract_sprite, extract_sprite_constellation, extract_sprite_skill,
    extract_trainer, extract_trainer_break, extract_trainer_constellation,
    extract_trainer_skill, extract_trait, extractor_fn, run_all,
};
use abc_db::wiki::html::{build_site, js_safe};

fn bin_root() -> PathBuf {
    std::env::var_os("ABC_BIN_ROOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(
                "~/Perforce/ABC_Project_<client>/ProjABC/BinaryData/Config",
            )
        })
}

fn data_available() -> bool {
    bin_root().join("Table/TrainerChs.json").is_file()
}

fn ctx() -> ExtractContext {
    ExtractContext::open(bin_root())
}

// ------------------------------------------------------------ definitions
#[test]
fn definitions_unique_keys() {
    for table in all_tables() {
        let mut keys: Vec<&str> = table.fields.iter().map(|f| f.key.as_str()).collect();
        keys.sort();
        let mut dedup = keys.clone();
        dedup.dedup();
        assert_eq!(keys, dedup, "{} 字段 key 重复", table.key);
        assert!(!table.extractor.is_empty(), "{} 缺少 extractor", table.key);
    }
}

#[test]
fn definitions_extractor_resolves() {
    for table in all_tables() {
        assert!(extractor_fn(&table.key).is_some(), "{}: 未注册提取函数", table.key);
    }
}

// ------------------------------------------------------------ 纯性 / 缓存
#[test]
fn extractors_are_pure() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let first = extract_trainer(&ctx);
    let second = extract_trainer(&ctx);
    assert_eq!(first, second);
    assert_eq!(run_all(&ctx), run_all(&ctx));
}

#[test]
fn table_entries_cached() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let a = ctx.table_entries("Table/TrainerChs");
    let b = ctx.table_entries("Table/TrainerChs");
    assert!(std::sync::Arc::ptr_eq(&a, &b), "同一 (root, path) 两次调用应返回同一对象");
}

#[test]
fn dir_entry_missing_returns_none() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    assert!(ctx.dir_entry("Entity/ChsTrainer", Some(99999999)).is_none());
    assert!(ctx.dir_entry("Entity/ChsTrainer", None).is_none());
}

// ------------------------------------------------------------ extract
#[test]
fn extract_trait_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_trait(&ctx);
    assert!(rows.len() >= 20, "len {}", rows.len());
    let table = table_by_key("trait").unwrap();
    for row in &rows {
        for k in row.keys() {
            assert!(table.fields.iter().any(|f| &f.key == k), "未定义字段 {k}");
        }
    }
    // 强大(1021)应有分层描述
    let strong = rows.iter().find(|r| r.get("id").and_then(serde_json::Value::as_i64) == Some(1021)).unwrap();
    assert_eq!(strong.get("name").unwrap().as_str(), Some("强大"));
    let layers = strong.get("layers").unwrap().as_array().unwrap();
    assert!(layers.len() >= 3);
    assert!(strong.get("icon").unwrap().as_str().unwrap().ends_with(".png"));
}

#[test]
fn extract_trainer_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_trainer(&ctx);
    assert_eq!(rows.len(), 51);
    let table = table_by_key("trainer").unwrap();
    let blade = rows.iter().find(|r| r.get("id").and_then(serde_json::Value::as_i64) == Some(22200)).unwrap();
    for k in blade.keys() {
        assert!(table.fields.iter().any(|f| &f.key == k), "未定义字段 {k}");
    }
    assert_eq!(blade.get("name").unwrap().as_str(), Some("刃"));
    assert_eq!(blade.get("rarity").unwrap().as_i64(), Some(5));
    assert_eq!(blade.get("traitId").unwrap().as_i64(), Some(1021));
    // 同行精灵与同行技能
    let partner: Vec<i64> = blade
        .get("partnerSpriteIds")
        .unwrap()
        .as_array()
        .unwrap()
        .iter()
        .filter_map(serde_json::Value::as_i64)
        .collect();
    assert!(partner.contains(&210000));
    assert!(!blade.get("partnerSkillIds").unwrap().as_array().unwrap().is_empty());
    // 共鸣 1-30 级
    let passive = blade.get("passivePower").unwrap().as_array().unwrap();
    assert_eq!(passive.len(), 30);
    assert_eq!(passive[0].get("level").unwrap().as_i64(), Some(1));
    assert_eq!(passive[29].get("level").unwrap().as_i64(), Some(30));
    assert_eq!(blade.get("ultSkillId").unwrap().as_i64(), Some(22201));
    // 仅需求表字段
    assert!(blade.get("breaks").is_none());
    assert!(blade.get("constellations").is_none());
}

#[test]
fn extract_sprite_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_sprite(&ctx);
    assert!(rows.len() >= 100, "len {}", rows.len());
    let table = table_by_key("sprite").unwrap();
    let bun = rows.iter().find(|r| r.get("id").and_then(serde_json::Value::as_i64) == Some(670200)).unwrap();
    assert_eq!(bun.get("name").unwrap().as_str(), Some("奶丁汪"));
    assert_eq!(bun.get("rarity").unwrap().as_i64(), Some(4));
    assert_eq!(bun.get("traitId").unwrap().as_i64(), Some(1067));
    assert_eq!(bun.get("position").unwrap().as_str(), Some("前排"));
    assert_eq!(bun.get("damageType").unwrap().as_str(), Some("法伤"));
    assert_eq!(bun.get("battleType").unwrap().as_str(), Some("坦克"));
    assert!(bun.get("profession").unwrap().as_str().unwrap_or("").len() > 0);
    assert!(bun.get("obtain").unwrap().as_str().unwrap_or("").len() > 0);
    assert!(bun.get("story").unwrap().as_str().unwrap_or("").len() > 0);
    assert_eq!(bun.get("height").unwrap().as_i64(), Some(64));
    assert!(bun.get("energy").is_some());
    // 属性按级(60 级), 含突破前后数值
    let attrs = bun.get("attributes").unwrap().as_object().unwrap();
    let hp = attrs.get("EntityAttribute_MaxHPBase").unwrap().as_array().unwrap();
    assert_eq!(hp.len(), 60);
    let lv60 = hp.last().unwrap();
    assert!(lv60.get("before").unwrap().as_f64().unwrap() <= lv60.get("after").unwrap().as_f64().unwrap());
    // 异色 / 性格 / 栖息地
    assert!(!bun.get("shiny").unwrap().as_array().unwrap().is_empty());
    assert!(!bun.get("personalityIds").unwrap().as_array().unwrap().is_empty());
    assert!(bun.get("habitatIds").unwrap().is_array());
}

#[test]
fn extract_gacha_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_gacha(&ctx);
    assert!(rows.len() >= 3);
    let up = rows.iter().find(|r| r.get("id").and_then(serde_json::Value::as_i64) == Some(1002)).unwrap();
    assert!(!up.get("ups").unwrap().as_array().unwrap().is_empty(), "限定蛋池应有概率UP产出");
    assert_eq!(up.get("poolType").unwrap().as_str(), Some("心象限定"));
}

#[test]
fn extract_trainer_skill_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_trainer_skill(&ctx);
    assert!(rows.len() >= 40);
    let ult = rows.iter().find(|r| r.get("id").and_then(serde_json::Value::as_i64) == Some(22201)).unwrap();
    assert!(ult.get("skillType").unwrap().as_array().unwrap().iter().any(|t| t.as_str().unwrap().contains("心象技能")));
    assert!(ult.get("trainerIds").unwrap().as_array().unwrap().iter().any(|t| t.as_i64() == Some(22200)));
    assert!(ult.get("name").unwrap().as_str().unwrap_or("").len() > 0);
}

#[test]
fn extract_trainer_break_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_trainer_break(&ctx);
    assert!(rows.len() >= 200);
    let blade: Vec<&serde_json::Map<String, serde_json::Value>> =
        rows.iter().filter(|r| r.get("trainerId").and_then(serde_json::Value::as_i64) == Some(22200)).collect();
    assert!(!blade.is_empty());
    assert!(blade.iter().any(|r| !r.get("effect").unwrap().as_array().unwrap().is_empty()), "心识应有加成效果");
    assert!(rows.iter().any(|r| r.get("skillId").is_some_and(|v| v.as_i64().unwrap_or(0) != 0)), "存在技能型心识节点");
}

#[test]
fn extract_trainer_constellation_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_trainer_constellation(&ctx);
    assert!(rows.len() >= 80);
    let blade: Vec<&serde_json::Map<String, serde_json::Value>> =
        rows.iter().filter(|r| r.get("trainerId").and_then(serde_json::Value::as_i64) == Some(22200)).collect();
    assert_eq!(blade.len(), 6);
    for r in &blade {
        let rank = r.get("rank").unwrap().as_i64().unwrap();
        assert!((1..=6).contains(&rank));
        assert!(r.get("name").is_some());
    }
}

#[test]
fn extract_sprite_skill_rows() {
    if !data_available() {
        eprintln!("skip: data not synced");
        return;
    }
    let ctx = ctx();
    let rows = extract_sprite_skill(&ctx);
