    }
    let ctx = ctx();
    let star = extract_pata_star_sprite(&ctx);
    assert!(star.len() >= 30);
    assert!(star.iter().any(|r| r.get("effect100").unwrap().as_str().unwrap_or("").len() > 0));
    let law = extract_pata_law(&ctx);
    assert!(law.len() >= 100);
    assert!(law.iter().any(|r| r.get("name").unwrap().as_str().unwrap_or("").len() > 0));
    let shop = extract_pata_shop_item(&ctx);
