// ------------------------------------------------------------ html
#[test]
fn html_site_builds() {
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path();
    let tables: Vec<&abc_db::wiki::definitions::TableDef> =
        [table_by_key("trait").unwrap(), table_by_key("habitat").unwrap()].to_vec();
    let mut data = indexmap::IndexMap::new();
    data.insert(
        "trait".into(),
        vec![serde_json::from_value(serde_json::json!({
            "id": 1021,
            "name": "强大",
            "icon": "Assets/Res/Prefabrication/UI/SpriteOutput/IconTrait/IconTrait128/1021.png",
            "layers": [{"rank": 0, "desc": "层效果", "formulas": {}}],
            "desc": "描述",
        }))
        .unwrap()],
    );
    data.insert(
        "habitat".into(),
        vec![serde_json::from_value(serde_json::json!({"id": 1, "name": "伊亚镇", "spriteIds": [670200]})).unwrap()],
    );
    let stats = build_site(&data, &tables, out, &bin_root().parent().unwrap().parent().unwrap()).unwrap();
    assert_eq!(stats.pages, 3); // index + 2 分类
    assert!(out.join("index.html").is_file());
    assert!(out.join("category-trait.html").is_file());
    assert!(out.join("category-habitat.html").is_file());
    assert!(out.join("assets/app.js").is_file());
    assert!(out.join("assets/style.css").is_file());
    assert!(out.join("data/trait.json").is_file());
    // 页面内嵌数据可被解析
    let page = std::fs::read_to_string(out.join("category-trait.html")).unwrap();
    assert!(page.contains("window.__DATA__"));
    assert!(page.contains("强大"));
}

#[test]
fn js_safe_escapes_script_close() {
    let s = js_safe(&serde_json::json!({"x": "</script><b>"}));
    assert!(!s.contains("</script"));
    let restored: serde_json::Value = serde_json::from_str(&s.replace("<\\/", "</")).unwrap();
    assert_eq!(restored, serde_json::json!({"x": "</script><b>"}));
}
