{"content": "//! 黄金对拍测试: Rust 产物 vs Python 遗留实现产物(build/wiki-before/ 与
//! output/)。build/ 与 output/ 为 gitignored 本地产物, 目录缺失时自动跳过。

use std::path::Path;

use abc_db::wiki::extract::ExtractContext;
use abc_db::wiki::html::{Data, build_site};

fn bin_root() -> PathBuf {
    std::env::var_os("ABC_BIN_ROOT")
        .map(PathBuf::from)
        .unwrap_or_else(|| {
            PathBuf::from(
                "~/Perforce/ABC_Project_<client>/ProjABC/BinaryData/Config",
            )
        })
}

use std::path::PathBuf;

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// 语义比较两个 JSON 值(忽略键序).
fn json_equal(a: &serde_json::Value, b: &serde_json::Value) -> bool {
    match (a, b) {
        (serde_json::Value::Object(x), serde_json::Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| json_equal(v, w)))
        }
        (serde_json::Value::Array(x), serde_json::Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(v, w)| json_equal(v, w))
        }
        _ => a == b,
    }
}

#[test]
fn wiki_data_golden_parity() {
    let golden = repo_root().join("build/wiki-before/data");
    if !golden.is_dir() {
        eprintln!("skip: golden dir not present (run python build_wiki first)");
        return;
    }
    let ctx = ExtractContext::open(bin_root());
    let data = abc_db::wiki::extract::run_all(&ctx);
    let dir = tempfile::tempdir().unwrap();
    let tables: Vec<&abc_db::wiki::definitions::TableDef> =
        abc_db::wiki::definitions::all_tables().iter().collect();
    let projabc = bin_root().parent().unwrap().parent().unwrap();
    build_site(&data, &tables, dir.path(), projabc).unwrap();
    for table in abc_db::wiki::definitions::all_tables() {
        let py = std::fs::read_to_string(golden.join(format!("{}.json", table.key))).unwrap();
        let rs = std::fs::read_to_string(dir.path().join("data").join(format!("{}.json", table.key))).unwrap();
        // 字节级一致(键序/缩进/转义全部相同)
        assert_eq!(py, rs, "data/{}.json byte parity", table.key);
        let py_schema =
            std::fs::read_to_string(golden.join(format!("{}.schema.json", table.key))).unwrap();
        let rs_schema =
            std::fs::read_to_string(dir.path().join("data").join(format!("{}.schema.json", table.key))).unwrap();
        assert_eq!(py_schema, rs_schema, "data/{}.schema.json byte parity", table.key);
    }
}

#[test]
fn roles_golden_parity() {
    let golden = repo_root().join("output/roles.json");
    if !golden.is_file() {
        eprintln!("skip: golden roles.json not present");
        return;
    }
    let out = repo_root().join("build/roles-golden-check.json");
    abc_db::wiki::export_roles(&bin_root(), &out).unwrap();
    let py = std::fs::read_to_string(&golden).unwrap();
    let rs = std::fs::read_to_string(&out).unwrap();
    assert_eq!(py, rs, "roles.json byte parity");
    let _ = std::fs::remove_file(&out);
}

#[test]
fn registry_python_parity() {
    // 与 Python registry_to_json 产物对拍(build/registry_python.json, 本地生成)
    let py_path = repo_root().join("build/registry_python.json");
    if !py_path.is_file() {
        eprintln!("skip: build/registry_python.json not present (run python dump script)");
        return;
    }
    let py: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&py_path).unwrap()).unwrap();
    let rs: serde_json::Value =
        serde_json::from_str(include_str!("../src/registry_snapshot.json")).unwrap();
    for section in ["loaders", "super_fields", "refs", "enum_key_maps", "streaming_messages"] {
        let a = py.get(section).unwrap();
        let b = rs.get(section).unwrap();
        assert!(json_equal(a, b), "registry section {section} parity");
    }
}
