{"content": "//! 生成 wiki-app 前端数据并取回资源内容.
//!
//! 对应 python/scripts/gen_frontend_data.py:
//! 输入 output/wiki/data/*.json(导出层产物, FText 已为纯文本); 输出
//! wiki-app/src/generated/profiles.ts 与 wiki-app/public/assets/... 图片
//! (经 softpath content 能力取回: 本地 P4 workspace 拷贝, p4 print 兜底)。

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use regex::Regex;
use serde_json::{Map, Value};

use crate::softpath;
use crate::value_ext::JsonExt;

pub const SPRITE_PREFIX: &str = "Assets/Res/Prefabrication/UI/SpriteOutput/";

pub const ITEM_TYPE_ZH: [(&str, &str); 9] = [
    ("ITEM_TYPE_USABLE", "消耗品"),
    ("ITEM_TYPE_MATERIAL", "材料"),
    ("ITEM_TYPE_MISSION", "任务"),
    ("ITEM_TYPE_SPRITE", "精灵"),
    ("ITEM_TYPE_FURNITURE", "家具"),
    ("ITEM_TYPE_TRAINER", "心象"),
    ("ITEM_TYPE_VIRTUAL", "虚拟"),
    ("ITEM_TYPE_TRIAL_SPRITE", "试用精灵"),
    ("ITEM_TYPE_TRIAL_TRAINER", "试用心象"),
];

pub const ATTR_STAT_META: [(&str, &str, &str, &str); 6] = [
    ("EntityAttribute_MaxHPBase", "max-hp", "最大HP", "IconAttributeHPMAX.png"),
    ("EntityAttribute_AttackDamageBase", "attack", "攻击", "IconAttributeAttackDamage.png"),
    ("EntityAttribute_AbilityPowerBase", "ability-power", "法强", "IconAttributeAbilityPower.png"),
    ("EntityAttribute_ArmorBase", "armor", "护甲", "IconAttributeArmor.png"),
    (
        "EntityAttribute_MagicResistanceBase",
        "magic-resistance",
        "魔抗",
        "IconAttributeMagicResistance.png",
    ),
    ("EntityAttribute_AttackRateBase", "attack-speed", "攻速", "IconAttributeAttackRate.png"),
];

pub const TRAINER_STAT_ICONS: [(&str, &str); 5] = [
    ("共鸣", "IconAttributeTraitPoint.png"),
    ("专注", "IconAttributeAbilityPower.png"),
    ("所需能量", "IconAttributeMP.png"),
    ("能量回复", "IconAttributeAttackMPRecover.png"),
    ("初始能量", "IconAttributeTrainerIniMp.png"),
];

fn load(data_dir: &Path, key: &str) -> Vec<Value> {
    std::fs::read_to_string(data_dir.join(format!("{key}.json")))
        .ok()
        .and_then(|t| serde_json::from_str::<Value>(&t).ok())
        .and_then(|v| v.as_array().cloned())
        .unwrap_or_default()
}

fn clean_text(value: &str) -> String {
    if value.is_empty() {
        return String::new();
    }
    static TAG_RE: std::sync::OnceLock<Regex> = std::sync::OnceLock::new();
    static WS_RE: std::sync::OnceLock<Regex> = std::sync::OnceLock::new();
    let tag_re = TAG_RE.get_or_init(|| Regex::new(r"<[^>]+>").unwrap());
    let ws_re = WS_RE.get_or_init(|| Regex::new(r"[ \t\r\f\v]+").unwrap());
    let out = tag_re.replace_all(value, "");
    let out = out.replace('\n', " ");
    ws_re.replace_all(&out, " ").trim().to_string()
}

/// 数值 → 展示字符串: 整数不带小数, 其余最多 2 位(与 Python fmt_num 一致).
fn fmt_num(value: Option<&Value>) -> String {
    let Some(v) = value.and_then(Value::as_f64) else { return String::new() };
    if v == v.trunc() {
        format!("{}", v as i64)
    } else {
        let s = format!("{v:.2}");
        s.trim_end_matches('0').trim_end_matches('.').to_string()
    }
}

fn fmt_pct(value: Option<&Value>) -> String {
    let Some(v) = value.and_then(Value::as_f64) else { return String::new() };
    format!("{:.1}%", v * 100.0)
}

/// 配置 SoftObjectPath → wiki-app public 相对 URL(空串表示无图).
fn pub_img(config_path: Option<&Value>) -> String {
    match config_path.and_then(Value::as_str) {
        Some(p) if p.starts_with(SPRITE_PREFIX) => {
            format!("/assets/sprites/{}", &p[SPRITE_PREFIX.len()..])
        }
        _ => String::new(),
    }
}

/// 收集 (public 相对路径, 配置路径), 生成时统一用 softpath content 取回.
#[derive(Default)]
struct AssetFetcher {
    pairs: std::collections::BTreeMap<String, String>,
}

impl AssetFetcher {
    fn add(&mut self, public_rel: &str, config_path: Option<&Value>) {
        if let Some(p) = config_path.and_then(Value::as_str) {
            if p.starts_with(SPRITE_PREFIX) {
                self.pairs.entry(public_rel.to_string()).or_insert_with(|| p.to_string());
            }
        }
    }

    fn fetch_all(&self, projabc: &Path, public: &Path) -> (usize, usize) {
        let loader = softpath::AssetLoader {
            workspace_root: Some(projabc.to_path_buf()),
            p4_client: None,
        };
        let mut ok = 0usize;
        let mut missing = 0usize;
        for (public_rel, config_path) in &self.pairs {
            let dst = public.join("assets").join(public_rel);
            if dst.exists() {
                ok += 1;
                continue;
            }
            let Some(content) = loader.get_content(config_path) else {
                missing += 1;
                continue;
            };
            if let Some(parent) = dst.parent() {
                let _ = std::fs::create_dir_all(parent);
            }
            if std::fs::write(&dst, content).is_ok() {
                ok += 1;
            }
        }
        (ok, missing)
    }
}

/// 生成前端数据; data_dir = wiki 导出目录, gen_out = profiles.ts 输出,
/// public = wiki-app/public, projabc = P4 workspace 的 ProjABC 根.
pub fn gen(data_dir: &Path, gen_out: &Path, public: &Path, projabc: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let mut trait_by_id: HashMap<i64, Value> = HashMap::new();
    for t in load(data_dir, "trait") {
        if let Some(id) = t.get("id").and_then(Value::as_i64) {
            trait_by_id.insert(id, t);
        }
    }
    let mut trainer_by_id: HashMap<i64, Value> = HashMap::new();
    for t in load(data_dir, "trainer") {
        if let Some(id) = t.get("id").and_then(Value::as_i64) {
            trainer_by_id.insert(id, t);
        }
    }
    let mut sprite_by_id: HashMap<i64, Value> = HashMap::new();
    for s in load(data_dir, "sprite") {
        if let Some(id) = s.get("id").and_then(Value::as_i64) {
            sprite_by_id.insert(id, s);
        }
    }
    let trainer_skill_rows = load(data_dir, "trainer_skill");
    let sprite_skill_rows = load(data_dir, "sprite_skill");
    let trainer_const_rows = load(data_dir, "trainer_constellation");
    let sprite_const_rows = load(data_dir, "sprite_constellation");
    let items = load(data_dir, "item");

    let trait_name = |tid: Option<&Value>| -> String {
        tid.and_then(Value::as_i64)
            .and_then(|id| trainer_by_id.get(&id).or_else(|| trait_by_id.get(&id)))
            .and_then(|t| t.get("name"))
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string()
    };

    let mut assets = AssetFetcher::default();

    // 同行角色反查: 精灵ID → 角色
    let mut trainer_of_sprite: HashMap<i64, Value> = HashMap::new();
    for t in trainer_by_id.values() {
        if let Some(list) = t.get("partnerSpriteIds").and_then(Value::as_array) {
            for sid in list.iter().filter_map(Value::as_i64) {
                trainer_of_sprite.entry(sid).or_insert_with(|| t.clone());
            }
        }
    }

    // ------------------------------------------------------------ 角色
    let mut trainer_profiles: Map<String, Value> = Map::new();
    let mut avatar_catalog: Vec<Value> = Vec::new();
    for t in trainer_by_id.values() {
        let tid = t.get("id").and_then(Value::as_i64).unwrap_or(0);
        let slug = tid.to_string();
        let head_pub = format!("/assets/avatars/{slug}-head.png");
        let hero_pub = format!("/assets/avatars/{slug}-hero.png");
        assets.add(&format!("avatars/{slug}-head.png"), t.get("icon"));
        assets.add(&format!("avatars/{slug}-hero.png"), t.get("portrait"));
        let mut companions: Vec<Value> = Vec::new();
        if let Some(partner_list) = t.get("partnerSpriteIds").and_then(Value::as_array) {
            for sid in partner_list.iter().filter_map(Value::as_i64) {
                let s = sprite_by_id.get(&sid).cloned().unwrap_or(Value::Null);
                let s_head = format!("/assets/spirits/{sid}-head.png");
                assets.add(&format!("spirits/{sid}-head.png"), s.get("head"));
                let name = clean_text(s.get("name").and_then(Value::as_str).unwrap_or(&sid.to_string()));
                companions.push(serde_json::json!({
                    "name": name,
                    "artwork": s_head,
                    "affinity": trait_name(s.get("traitId")),
                    "role": s.get("profession").and_then(Value::as_str).unwrap_or(""),
                    "href": format!("/spirit/{sid}"),
                }));
            }
        }
        let passive = t.get("passivePower").and_then(Value::as_array).cloned().unwrap_or_default();
        let active = t.get("activePower").and_then(Value::as_array).cloned().unwrap_or_default();
        let stat_icon = |key: &str| -> String {
            format!("/assets/IconFunctional64/{}", TRAINER_STAT_ICONS.iter().find(|(k, _)| *k == key).map(|(_, i)| *i).unwrap_or(""))
        };
        let stats = serde_json::json!([
            {"label": "共鸣", "level1": fmt_pct(passive.first().and_then(|r| r.get("value"))), "level30": fmt_pct(passive.last().and_then(|r| r.get("value"))), "icon": stat_icon("共鸣")},
            {"label": "专注", "level1": fmt_pct(active.first().and_then(|r| r.get("value"))), "level30": fmt_pct(active.last().and_then(|r| r.get("value"))), "icon": stat_icon("专注")},
            {"label": "所需能量", "level1": fmt_num(t.get("maxMp")), "icon": stat_icon("所需能量")},
            {"label": "能量回复", "level1": fmt_num(t.get("mpRegen")), "icon": stat_icon("能量回复")},
            {"label": "初始能量", "level1": fmt_num(t.get("initialMp")), "icon": stat_icon("初始能量")},
        ]);
        // 技能: 心象 → 元理 → 同行
        let mut skills: Vec<Value> = Vec::new();
        let mut skill_rows: Vec<&Value> = trainer_skill_rows
            .iter()
            .filter(|r| r.get("trainerIds").and_then(Value::as_array).is_some_and(|a| a.iter().any(|x| x.as_i64() == Some(tid))))
            .collect();
        skill_rows.sort_by_key(|r| {
            let st = r.get("skillType").and_then(Value::as_array).and_then(|a| a.first()).and_then(Value::as_str).unwrap_or("");
            if st.contains("心象") {
                0
            } else if st.contains("元理") {
                1
            } else {
                2
            }
        });
        for row in skill_rows {
            let skill_id = row.get("id").and_then(Value::as_i64).unwrap_or(0);
            let skill_icon = format!("/assets/skills/{skill_id}.png");
            assets.add(&format!("skills/{skill_id}.png"), row.get("icon"));
            let ranks = row.get("rankDescs").and_then(Value::as_array).cloned().unwrap_or_default();
            let mut notes: Vec<Value> = Vec::new();
            for r in ranks.iter().filter(|r| r.get("rank").and_then(Value::as_i64).unwrap_or(0) >= 1) {
                let diff = r.get("diffDesc").and_then(Value::as_str).unwrap_or("");
                let desc = r.get("desc").and_then(Value::as_str).unwrap_or("");
                let text = if !diff.is_empty() { diff } else { desc };
                if !text.is_empty() {
                    notes.push(serde_json::json!({
                        "label": format!("{}阶", r.get("rank").and_then(Value::as_i64).unwrap_or(0)),
                        "value": clean_text(text),
                    }));
                }
            }
            let name = row.get("name").and_then(Value::as_str).unwrap_or(&skill_id.to_string()).to_string();
            let st0 = row.get("skillType").and_then(Value::as_array).and_then(|a| a.first()).and_then(Value::as_str).unwrap_or("").to_string();
            let desc0 = ranks.first().and_then(|r| r.get("desc")).and_then(Value::as_str).unwrap_or("").to_string();
            skills.push(serde_json::json!({
                "id": skill_id.to_string(),
                "name": if name.is_empty() { skill_id.to_string() } else { name },
                "type": st0,
                "description": clean_text(&desc0),
                "image": skill_icon,
                "notes": notes,
            }));
        }
        let heart: Vec<Value> = trainer_const_rows
            .iter()
            .filter(|r| r.get("trainerId").and_then(Value::as_i64) == Some(tid))
            .map(|r| {
                let rank = r.get("rank").and_then(Value::as_i64).unwrap_or(0);
                let name = r.get("name").and_then(Value::as_str).unwrap_or("").to_string();
                serde_json::json!({
                    "id": format!("{tid}-{rank}"),
                    "stage": format!("{rank:02}"),
                    "name": if name.is_empty() { format!("Rank {rank}") } else { name },
                    "effect": {
                        let eff = clean_text(r.get("effectDesc").and_then(Value::as_str).unwrap_or(""));
                        if eff.is_empty() { "—".to_string() } else { eff }
                    },
                })
            })
            .collect();
        let profile = serde_json::json!({
            "character": {
                "name": {
                    let n = clean_text(t.get("name").and_then(Value::as_str).unwrap_or(&slug));
                    if n.is_empty() { slug.clone() } else { n }
                },
                "affinity": trait_name(t.get("traitId")),
                "role": "",
                "rarity": t.get("rarity").and_then(Value::as_i64).unwrap_or(0),
                "companions": companions,
                "avatar": head_pub,
                "artwork": hero_pub,
            },
            "battle": {
                "title": "战斗",
                "attributesTitle": "属性",
                "stats": stats,
                "skillsTitle": "技能",
                "skills": skills,
                "heartTitle": "心缘",
                "heart": heart,
                "heartShowcase": {"options": [], "selected": "", "image": ""},
            },
            "content": {"story": [], "gallery": {"categories": [], "videos": []}, "guides": []},
        });
        trainer_profiles.insert(slug.clone(), profile);
        let rarity = t.get("rarity").and_then(Value::as_i64).unwrap_or(0);
        let entry_name = clean_text(t.get("name").and_then(Value::as_str).unwrap_or(&slug));
        let mut entry = serde_json::json!({
            "id": slug,
            "kind": "avatar",
            "name": if entry_name.is_empty() { slug.clone() } else { entry_name },
            "affinity": trait_name(t.get("traitId")),
            "role": "",
            "rarity": rarity,
            "source": "已建详情",
            "detailHref": format!("/avatar/{slug}"),
            "cardArt": {"character": hero_pub},
            "cardTone": if rarity >= 5 { "gold" } else { "purple" },
        });
        if rarity <= 0 {
            continue; // 未实装/占位角色不进目录
        }
        if !companions.is_empty() {
            entry
                .as_object_mut()
                .unwrap()
                .insert("featuredCompanion".into(), serde_json::json!({"name": companions[0]["name"], "artwork": companions[0]["artwork"]}));
        }
        avatar_catalog.push(entry);
    }

    // ------------------------------------------------------------ 精灵
    // 满级域最大值(雷达图): 各属性 60 级 after 的最大值向上取整
    let mut domain_max: Map<String, f64> = Map::new();
    for s in sprite_by_id.values() {
        let attrs = s.get("attributes").and_then(Value::as_object);
        if let Some(attrs) = attrs {
            for (key, _, _, _) in ATTR_STAT_META {
                if let Some(levels) = attrs.get(key).and_then(Value::as_array) {
                    if let Some(last) = levels.last() {
                        let after = last.get("after").and_then(Value::as_f64).unwrap_or(0.0);
                        let cur = domain_max.get(key).copied().unwrap_or(0.0);
                        if after > cur {
                            domain_max.insert(key.to_string(), after);
                        }
                    }
                }
            }
        }
    }

    let mut spirit_profiles: Map<String, Value> = Map::new();
    let mut spirit_catalog: Vec<Value> = Vec::new();
    for s in sprite_by_id.values() {
        let sid = s.get("id").and_then(Value::as_i64).unwrap_or(0);
        let slug = sid.to_string();
        let hero_pub = format!("/assets/spirits/{slug}-hero.png");
        let head_pub = format!("/assets/spirits/{slug}-head.png");
        assets.add(&format!("spirits/{slug}-hero.png"), s.get("artwork"));
        assets.add(&format!("spirits/{slug}-head.png"), s.get("head"));
        let trainer = trainer_of_sprite.get(&sid).cloned();
        let trainer_head = trainer
            .as_ref()
            .map(|t| format!("/assets/avatars/{}-head.png", t.get("id").and_then(Value::as_i64).unwrap_or(0)))
            .unwrap_or_default();
        if let Some(t) = &trainer {
            assets.add(&format!("avatars/{}-head.png", t.get("id").and_then(Value::as_i64).unwrap_or(0)), t.get("icon"));
        }
        let attrs = s.get("attributes").and_then(Value::as_object).cloned().unwrap_or_default();
        let levels = [1i64, 10, 20, 30, 40, 50, 60];
        let mut stats_by_level: Map<String, Value> = Map::new();
        for lv in levels {
            let mut stat_list: Vec<Value> = Vec::new();
            for (key, stat_id, label, icon_name) in ATTR_STAT_META {
                let entry = attrs
                    .get(key)
                    .and_then(Value::as_array)
                    .and_then(|a| a.iter().find(|e| e.get("level").and_then(Value::as_i64) == Some(lv)));
                let Some(entry) = entry else { continue };
                let mut stat = serde_json::json!({
                    "id": stat_id,
                    "label": label,
                    "icon": format!("/assets/IconFunctional64/{icon_name}"),
                    "before": fmt_num(entry.get("before")),
                    "after": fmt_num(entry.get("after")),
                });
                if lv == 60 {
                    let after = entry.get("after").and_then(Value::as_f64).unwrap_or(0.0);
                    let domain = domain_max.get(key).copied().unwrap_or(1.0);
                    stat.as_object_mut().unwrap().insert("radar".into(), serde_json::json!({"value": after, "domainMax": domain}));
                }
                stat_list.push(stat);
            }
            stats_by_level.insert(lv.to_string(), Value::Array(stat_list));
        }
        let mut battle_skills: Vec<Value> = Vec::new();
        let mut skill_rows: Vec<&Value> = sprite_skill_rows
            .iter()
            .filter(|r| r.get("spriteIds").and_then(Value::as_array).is_some_and(|a| a.iter().any(|x| x.as_i64() == Some(sid))))
            .collect();
        skill_rows.sort_by_key(|r| r.get("id").and_then(Value::as_i64).unwrap_or(0).to_string());
        for row in skill_rows {
            let skill_id = row.get("id").and_then(Value::as_i64).unwrap_or(0);
            let s_icon = format!("/assets/skills/{skill_id}.png");
            assets.add(&format!("skills/{skill_id}.png"), row.get("icon"));
            let ranks = row.get("desc").and_then(Value::as_array).cloned().unwrap_or_default();
            let name = row.get("name").and_then(Value::as_str).unwrap_or(&skill_id.to_string()).to_string();
            let tags = row.get("tags").and_then(Value::as_array);
            let type_ = tags.and_then(|a| a.first()).and_then(Value::as_str).unwrap_or("战斗技能").to_string();
            let active = ranks.first().and_then(|r| r.get("desc")).and_then(Value::as_str).unwrap_or("").to_string();
            battle_skills.push(serde_json::json!({
                "name": if name.is_empty() { skill_id.to_string() } else { name },
                "type": type_,
                "icon": s_icon,
                "active": clean_text(&active),
            }));
        }
        let bonds: Vec<Value> = sprite_const_rows
            .iter()
            .filter(|r| r.get("spriteId").and_then(Value::as_i64) == Some(sid))
            .map(|r| {
                let eff = clean_text(r.get("effectDesc").and_then(Value::as_str).unwrap_or(""));
                serde_json::json!({
                    "stage": r.get("rank").and_then(Value::as_i64).unwrap_or(0),
                    "effect": if eff.is_empty() { "—".to_string() } else { eff },
                    "artwork": "",
                })
            })
            .collect();
        let mut variants: Vec<Value> = Vec::new();
        if let Some(shinies) = s.get("shiny").and_then(Value::as_array) {
            for (i, sh) in shinies.iter().enumerate() {
                let v_head = format!("/assets/spirits/{slug}-variant-{}.png", i + 1);
                assets.add(
                    &format!("spirits/{slug}-variant-{}.png", i + 1),
                    sh.get("head").or_else(|| sh.get("image1024")),
                );
                let sh_name = sh.get("name").and_then(Value::as_str).unwrap_or("").to_string();
                variants.push(serde_json::json!({
                    "id": format!("variant-{:02}", i + 1),
                    "label": if sh_name.is_empty() { format!("异色 {}", i + 1) } else { sh_name },
                    "artwork": v_head,
                }));
            }
        }
        let rarity = s.get("rarity").and_then(Value::as_i64).unwrap_or(0);
        let formation = s.get("position").and_then(Value::as_str).unwrap_or("前排").to_string();
        let name = clean_text(s.get("name").and_then(Value::as_str).unwrap_or(&slug));
        let story = s.get("story").and_then(Value::as_str).unwrap_or("");
        let trainer_ref = trainer.as_ref();
        let profile = serde_json::json!({
            "id": slug,
            "source": "verified",
            "overview": {
                "name": if name.is_empty() { slug.clone() } else { name },
                "rarity": rarity,
                "formation": if formation == "前排" || formation == "后排" { formation } else { "前排".to_string() },
                "affinity": trait_name(s.get("traitId")),
                "role": s.get("profession").and_then(Value::as_str).unwrap_or("").to_string()
                    .pipe_else(s.get("battleType").and_then(Value::as_str).unwrap_or("")),
                "metrics": [
                    {"label": "能量", "value": fmt_num(s.get("energy")), "unit": ""},
                    {"label": "身高", "value": fmt_num(s.get("height")), "unit": ""},
                ],
                "summary": clean_text(s.get("intro").and_then(Value::as_str).unwrap_or("")),
                "artwork": hero_pub,
                "companionCharacter": {
                    "name": trainer_ref.and_then(|t| t.get("name")).and_then(Value::as_str).unwrap_or(""),
                    "avatar": trainer_head,
                    "href": trainer_ref.map(|t| format!("/avatar/{}", t.get("id").and_then(Value::as_i64).unwrap_or(0))).unwrap_or_default(),
                },
                "acquisition": clean_text(s.get("obtain").and_then(Value::as_str).unwrap_or("")),
            },
            "battle": {
                "levels": levels,
                "defaultLevel": 60,
                "maxLevel": 60,
                "statsByLevel": stats_by_level,
                "skills": battle_skills,
                "bonds": bonds,
            },
            "explorationSkills": [],
            "variants": variants,
            "guides": [],
            "story": if story.is_empty() { Value::Array(vec![]) } else { Value::Array(vec![Value::String(clean_text(story))]) },
            "gallery": [],
        });
        spirit_profiles.insert(slug.clone(), profile);
        if rarity <= 0 {
            continue; // 未实装/占位精灵不进目录
        }
        let cat_name = clean_text(s.get("name").and_then(Value::as_str).unwrap_or(&slug));
        spirit_catalog.push(serde_json::json!({
            "id": slug,
            "kind": "spirit",
            "name": if cat_name.is_empty() { slug } else { cat_name },
            "affinity": trait_name(s.get("traitId")),
            "role": s.get("profession").and_then(Value::as_str).unwrap_or(""),
            "rarity": rarity,
            "source": "已建详情",
            "detailHref": format!("/spirit/{slug}"),
            "spiritArt": hero_pub,
            "spiritTone": if rarity >= 5 { "gold" } else if rarity >= 4 { "purple" } else { "blue" },
        }));
    }

    // ------------------------------------------------------------ 物品
    let mut item_profiles: Map<String, Value> = Map::new();
    for it in items {
        let iid = it.get("id").and_then(Value::as_i64).unwrap_or(0).to_string();
        let icon_pub = format!("/assets/items/{iid}.png");
        assets.add(&format!("items/{iid}.png"), it.get("icon"));
        let name = clean_text(it.get("name").and_then(Value::as_str).unwrap_or(&iid));
        let type_ = it.get("type").and_then(Value::as_str).unwrap_or("");
        let category = ITEM_TYPE_ZH
            .iter()
            .find(|(k, _)| *k == type_)
            .map(|(_, v)| v.to_string())
            .unwrap_or_else(|| type_.to_string());
        item_profiles.insert(
            iid.clone(),
            serde_json::json!({
                "id": iid,
                "name": if name.is_empty() { iid.clone() } else { name },
                "category": category,
                "rarity": it.get("rarity").and_then(Value::as_i64).unwrap_or(1),
                "artwork": icon_pub,
                "cardFooter": "",
                "summary": clean_text(it.get("desc").and_then(Value::as_str).unwrap_or("")),
                "description": clean_text(it.get("subDesc").and_then(Value::as_str).unwrap_or("")),
                "flavorText": [],
                "acquisition": it
                    .get("sources")
                    .and_then(Value::as_array)
                    .map(|a| a.iter().filter(|x| !x.is_null() && x.as_str().unwrap_or("") != "").cloned().collect::<Vec<_>>())
                    .unwrap_or_default(),
            }),
        );
    }

    // ------------------------------------------------------------ 写出 TS
    std::fs::create_dir_all(gen_out)?;
    let trait_names: Map<String, Value> = trait_by_id
        .iter()
        .filter(|(_, t)| t.get("name").and_then(Value::as_str).is_some_and(|n| !n.is_empty()))
        .map(|(id, t)| (id.to_string(), t.get("name").cloned().unwrap_or(Value::Null)))
        .collect();
    let js = |v: &Value| crate::json_py::to_python_json_compact(v);
    let parts = vec![
        "// AUTO-GENERATED by abc-db frontend-data — 请勿手改".to_string(),
        "import type { CharacterProfile } from \"../data\";".into(),
        "import type { SpiritProfile } from \"../spirit-data\";".into(),
        "import type { ItemProfile } from \"../item-data\";".into(),
        "import type { CatalogEntry } from \"../home-data\";".into(),
        String::new(),
        format!(
            "export const traitNames: Record<number, string> = {};",
            js(&Value::Object(trait_names))
        ),
        format!("export const trainerProfiles: Record<string, CharacterProfile> = {};", js(&Value::Object(trainer_profiles))),
        format!("export const spiritProfiles: Record<string, SpiritProfile> = {};", js(&Value::Object(spirit_profiles))),
        format!("export const itemProfiles: Record<string, ItemProfile> = {};", js(&Value::Object(item_profiles))),
        format!("export const avatarCatalog: CatalogEntry[] = {};", js(&Value::Array(avatar_catalog))),
        format!("export const spiritCatalog: CatalogEntry[] = {};", js(&Value::Array(spirit_catalog))),
        String::new(),
    ];
    std::fs::write(gen_out.join("profiles.ts"), parts.join("\n"))?;

    // ------------------------------------------------------------ 资源内容
    let (ok, missing) = assets.fetch_all(projabc, public);
    println!("角色 {} / 精灵 {} / 物品 {}", trainer_profiles.len(), spirit_profiles.len(), item_profiles.len());
    println!("首页目录: 心象 {} / 精灵 {}", avatar_catalog.len(), spirit_catalog.len());
    println!("资源取回: 成功 {ok} 个, 缺失 {missing} 个 → {}", gen_out.display());
    Ok(())
}

/// 前端数据生成入口(默认路径: output/wiki/data → wiki-app).
pub fn gen_frontend_data(bin_root: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let repo = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let data_dir = repo.join("output/wiki/data");
    let gen_out = repo.join("wiki-app/src/generated");
    let public = repo.join("wiki-app/public");
    let projabc = bin_root.parent().and_then(|p| p.parent()).unwrap_or(bin_root);
    gen(&data_dir, &gen_out, &public, projabc)
}
