{"command": "python3 - <<'EOF'
path = 'src/wiki/mod.rs'
text = open(path).read()
start = text.index('/// 心象名称/原画/技能端到端提取示例(对应 python/examples/extract_trainers.py).')
end = text.index('/// 生成 wiki-app 前端数据(profiles.ts + 资源取回).')
new_demo = '''/// 心象名称/原画/技能端到端提取示例(对应 python/examples/extract_trainers.py).
pub fn extract_trainers_demo(bin_root: &Path) -> Result<(), Box<dyn std::error::Error>> {
    use crate::components;
    use crate::ftext;
    use crate::jsonconfig::JsonConfig;
    use crate::textmap::TextMapIndex;

    let jc = JsonConfig::open(bin_root);
    let textmap = TextMapIndex::open(bin_root);
    let ability_component = "ChsTrainerAbilityEntityComponentConfig";

    let skill_name = |jc: &JsonConfig, loader_path: &str, skill_id: i64| -> String {
        let Some(loader) = jc.registry.loader_by_path(loader_path) else {
            return format!("<no loader {loader_path}>");
        };
        let msg = match jc.load_dir_entry(loader, skill_id) {
            Ok(m) => m,
            Err(_) => return format!("<missing {skill_id}>"),
        };
        let name = msg
            .get("Name")
            .or_else(|| msg.get("Base").and_then(|b| b.get("Name")))
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        if name.is_empty() {
            "<unnamed>".to_string()
        } else {
            name
        }
    };

    let Some(trainer_loader) = jc.registry.loader_by_path("Table/TrainerChs") else {
        return Err("TrainerChs loader not found".into());
    };
    let entries = jc.load_single_entries(trainer_loader)?;
    println!("心象总数: {}\\n", entries.len());
    let entity_loader = jc.registry.loader_by_path("Entity/ChsTrainer");

    for entry in &entries {
        let mut skills: Vec<String> = Vec::new();
        if let Some(entity_config_id) = entry.get("EntityConfigID").and_then(Value::as_i64) {
            let entity = entity_loader.and_then(|l| jc.load_dir_entry(l, entity_config_id).ok());
            if let Some(entity) = entity {
                let comps = entity
                    .get("Base")
                    .and_then(|b| b.get("InitComponents"))
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                for (type_name, comp) in components::iter_components(&comps) {
                    if type_name != ability_component {
                        continue;
                    }
                    if let Some(ult) = comp.get("UltSkill").and_then(Value::as_i64) {
                        if ult != 0 {
                            skills.push(format!(
                                "大招[{}]",
                                skill_name(&jc, "ChessGame/ChsManualSkill", ult)
                            ));
                        }
                    }
                    if let Some(cds) = comp.get("ConditionSkills").and_then(Value::as_array) {
                        for cond in cds {
                            if let Some(sid) = cond.get("SkillID").and_then(Value::as_i64) {
                                if sid != 0 {
                                    skills.push(format!(
                                        "技能[{}]",
                                        skill_name(&jc, "ChessGame/ChsSkill", sid)
                                    ));
                                }
                            }
                        }
                    }
                }
            }
        }
        let name = entry.get("Name").cloned().unwrap_or(Value::Null);
        let langs = ftext::ftext_langs(Some(&name), &textmap);
        let text = ftext::ftext_text(Some(&name), Some(&textmap));
        let poster = entry
            .get("Poster")
            .and_then(|p| p.get("Path"))
            .and_then(Value::as_str)
            .filter(|p| !p.is_empty())
            .unwrap_or("-");
        let skill_text = if skills.is_empty() {
            "(未配置)".to_string()
        } else {
            skills.join(" ")
        };
        println!(
            "心象 {}: 名称={}({}语) 原画={} 技能={}",
            entry.get("ID").and_then(Value::as_i64).unwrap_or(0),
            text,
            langs.len(),
            poster,
            skill_text
        );
    }
    Ok(())
}

'''
text = text[:start] + new_demo + text[end:]
open(path, 'w').write(text)
print('ok')
